/* 平成19年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h19.committeeSessions.push(...[{"id":"h19-20071005-4","meetingId":"h19-c-settlement","date":"2007年10月5日","dateIso":"2007-10-05","committee":"決算特別委員会","time":"午前１０時０３分～午後７時０９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を173件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１８年度品川区一般会計歳入歳出決算","agenda":"平成１８年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"私のほうは、１２９ページの区民健康審査、１３０ページにあります健康センター事業、１３２ページにありますマイバッグ運動推進事業、１３８ページになります産業振興事業、この４点についてお伺いをしてまいりたいと思います。こういった専門家の方のお話も踏まえてご紹介させていただいたご指摘の点を踏まえて、行政のほうで聴力検査の有効性についてご見解を伺えればと思います。","respondent":"太田健康課長、倉橋品川区保健所保健サービス課長","answer":"最初に、私のほうから、区民健診に現在聴力検査は入ってございません。ご案内のとおり、区民健診は、今年までは老人保健法に基づく区民健診ということで、主として成人病予防対策という観点から検査項目が実施されているところです。問診票あるいは通常の問診、そのような形の中で有効に発見していく方策を検討してまいりたいというふうに考えております。","voiceIndex":6,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"続きまして、マイバッグ運動推進事業についてお伺いします。環境対策への取り組みにおいて、この品川区の行政はじめ、企業、それぞれ個人等、いろいろな取り組みが行われております。やはりこれまでのマイバッグ運動、私の感覚も踏まえて成果があると思っておるんですが、この辺を行政として成果の点をお伺いしたいのと、関連する環境施策を主なもの数点で構いませんのでお聞かせください。","respondent":"田村環境課長","answer":"それ以外の事業ですが、商店街連合会では、もったいない風呂敷だとか、あるいは区で実施しておりますＥＣＯフェスティバルに展示して、できる機会を十分に利用してＰＲ活動をして。","voiceIndex":9,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"今後という点で考えて、やはりこの変化や進展とか、応用することで関心も盛り上がりももっとあるかなと思うんですが、本当に対象となる参加をしてくれる区民の拡大という点で、今後何か新しい企画だとか、取り組みがあるか、やはり効果、成果、意義の点から、今後についての方向性を最後にお伺いしたいと思います。","respondent":"田村環境課長","answer":"やはり環境を考える場合、押しつけでなく、やはりこれから次代を担うお子さんたちが。","voiceIndex":11,"id":"exchange-003"},{"speaker":"渡辺委員","kind":"質問","question":"産業振興事業のところでお伺いしたいと思います。こちらも区商連のことですとかを伺いたいと思います。そのような背景を踏まえてかと思いますが、商店街にぎわい創出事業が好評の中、継続されている、いいものであるから継続されていると私は認識しております。そういった中で、このにぎわい創出事業の成果の点もそうなんですが、この小規模商店街支援の事業内容に大変関心があるのでお聞かせください。","respondent":"金子産業振興課長","answer":"商店街への支援のうちの小規模商店街への私どもの支援事業の内容というお尋ねですけれども、ご案内のとおり、小規模商店街、なかなか人員の問題、あるいは活力の問題ということから、イベント等を実施したくても、なかなか企画、実施ができない。","voiceIndex":13,"id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今言ったポイントですと、やはり商店街事務所がないというような小規模の中で、商店街運営の事務ですとか、雑務のところを支援していくというご趣旨かと思いますが、今やはりとっても必要な求められている部分かと思われます。当然、こういったことに携われる方、地域のことですとか、商店街事情に精通した方が求められると思いますが、どのような対応かと思われますがいかがでしょうか。","respondent":"金子産業振興課長","answer":"実際の支援の対応の内容だろうと思いますが、私どもとしては、商店街連合会にお任せしていますが、聞き及んでいる範囲では、今までそういったイベント等、あるいは事務をされていた商店街のＯＢの方を上手に活用して派遣しながら支援しているというふうに聞いてあります。","voiceIndex":15,"id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問","question":"いろいろなご相談を受けて、まさしく本当に気軽に訪れる相談場所という感じが見受けられますが、この商店街連合会事務局機能という点で、業務内容、これは主立ったものというか、感覚でも構いませんので教えていただければと思います。","respondent":"金子産業振興課長","answer":"お尋ねですけれども、商店街連合会の事務局の事務内容すべてを掌握しているわけではありませんが、私の知る範囲では、当然のことながら商店街、あるいは商店街振興組合の全体の事務、それから私どもの委託事業のほかに、最近では区のいろいろなセクション。","voiceIndex":17,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"実際この商店街連合会の事務局の職員体制というのは、どのような形なんでしょうか。","respondent":"金子産業振興課長","answer":"正確に把握しているわけではありませんが、私の見るところでは、常勤の方が３名いらして、そのほかに非常勤の方、あるいはアルバイトの方が何人かいらっしゃるように見受けられます。","voiceIndex":19,"id":"exchange-007"},{"speaker":"渡辺委員","kind":"確認","question":"先ほどご答弁いただいた中で、やはり産業振興直接でない部分で、行政の各セクションの業務もここ数年増えているというふうに伺いました。先ほどご答弁にありましたように、相談のところも含めて、あるいは各セクションの支援業務を含めて、こういったことは実際に区民サービスに有益であると思いますが、そのことについて、区民サービスにとってとても有益かどうか、ちょっとご確認させてください。","respondent":"金子産業振興課長","answer":"商店街連合会、さまざまなことをお願いしている中で、非常に区民にとって有益かどうかというお話ですけれども、商店街そのものにつきましても、商店街をリードする、そういう意味では地域の活性化そのものに資することはありますし、また先ほど申し上げましたとおり。","voiceIndex":21,"id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今、広報広聴課の事業ですとか、本当にあらゆるセクションにこの商店街連合会の機能というのが大きな役割を果たしている、そのように認識しました。やはりこのように区民サービスが有益である、特に区民サービスは今後展開される中で拡大されることが一人一人の区民にとってもありがたい話ですので、ぜひこの事務局機能の強化に向けてご支援願えればという要望で私の時間を終わらせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"},{"speaker":"浅野委員","kind":"質問","question":"私のほうからは、１２７ページ、保健衛生総務費の各種助成金と、１３９ページ、中小企業対策費について質問します。そして、１３９ページのほうですけれども、産業振興事業助成金の中に、公衆浴場商業協同組合として、こちらも助成金が出ています。同じ公衆浴場に対しての助成、内容は異なるかと思いますけれども、このように２つに分かれた理由ですけれども、わかりやすく簡潔にお伺いしたいと思います。","respondent":"太田健康課長、金子産業振興課長","answer":"それからもう１つは、公衆浴場のほうで新たに健康増進型ということでの健康が重要視されてきてありますので、公衆浴場施設を有効活用した区民の健康増進、区民の相互交流、そういった面での助成を新たに実施しているものです。この助成の趣旨は、産業振興の観点から、この浴場商業協同組合の振興発展のために実施する事業について一定の補助をしようというふうな趣旨から実施しているものです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"この公衆浴場以外の助成金ですけれども、こちら、医師会、歯科医師会、薬剤師会等ありますけれども、平成１７年度、そして平成１８年度、そして平成１９年度予算も同額の助成金が拠出され、またされようとしているわけですけれども、これらの助成金ですけれども、この金額を決める根拠となるものは何らかの基礎的なデータがあるのかなと思うんですけれども。","respondent":"太田健康課長","answer":"今後についてはどういうことかといいますと、それぞれの事業の必要性が生じた場合に検討していくということになってこようかと思います。","voiceIndex":28,"id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"その上でお伺いしたいんですけれども、薬剤師の方とお話をする機会がございまして、どういう話が出たかといいますと、インシュリンの自己注射なんですけれども、この注射針、使用済みの針ですけれども、これはそのまま捨てると、例えば清掃の方が指に刺したりとか、そういう事故を起こしてしまう。この容器につきましては、当初、都のほうでつくったものが配布をされて提供されてきた。","respondent":"秋山資源循環推進課長","answer":"平成１９年度で補助が切れるというお話も薬剤師会のほうからも伺っておりますし、ただ、注射針等につきましては、薬局から出るものですから事業系のごみだということもありますし、また一般の家庭で区民の方が使われているものですので。","voiceIndex":30,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問・要望","question":"検討してくださるということで、本当にありがとうあります。もう１点ですけれども、この品川薬剤師会としまして、この上のほうになるんですが、先ほどお話ししました休日の診療の件ですけれども、やはり薬を出す、提供する側としては、安全のためにダブルチェックを含めて２名でやっていきたいという話がございまして、なかなか予算のほうが厳しいという話も伺いました。","respondent":"金子産業振興課長","answer":"私どもが実施している部分につきましては、委託事業としまして専門のパソコンの講座の業者にお願いしています。","voiceIndex":32,"id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"その他もろもろあるかと思いますけれども、このような特殊なソフトというのは、多分いろいろなメーカーがつくったりして多くの種類があると思いますけれども、こちらのほうにつきましては、例えばこのソフトしかやらないとか、そういうことは多分ないと思うんですけれども、主要なソフトにつきましては、例えばプログラムをしっかりと用意するとか、メニューを幅広くつくって。","respondent":"金子産業振興課長","answer":"使い方につきましても、私どもが想定した部分を超える使い方を要望されていることもありまして、今後の展開につきましては、ただいま検討しているところですが、さまざまな団体あるいは個人の方からのご希望をお伺いして。","voiceIndex":34,"id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"それともう１点ですが、最後になりますけれども、品川ネット見本市、今年の３月にスタートしたと出ておりました。スタートしてからほぼ半年たっているんですけれども、もし統計としてデータがあればなんですが、今までのアクセス件数、また増えていっているのか、減っているのか、そういうような推移がありましたら教えていただきたいと思います。","respondent":"金子産業振興課長","answer":"品川ネット見本市のお尋ねですけれども、これはご指摘のとおり、３月にスタートしまして、ちょうど７カ月がたったところです。アクセス数は増加の傾向にありまして、９月現在でトータルしますと２,５８５件のアクセスがあります。","voiceIndex":36,"id":"exchange-015"},{"speaker":"浅野委員","kind":"質問・要望","question":"このようなさまざまな技術を用いて品川の技術、また品川でやっていること、日本にまた、世界というのはなかなか難しいかもしれませんけれども、どんどん宣伝をしていっていただければと思います。この品川の特色ある中小企業が本当にいつまでも元気で仕事をできるようにこれからも支援をしていただくよう私のほうから要望して質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"１３５ページと１３６ページの船舶中継所維持管理費、船舶中継所作業費に関連してまずお伺いしたいと思います。この船舶中継所、東品川清掃作業所ですけれども、品川区内の不燃ごみが運ばれて、中間処理されているとのことですけれども、その後、この不燃ごみはどのように処理されているのかお伺いしたいと思います。","respondent":"秋山資源循環推進課長","answer":"お尋ねの東品川の清掃作業所ですけれども、城南の４区から不燃ごみが搬入されております。私ども品川区と、目黒区、世田谷区、渋谷区と４区が不燃ごみを持ち込んでおりまして、そこから船で京浜島の不燃ごみ処理センターというところに持ち込んです。","voiceIndex":40,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"焼却ということなんですけれども、不燃ごみという名前にもかかわらず、一定の鉄分などは選別してリサイクルへ回すということなんですが、燃やすということで、非常に驚きを感じるわけですけれども、これはいつからそういった処理が行われていたのでしょうか。","respondent":"秋山資源循環推進課長","answer":"大田清掃工場ですけれども、平成２年に竣工しています。それ以降、このような処理をしているというところです。","voiceIndex":42,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"となりますと、平成２年ということなので、１７年間、不燃ごみということで選別を私も含め区民の方々がされていましたけれども、それは不燃ごみ、金属、ガラスなどの不燃ごみと、プラスチックなどの焼却不適ごみの総称とされていますけれども、これが焼却されていたということになるわけですけれども、このことを普通に考えたら驚きの事実だと思うんですが、区民の皆さんは知っているのでしょうか。","respondent":"秋山資源循環推進課長","answer":"この話、大田の清掃工場で燃やしているというお話は、昨年度以前もサーマルリサイクル等の話をして町会で説明をしておりますし、積極的に平成２年の当時からお話をしていたかどうかというのはちょっとわかりませんけれども、十分説明をしていたというふうに考えております。","voiceIndex":44,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"十分説明をしているというお話ですけれども、私の実感としては、周知徹底というか、全然十分ではないと思うんです。周りの方に聞いても、燃やしていたのというふうに驚かれる声もよく聞きますし、いつの時点かということも定かではないということなんですが、どのような説明周知を行ったのか、いつの時点で行ったのかというのをもう少し丁寧にというか、具体的に教えていただけますでしょうか。","respondent":"秋山資源循環推進課長","answer":"説明ですけれども、大田の清掃工場が竣工しましてすぐ、区民委員会、当該の委員会でも視察に行っていただいて、不燃ごみの処理センターと大田の清掃工場を見学、視察をしていただいておりますし、あと、昨年度の周知ですけれども、４０数回以上。","voiceIndex":46,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"町会などで説明したということと、あと、区民委員会で視察に行ったということ、あと４０回ほど説明したということなんですけれども、やはり非常に足りないといいますか、周知の程度としては非常に不十分だと思うんですけれども、やはり不燃ごみとして分別の協力をしていただいて、協力を求めてきた以上、それを不燃ごみとして処理せずに燃やしてきたということで。","respondent":"岩崎環境清掃事業部長","answer":"それを興味を起こさせようとしているのが品川区の考え方でございまして、何か隠していて説明が不十分でというようなお話ですけれども、ちょっと私の認識とは違うかなというふうに思っております。","voiceIndex":48,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"少なくともこれからの廃棄物処理をどうするかということを考えていく上で、これまで燃やしてきたということの事実を、総括というか、反省と言うと言い過ぎかもしれないんですけれども、それを次のごみ処理計画を区民の皆さん全体で考えていくという、議論していく上では、それは最低限の土台になると思うんですけれども、そこら辺はどうでしょうか。","respondent":"秋山資源循環推進課長","answer":"清掃事務所の職員が１件１件お宅を回って説明をしている中では、どういう分別になるのかという質問が中心でございまして、もちろんそういう不燃ごみから可燃ごみにプラスチックを変えるんですよという説明もしておりますし。","voiceIndex":50,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう問題もあります。その点で、最低限このパブリックコメントの期間というのは大幅に延長されるべきだと思いますし、サーマルリサイクル実施に関しても、やっぱり一から区民の皆さんと長い間かけてどうなのかということも踏まえて、必要であれば見直すということも選択肢に入れるべきだと思うんですけれども、その点はいかがでしょうか。","respondent":"秋山資源循環推進課長","answer":"いろいろ何点かご指摘がございましたけれども、循環型社会形成推進基本法のお話ですけれども、そこの中には環境への負荷の低減にとって有効である場合は、これによらないということで、昨今、ライフサイクルアセスメント等は言われておりますので。","voiceIndex":52,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"少なくとも２０日間というのは本当に短いというか、どう考えてもこの環境問題は非常に区民の皆さんも関心が高い問題ですし、世論調査でも常に３位以内に入って、今年は５位になりましたけれども、毎回品川区が行っている世論調査でも３位以内に入って非常に関心が高い分野だけに、最低限、これは２０日間という期間ではどう考えてもこれから計画を策定した上でも。","respondent":"秋山資源循環推進課長","answer":"パブリックコメントの時期ですけれども、広報に書いてあるとおり１０月１１日より月末までという期間で出しております。","voiceIndex":54,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"それが十分な期間だと考えておられるのか、また、２０日間とした何か基準としての縛りみたいなものはあるのでしょうか。必要であれば１年とかというのもできると思うんですけれども、それは可能なんでしょうか。","respondent":"秋山資源循環推進課長","answer":"２週間以上３０日以内の期間をとるというのがパブリックコメントの区の方針ですので、その中で期間をとっているです。","voiceIndex":56,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"最後なんですが、がらっと変わりまして、１３２ページの環境測定費の大気汚染対策費に関連してお伺いしたいと思います。","respondent":"阿部都市計画課長","answer":"もう１点ですけれども、環境影響の話ですけれども、影響評価などでも言っておりますけれども、事業評価をきちっとしますので、事前と事後と比較いたします。そういうふうに義務づけがありますので、そのように当然見守っていくという考えです。","voiceIndex":58,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"区民の皆さんの立場に立ってできることを模索していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-027"},{"speaker":"川西委員","kind":"質問・要望","question":"そういう中で、区民健診の実施の数字の推移というのが、簡単でいいですから説明していただき、今、品川区が実施している検査の中で、区民健診という中に入るのでしょうか、個人商店や小規模事業所の健診の見直しが行われるやに聞いておりますが、その中身について。これは項目としては区民健診に入るのでしょうか。","respondent":"太田健康課長、川口品川区保健センター保健サービス課長","answer":"最初に、私のほうから、区民健診の推移ということでお尋ねですけれども、受診者ですれば、平成１６年度で３万７,３９４人、平成１７年度で３万７,６５４人、平成１８年度で３万６,８８４人と。その中で小規模企業健診を行ってあります。お尋ねの件ですけれども、今現在、特に見直しとか、そういうことは、今現在のお話ですけれども、考えてございません。","voiceIndex":62,"id":"exchange-028"},{"speaker":"川西委員","kind":"質問","question":"そういうふうに新しく加えようとするものについての見通しを伺わせてください。それから、これは素人の意見なんですが、毎年毎年がん検診を受けているのに胃がんが発生してしまったり、膵臓がんが発生してしまったり、しようがないんですけれども、検査の内容に多少不十分さがあるのかないのか、これは素人の意見ですから聞かせてください。","respondent":"太田健康課長","answer":"がん検診の内容、種目について、私のほうからご答弁します。がん検診、厚生労働省の指針に基づいて、胃がん、子宮がん、乳がん、肺がん、大腸がんの５つのがんについては従来から実施をしてきてあります。","voiceIndex":65,"id":"exchange-029"},{"speaker":"川西委員","kind":"質問・要望","question":"医療関係者とか、区民の皆さんにどういうふうに聞くのかという聞き方がありますが、追加してほしいという内容の検診があるやに聞いております。しかし、１つ要望がありますが、同じ南品川の中で、例えば地域センターがコミュニティーの１つの地域の固まりということだとすると、モデル地域になっているところとなっていないところと出まして、いろいろ各種イベントのときに意見が混線しております。","respondent":"秋山資源循環推進課長","answer":"モデル地区ですけれども、一応１５％の地域を設定し、工夫はしてきたつもりなんですけれども、通常の町会、自治会と区分けとか、あと、小さな路地で地区とモデル地区、未実施の地区が分かれていたりということで。","voiceIndex":67,"id":"exchange-030"},{"speaker":"川西委員","kind":"質問","question":"来年度の全面実施の方向性についてお願いします。それから、資源追っかけ隊というのは、先ほどの説明のように大変区民の関心事です。今まで分別をして、大気汚染その他に影響のないように考えている区民の皆さんからすれば、それがどういうふうに資源化されて再利用されていくのかということは大きな問題だというふうに思います。資源追っかけ隊の活動の記録を教えてください。平成１８年度。","respondent":"秋山資源循環推進課長","answer":"追っかけ隊の隊員数ですけれども、合計で６２名です。来年度の全区展開につきましてですけれども、先ほどもお話申しましたように、地区を分けていきますと混乱が出てくるですので、全区で同時に実施していきたいというふうに考えております。","voiceIndex":69,"id":"exchange-031"},{"speaker":"川西委員","kind":"質問","question":"資源追っかけ隊のことなんですが、プラスチック類のモデル地域が荏原のほうでありましたよね。それの再生資源化のところは調査活動は追っかけ隊の範疇に入っていないんですね。今のは東洋ガラスと食品トレーですから、荏原地域でモデル実施をしているプラスチック類の再資源化の行き先というのは、追っかけ隊の平成１８年度の実績の中には入っていないのでしょうか。","respondent":"秋山資源循環推進課長","answer":"プラスチックの資源化は、荏原地区も含めて、平成１９年９月からですので、平成１８年度の中には入ってございません。","voiceIndex":71,"id":"exchange-032"},{"speaker":"川西委員","kind":"質問","question":"１２７ページ、健康増進型公衆浴場の補助金のことですけれども、これは遠くへ温泉に行けない人たちが大変利用できる施設みたいなものに補助をしていただいているのかなというふうに思いまして、内容を聞きたいと思います。私は少なくなった公衆浴場に対しての支援というのは、これからやはり公としてもどんどんしていかなければならないというふうに考えている１人でありますので、説明を伺います。","respondent":"太田健康課長","answer":"健康増進型公衆浴場改築の補助ですけれども、この補助につきましても、平成１８年度から実施をしたものです。１,０００万円を限度として補助対象施設整備費の２０分の１ということで実施をしています。","voiceIndex":73,"id":"exchange-033"},{"speaker":"川西委員","kind":"質問","question":"１３３ページ、緑化推進費で、この金額が出ております。１けた違うのではないかと。ですから、やはりこの点では、少し予算の規模を増やして、大胆に緑化、例えば、意見になりますけれども、小中一貫であいたところに思い切って緑化、今、八潮団地の地域なんていうのは、非常に環境のいい緑化地域ですよね。これはそのように品川区内全部考えてほしいというふうに思います。時間がないから答弁はいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-034"},{"speaker":"井桁委員","kind":"質問","question":"成果報告書の１２９ページ、犬の登録・予防注射および動物の愛護、そして先ほどもございましたが、１３３ページの緑化推進費についてお伺いしたいと考えています。１２９ページの犬の登録・予防注射および動物の愛護についてお伺いいたします。教えていただければと思います。","respondent":"山岡品川区保健所衛生課長","answer":"登録は、犬の一生の間に１回していただければ結構ですので、そういうことで１年間で登録したのが１,０００何がしということになります。予防注射はその以前から登録されている犬、あるいはまだ未登録の犬に対してもやっていただくことになります。","voiceIndex":77,"id":"exchange-035"},{"speaker":"井桁委員","kind":"意見","question":"毎年注射をするとワッペン、金具みたいなのをいただくと思うんですけれども、それで継続になっているとうちの近所ではそういうことになっているのではないかなということだと思っていたんですが、その辺をお聞かせください。","respondent":"山岡品川区保健所衛生課長","answer":"おっしゃるとおりで、毎年注射していただくと、済証という形でそれを交付します。それをつけていただくということになります。先ほど登録と申しましたのはそれ以前の問題で、そもそも犬は登録していただかなくてはいけないという、そういう意味の登録です。","voiceIndex":79,"id":"exchange-036"},{"speaker":"井桁委員","kind":"質問","question":"その登録についてもう少しお聞かせ願いたいんですけれども、平成１８年は１,００６頭とあります。注射の頭数が６,５５２頭、では、この６,５５２頭というのが、今、品川区にいる犬の数なんでしょうか。教えていただければと思います。","respondent":"山岡品川区保健所衛生課長","answer":"今ちょっと手元にないんですが、登録数は昨年度末で８,８９０頭が登録していて、そのうちの６,５００何がしが予防注射をしていただいている、そういうことです。","voiceIndex":81,"id":"exchange-037"},{"speaker":"井桁委員","kind":"質問","question":"それで、今現在、８,８９０頭という犬が品川区にはいると思うんですが、ちょうど時間帯もかぶるということもありまして、多くの犬、そしてまた外には犬だけではなくて、最近ではこういった呼び方をしているそうなんですが、地域猫といった、そういった犬や猫、動物がたくさんいると思うんですけれども、この犬の数はわかったんですが、次は地域猫についてちょっとお伺いしたいと思うんですが。","respondent":"太田健康課長","answer":"せっかくのご質問ですが、地域猫、猫については登録制がございませんので、申しわけございませんが、把握できておりません。","voiceIndex":83,"id":"exchange-038"},{"speaker":"井桁委員","kind":"意見","question":"私の家の近所で大きな公園がこの間オープンいたしまして、そのときでもまだ何人かの方が猫にえさをやっていて、発情期になるとかなりの音を立てて夜うるさかったりとか、そういったこともあるんですが、その辺の品川区としての対策というのをちょっとお聞かせ願えたらと思います。","respondent":"太田健康課長","answer":"地域猫のお話ですけれども、もともとはやはり所有者の方がいらっしゃるのだろうと考えています。それが捨てたということで、猫の繁殖力が強いものですから、子どもが産まれてきて、次々と公園といいますか、いるという状況になってあります。","voiceIndex":85,"id":"exchange-039"},{"speaker":"井桁委員","kind":"意見","question":"先般の品川の広報にも載っておりましたが、その頭数で１人１匹となっておったんですが、その件数でまた助成についても６７件と毎年毎年猫というのは子どもが産まれ、そしてまた１年後にはその子たちが子どもを産める状況になっているので、ぜひともこの頭数というのを今後増やしていくのであるか、そのご見解をお聞かせ願えたらと考えています。","respondent":"太田健康課長","answer":"現在、１町会あります。それから、助成金の件数ですが、これは今年なりの件数の申し込み状況を見ながら次年度以降考えていく、こういうことかと思います。","voiceIndex":87,"id":"exchange-040"},{"speaker":"井桁委員","kind":"意見","question":"続きまして、猫がいる公園等々のことで含みまして、１３３ページの緑化推進費のみどりの保全事業ということについてお聞かせ願います。この保全事業というのは、近年言われておりますＣＯ２の排出を防ぐ緑についての保全だと私は思っておるんですが、その辺の考え方をお聞かせ願えたらと思います。","respondent":"藤田道路公園課長","answer":"ただいまのみどりの保全事業の関係ですけれども、私ども、この事業の中で区内にある大きな樹木等の保存樹あるいはそういった樹木がたくさんある樹林といったようなものを保存樹、保存樹林というような形で持ち主の方の同意を得て。","voiceIndex":89,"id":"exchange-041"},{"speaker":"井桁委員","kind":"質問","question":"その保存樹について、以前ちょっとある方からお伺いしたんですけれども、基本的に３年に１回のお手入れということになっておりますが、今後その３年に１回というのが、木のお手入れというのはかなり大変なものだと思うんですが、増やしていく、１年に１回という、そのような緑を守るという観点から、そのようなことをお考えでしょうか。","respondent":"藤田道路公園課長","answer":"本来、樹木はそれぞれの持ち主の方が、その持ち主の方々の手で手入れをするのが基本ですので、私どもはそれに支援をするという形で、今後もこのような形で続けていきたいというふうに考えております。","voiceIndex":91,"id":"exchange-042"},{"speaker":"山内委員","kind":"質問・要望","question":"１２８ページのがん対策費についてお尋ねさせていただきたいと思います。と申しますのは、実はうちの父親も今がんにかかっていまして、肝臓がんと腎臓がんということで、まさに今これを見ますと、その検診はないんですけれども、これは私の要望といたしまして、ほかの部分のがんの検診も加えてお願いをしていただければなんて思っております。それと、乳がんの検診がありますね。","respondent":"太田品川区保健センター大井保健相談所長","answer":"先ほど委員がおっしゃられました肝臓がんにつきましては、肝炎ウィルスの検査を行うということで、肝臓がんを減らすということについて有効性が確立されてあります。","voiceIndex":94,"id":"exchange-043"},{"speaker":"山内委員","kind":"質問・要望","question":"やはりそういう部分でこのＰＥＴ検査というものを私はどんどん周知していただいて、例えば、これはもう本当に要望になってしまうんですけれども、ＰＥＴ検査をする人に当たって、１人当たり何かしらの区からの助成をしていただければ、例えば今、高額医療が、昨日も予算のほうで説明がございましたけれども、高額療養費が今、１７億円品川のほうでかかっているということなんですけれども。","respondent":"倉橋品川区保健所保健サービス課長","answer":"そういう意味でＰＥＴ検査というのは非常に高額な検査ですので、すぐに委員のご提案のような形になることはなかなか難しいことだとは思いますけれども、このような原則にのっとりまして有効な手法を検討して採用していきたいというふうに考えております。","voiceIndex":98,"id":"exchange-044"},{"speaker":"山内委員","kind":"質問・要望","question":"そうしますと、やはりその間にカラスだ、猫だの、ごみの被害に遭って、道路にごみが散乱して、なかなか美観という部分で損なわれてしまうということで、例えば、これはアイデアなんですけれども、時間帯を変えるとか、ローテーションを変えるとか、そのような形で、それは毎年毎年やってくれということではなくて、例えば、２年とか、３年とか、ないし５年とか、それぐらいのスパンでこのような形でルート。","respondent":"島袋品川区清掃事務所長","answer":"このルートは、清掃車両と効率を考えて最大限に使っているものですから、そう簡単に変えられないんですけれども、将来的には検討していきたいと思っています。","voiceIndex":100,"id":"exchange-045"},{"speaker":"金野委員","kind":"質問・要望","question":"私のほうからは、１３０ページの妊婦健康診査、それから、公衆トイレ、それから１２８ページの予防費からお伺いをします。１３０ページの妊産婦の健康診断ですけれども、先般、今定例会でも同僚議員から、公明党としてこの妊産婦健診の無料化の回数を増やしていただきたいという要望をさせていただきました。","respondent":"太田健康課長","answer":"妊産婦健診についてのお尋ねです。９月の本会議のご質問のところでは、いわゆる五者協議をそれぞれの団体の代表と学識経験者、それから医師等を含めて、あり方の検討会を今行っているということで申し上げたところです。","voiceIndex":103,"id":"exchange-046"},{"speaker":"金野委員","kind":"質問・要望","question":"早急というのでしょうか、出てから取り組んでいただくということで、今は返事待ちということですので、出ましたら、どうか重ねてお願いしたいと思いますが、早急にこのことに本区としても取り組んでいただきたい、重ねて要望いたします。次に参ります。ちょっと戻りますが、１２８ページの予防費についてお伺いします。","respondent":"倉橋品川区保健所保健サービス課長","answer":"これにつきましては、２類、３類等の詳細な説明は省きますけれども、発生した感染症につきましては、二次感染等の予防、ほぼ防げておるという結果です。エイズ抗体検査につきましても十分な対応をとっていると考えております。予防接種につきましては、実績があります。","voiceIndex":105,"id":"exchange-047"},{"speaker":"金野委員","kind":"提案","question":"そこで、はしかではないんですけれども、この予防接種という観点から見て、これから冬を迎え、インフルエンザ等々、悪質な流行が来る時期でも、また、今年は新型なんていうこともあるのかどうか、その状況もあるんですけれども、そういう中で高齢者の方が、今はインフルエンザもたしか高齢者の方は助成をしていただき、たしか後期高齢者は。","respondent":"倉橋品川区保健所保健サービス課長","answer":"というように、まだ十分にどの程度有効かというところが十分でない部分がありますので、これにつきまして、今後検討していきたいと考えているところです。","voiceIndex":107,"id":"exchange-048"},{"speaker":"金野委員","kind":"質問・要望","question":"この健康に対する意識というのは、スポーツをしたり，また食事の面でも、休息の面でも考えることですが、それだけではどうしても体は老化をしていく、病気になっていく、これは仕方のないことで、それを予防するには、やはり医力を借りなければいけないといったときに、ぜひこの肺炎球菌ワクチンの予防接種というところもひとつ考えていただければ、そのように思いまして、重ねて要望をするものです。","respondent":"倉橋品川区保健所保健サービス課長","answer":"それにつきましては、まず手を洗う、そのほかの基本的な生活習慣、適度な運動、清潔を保つ、入浴等の清潔など、そして、委員ご指摘の肺炎球菌ワクチンによる予防等、さまざまな予防策を考えまして、肺炎のすべてが予防できるわけではありませんけれども。","voiceIndex":109,"id":"exchange-049"},{"speaker":"金野委員","kind":"質問・要望","question":"ぜひ重ねて重ねて要望いたしますので、こちらも粘り強く要望させていただきたいと思います。よろしくお願いします。続きまして、戻りますが、１３０ページの公衆トイレ維持に関してお伺いいたします。清掃の割合はどれぐらいでされているのか教えてください。","respondent":"藤田道路公園課長","answer":"公衆便所の関係ですが、清掃のほうは１日１回清掃の場所と、２回清掃の場所とあります。２回清掃の場所については、駅前等の利用頻度の高いところ、こちらについては２回清掃というような形で行っているものです。","voiceIndex":111,"id":"exchange-050"},{"speaker":"金野委員","kind":"質問・要望","question":"トイレをきれいにしていただいて、本当に皆さんが使いやすいようにしていただくことをよろしくお願いします。ですので、設備に関して、まだまだ、足場だけではなくて、子どもが座れるような場所も必要なトイレもありますし、いろいろな意味で、まずはだれでもトイレという観点から、使いやすい使い勝手のいい設備もぜひつけていただきたい、このことを要望いたしますが、ご所見を伺いたいと思います。","respondent":"松代管理工事課長","answer":"大体公園の入り口でまず案内を見ていただくという形になろうかと思います。だれでもトイレ、私ども身障者の方のみならず、妊婦の方、また小さなお子さまを連れた女性の方に使っていただけるような、そういったトイレを今、順次改築とあわせて進めているところです。","voiceIndex":113,"id":"exchange-051"},{"speaker":"藤原委員","kind":"質問","question":"私は、成果報告書の１３４ページ、メール配信サービス事業、１３７ページ、観光アクションプラン推進事業、１３８ページの商店街活性化事業についてお伺いしますが、まずメール配信サービス事業ですけれども、これ、平成１８年度の新規事業だと思いますが、まず実績についてお伺いします。","respondent":"秋山資源循環推進課長","answer":"メール配信サービスですけれども、これは平成１８年度から明治大学との共同研究ということで始めさせていただきました。開始は平成１９年２月です。現在の実績ですけれども、延べの登録数が８４７名です。","voiceIndex":116,"id":"exchange-052"},{"speaker":"藤原委員","kind":"質問","question":"利用者の評判と、それと区としての評価と、あと、最初の見込みというのをもう一度伺います。","respondent":"秋山資源循環推進課長","answer":"見込みですけれども、当初、どこまで行くかというのはなかなか見込みはできてはいなかったんですけれども、現在の数が多いか少ないかというのはちょっと議論があるところではありますけれども、私どもとしましては、いろいろな広報の手段の１つということで。","voiceIndex":118,"id":"exchange-053"},{"speaker":"藤原委員","kind":"質問","question":"明治大学との共同開発という形になるのですばらしい施策のように思うんですけれども、結局、ごみを出すときにメールで登録した方に、きょうはごみですよという形でお知らせするのが主体ですよね。ほんとうにそのメールを送った方がちゃんと出しているのか、ちゃんとこのシステムを使っているのかということを検証しなければ、次に向かって全然進めないと思うんですけれども、その辺はいかがでしょうか。","respondent":"秋山資源循環推進課長","answer":"ただ、評価につきましては、なかなかメール配信を受け取っている方との連絡というのもなかなか難しいところですので、今後の研究課題にしたいというふうに考えております。","voiceIndex":120,"id":"exchange-054"},{"speaker":"藤原委員","kind":"質問・要望","question":"まさに８４７名の１人が課長ということですよね。自分も入られている。次へ行きますが、次、環境アクションプランについてお伺いしますが、これで商店街のつまみ食いウォークがすごくマスコミでも評判が高かったと思うんですけれども、いわゆる都市型観光ということと、ウォーキングの位置づけということを、なぜそういう形でしたのかについて、まずお伺いします。","respondent":"金子産業振興課長","answer":"そういう意味では、この商店街つまみ食いウォーク、利用者の方および商店街の方に非常に好評を得ているものですから、恒例の事業として位置づけていくものかなと今考えて、今年度についても、あるいは今後についてもそういった取り組みをしていこうと考えているところです。","voiceIndex":122,"id":"exchange-055"},{"speaker":"藤原委員","kind":"質問","question":"都市型観光ですけれども、まさにこのウォーキングというのはすばらしいと思うんですけれども、いわゆる都市型観光において商店街だとか、お祭りだとか、神社・仏閣だとか、そういう形でこれから観光資源とともにやっていくと思うんですけも、もう一歩踏み込んで、それがいわゆる区内の産業振興とどうつながっていくかということについて、どのような展望を持っているか教えてください。","respondent":"金子産業振興課長","answer":"先ほどちょっと取り上げたとおりなんですけれども、区の観光資源、委員ご指摘のとおり、そういった歴史的なものもありますが、商店街あるいは区内の著名な工業あるいは先ごろ整備した旧東海道等々。","voiceIndex":124,"id":"exchange-056"},{"speaker":"藤原委員","kind":"質問","question":"商店街のことでちょっと１件お伺いしますが、商店街でやっているインターロッキングの維持管理なんですけれども、本当にこのごろ厳しくなってきていると思いますが、区としてこのインターロッキングの支援について、今後どのように思っていらっしゃるのか、ご見解をお伺いしたいと思います。","respondent":"金子産業振興課長","answer":"ご指摘のとおり、商店街、長く続いた不況で疲弊しているところも多うあります。私どもとしましては、これにつきましては、今後の研究課題とさせていただければと思います。","voiceIndex":126,"id":"exchange-057"},{"speaker":"中塚委員","kind":"質問","question":"私からは、成果報告書１２９ページの区民健診についてお伺いしたいと思います。とりわけ２０代、３０代の若い世代における健康づくりについてお伺いいたします。よく若いうちは元気だし丈夫だから大丈夫だとおっしゃる方もいらっしゃいますが、年に１回の定期健診というのは大事だと思いますけれども、その保健指導上の理由といいますか、そこをちょっと教えていただけたらと思います。","respondent":"太田健康課長","answer":"区民健診についてのご質問です。年に１回、老人保健法に基づいて、４０歳以上の方を対象として区民健診を実施しているものです。","voiceIndex":130,"id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"私が伺いたいのは、２０代、３０代も含めて、若い世代の年に１回の健康診断というのは、保健指導上必要ではないかという趣旨で伺いました。もう一度お願いします。","respondent":"太田健康課長","answer":"後半でご答弁したつもりなんですが、申しわけございません。予防という観点から言えば、やはり疾病を予防していくということであれば、どなたでも年１回の検査というのは必要かなというふうには感じているところです。","voiceIndex":132,"id":"exchange-059"},{"speaker":"中塚委員","kind":"質問","question":"品川区は、２０代、３０代に限って伺うんですけれども、こうした健康診断を受ける機会が失われている若い世代が広がっていることをご存じなのか、また、こういう状況を望ましい状況だと思うのか、お考えを教えてください。","respondent":"太田健康課長","answer":"ご質問の２０代、３０代の方の健診のお尋ねですけれども、通常、学校を卒業して就労されていれば、やはり何がしかの保険に入られている。これは日本の今、皆保険制度のもとでは入られているというふうに私どもは認識しております。","voiceIndex":134,"id":"exchange-060"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、若い世代で健康診断を受ける機会が失われている若者が広がっていることをご存じかと。そういう状況が望ましい姿なのかということです。","respondent":"太田健康課長","answer":"新聞紙上では、ネットカフェというような状況の中で受けられない方がいらっしゃるということは社会常識の中で承知はしていますけれども、統計上、どの程度ということはございません。やはり健診は受けられることが望ましいということは基本的なものだと考えています。","voiceIndex":136,"id":"exchange-061"},{"speaker":"中塚委員","kind":"質問","question":"もちろんこの調査では年に１回という規定はありませんけれども、若い世代の健康診断を受けていない状況をこういうところからもその傾向が見られるのではないのかなと思うんですけれども、この世論調査の結果はどんなふうにごらんになられているのでしょうか。","respondent":"太田健康課長","answer":"若い方の受診率が低い、これはやっぱり年齢が若いということで、体力がある、健康だというようなことがやっぱり１つあるのかなと考えています。","voiceIndex":138,"id":"exchange-062"},{"speaker":"中塚委員","kind":"質問","question":"先ほどから若いから自分は大丈夫だと過信していても、実際はやっぱり年に１回は望ましいという、ここがやっぱり大事ではないのかなと思うんです。この品川区世論調査を行っていますけれども、例えばこの設問の中に過去１年間健康診断を受けておりますかと、そういうところの設問があれば、傾向がつかめるのではないかと思うんですけれども、いかがでしょうか。","respondent":"太田健康課長","answer":"３０代で３割の方が受けていない、機会が少ないとか、費用が高いとか、そういういろいろな理由はあろうかと思いますけれども、やはり意識としては受ける必要があるんだと、そういう意識はたしか世論調査でも高かったかなと思ってあります。","voiceIndex":140,"id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"私がなぜ２０代、３０代の健康診断のことを心配しているかといいますと、きのうの話でも雇用の破壊の問題や、あと、長時間労働の問題もあわせて、正社員、非正規社員、どちらに対しても若い人を育てるという視点が会社や組織の中に非常に失われていて、特に即戦力を求める企業が多いと、異常な成果主義や目標管理制度的なノルマを掲げたような形の中で、心の病が、特に３０代を中心に広がっている。","respondent":"倉橋品川区保健所保健サービス課長","answer":"実際、相談の実績といたしましても、うつなどの相談が伝統的な統合失調症などに加えまして、うつなどの部分の相談が増加しています。これにつきましては、相談体制を強化いたしまして、またうつ対策、これは講演会、専門医の相談の回数を確保するなど対策を講じているところです。","voiceIndex":142,"id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"実際に保健所の相談の中でも３０代の方々のうつ、心の病が広がっているというお話しですけれども、その背景にはどういった問題があるのか、ちょっと認識を伺いたいと思います。それの背景についてお伺いしたいと思います。健康づくりのきっかけづくりに役立てていただきたい、そう願うわけですけれども、対象拡大をぜひ進めていただきたいと思いますけれども、いかがでしょうか。","respondent":"倉橋品川区保健所保健サービス課長、太田健康課長","answer":"これに対しましては、短期的なうつの発病前後の対応だけでなく、その心の病全体に対します普及啓発、このようなものが基礎的な理解として最も重要になると考えておりまして、普及啓発、それから心の病の対応方策。今申し上げたようなことを総合的に勘案して、私どもとして年齢を引き下げて、２０代、３０代の方を対象とした健診よりは、むしろ先ほども申し上げましたけれども、一般的な啓発。","voiceIndex":144,"id":"exchange-065"},{"speaker":"中塚委員","kind":"質問・要望","question":"職場等で受ける機会のない、そういった方が今新たに生まれているということをぜひ直視していただきたいのですけれども、最後に１つ。２３区の中でもいわゆる４０歳からの区民健診の年齢を拡大し、若い世代に広がっているところが増えておりますけれども、何区があるのか教えてください。","respondent":"太田健康課長","answer":"正確に把握してございませんが、数区ということで認識をしています。","voiceIndex":147,"id":"exchange-066"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、私の調べた範囲だと、千代田区、港区、杉並区、葛飾区などで対象を拡大しているそうです。千代田区などで電話で伺った話ですけれども、対象者にはがきでお知らせをしてあげ、受診機会がなければ、こちらでやっていますとお知らせをしているそうです。ぜひ２０代、３０代の健康づくりをしっかりと進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-067"},{"speaker":"大沢委員","kind":"質問","question":"１２７ページ、各種助成金に関連すること。それと、１３７ページ、１３８ページ、全体的に質問します。１２７ページの助成金ということで、医師会、歯科医師会、薬剤師会、さまざまな医療関係団体に助成をされているということですけれども、この医療関係機関または関係団体、こちらの方たちが意見を交換するような会議体というのはあるのでしょうか。","respondent":"太田健康課長","answer":"通常ですと年度末の３月に全体的なお話をする機会ということで実施をしています。","voiceIndex":151,"id":"exchange-068"},{"speaker":"大沢委員","kind":"質問","question":"その都度意見を伺っているという、その都度というのはどういうことを言うのか。それと、年度末にということですけれども、会議体自体を常時というか、定例的に開いて意見を交換する場所ないし時間というのをあまり必要性を感じておられないのかお答えください。","respondent":"太田健康課長","answer":"そういう事業の中でいろいろな問題が出てきたときに医師会との調整をする、そういう場で開催をさせていただいているところです。それから、定期的な会議体といいますか、持つ必要があるかということについては、私どももそういう認識は持っているところです。","voiceIndex":153,"id":"exchange-069"},{"speaker":"大沢委員","kind":"質問","question":"今ちょっと伺った答弁の中で、会議体を開いて意見の交換をするという主たる目的が予算とか、その委託事業に対する打合せ程度のことに感じましたけれども、そのような受けとめ方でよろしいでしょうか。","respondent":"太田健康課長","answer":"当然、予算、事業連携も必要ですけれども、それにとらわれず、品川区の区民の方の健康を増進させるという視点からの意見交換も当然入っているところです。","voiceIndex":155,"id":"exchange-070"},{"speaker":"大沢委員","kind":"質問","question":"どういうふうに医療関係の方がそういう場合、またほかの場合もあろうかと思いますけれども、どういうふうに連携、どういうふうに意思を疎通をしながら動いていっていいのかというのは、まるっきり暗中模索でわからないというようなお話を聞いたんですけれども、それに向けての会議体、それに特化せずにそういうようなものの意思が疎通できるような会議体を開くことが必要だと思いますけれども。","respondent":"久保田防災課長","answer":"ただ、その事前の打合せが、私どもぜひともそういう形でやってみたいなとは思っているんですけれども、医者のスケジュールとか、あるいは薬剤師のスケジュールがどうしても合わないことが多くて、こちらから職員がそれぞれお尋ねしていって、今回の訓練の趣旨と。","voiceIndex":157,"id":"exchange-071"},{"speaker":"大沢委員","kind":"質問・要望","question":"ぜひとも区が主導して医師会、薬剤師会、歯科医師会、これは皆さん多忙な方ゆえになかなか接点を持ちにくいと思いますので、ぜひとも行政の方たちが主体になって定期的な会議体をつくっていただきたいと思います。執行率が低いのはなぜかということを教えてください。","respondent":"金子産業振興課長","answer":"産業経済費の執行率がほかと比べて８０％台という理由ですけれども、一番大きな理由を１つ申し上げれば、私どもの事業の中で中小企業事業資金融資あっせんという事業があります。１３８ページの上から六、七行目あたりでしょうか。","voiceIndex":159,"id":"exchange-072"},{"speaker":"大沢委員","kind":"質問","question":"まさにその話なんですけれども、融資あっせんを申し込まれて、この中に金融相談とありますけれども、区でその融資あっせんに関して蹴ってしまう場合と、金融機関、保証協会へ行って蹴られてしまう場合があるんですが、その２つの場合どれぐらいの件数があるのか教えてください。","respondent":"金子産業振興課長","answer":"システムは委員もご承知だろうと思いますが、私どもに融資の申し込みに来た場合に、その方の企業の経営状況等々、決算書等々で調べまして、融資が可能かどうかを案内するところですけれども、不執行分については、大体年間６０件ほどあります。","voiceIndex":161,"id":"exchange-073"},{"speaker":"稲川委員","kind":"質問","question":"私のほうからは、成果報告書の１２９ページ、井桁委員からも質問がありましたが、犬の登録、そして予防注射および動物の愛護、１３３ページのカラスの巣等撤去助成、１３５ページのカラス対策費、そして動物死体処理費についてお伺いいたします。逆にやっぱりそれも載せるべきではないかなと思います。この飼い猫の去勢・不妊手術の助成、１３５件なんですが、これは実際単価はどれぐらいの助成をしているか。","respondent":"山岡品川区保健所衛生課長、太田健康課長","answer":"死亡につきましては、おっしゃるとおり、死亡されますと引いていくわけですけれども、先ほどの８,９９９頭というのは、年度末で押さえた数字ですので、それまでに死亡された犬は引かれているという形になっております。２点のご質問をいただいたかと思います。１点目、飼い猫の不妊・去勢手術の関係です。これについては、獣医師会との協定のもとで実施をさせていただいているものです。","voiceIndex":164,"id":"exchange-074"},{"speaker":"稲川委員","kind":"意見","question":"ちょっとまたここから外れてしまうかもしれないんですが、先ほど午前中の答えで、犬は登録制なので何匹登録されているかというのはわかると言っていたんですが、この猫の登録件数はもちろんわからないということなんですが、外れてしまうかもしれないんですが、例えば公園には砂場があると思うんですが、去勢をすることによって猫の子どもはどんどん減っていて、猫自体、野良猫は減っていくと思うんですが。","respondent":"藤田道路公園課長","answer":"ただいま砂場の衛生面ということだと思いますけれども、砂場につきましては、現在、地域の方と連携して、砂場がやはりどうしてもそういったおしっことかされやすい場所だということは認識しておりますので、例えばネットをかけるですとか。","voiceIndex":167,"id":"exchange-075"},{"speaker":"稲川委員","kind":"質問","question":"その砂に関しては、消毒とか、そういうことはしていないですか。やっぱり子どもは手でこうやって口に持っていったりするケースも多いので、その辺はどうかなと思いまして、お願いします。","respondent":"藤田道路公園課長","answer":"私ども、管理の中では、今、委員ご指摘のとおり、やはり砂場の砂は小さなお子さんが活用するですので、どうしても口に持っていったりとか、いろいろなことがありますので、消毒液で消毒をするとか、そういったことは避けている形で管理をしています。","voiceIndex":169,"id":"exchange-076"},{"speaker":"稲川委員","kind":"質問","question":"それとも、今はやりのＩＣチップやマイクロチップ、情報を入れたものを、強制はできないと思うんですが、首筋とかに入れるケースもあるというのを聞いているんですが、それがあることによって、例えば動物が死んでいる、そこでピッとやったらどこどこの飼い猫だった、飼い犬だったというのがわかるような、そういう仕組みも必要だと思うんですが、その辺、どうお考えですか。","respondent":"島袋品川区清掃事務所長","answer":"お墓もありまして、延命地蔵尊というお墓に祭ってある、そういうことです。動物の種類ですけれど、大部分が猫、あと犬が少々です。カラスなんかもありますけれど、そういうものがあります。","voiceIndex":171,"id":"exchange-077"},{"speaker":"稲川委員","kind":"質問","question":"やはり本当にこれだけお金をかけて、そこまで荼毘に付してやっておくと安心はしたところなんですが、やはりすべてが役所がお金を払ってすべてやるというのではなく、例えば先ほど申し上げましたマイクロチップなんかがあれば、その飼い主にそれを報告することもできますし、ゆくゆくは処理費の半分ぐらいはやっぱり飼い主責任という部分も追及できるのかなと、やっぱり動物愛護の観点で考えると。","respondent":"島袋品川区清掃事務所長","answer":"ちょっとつけ加えますけれども、一応、例えば都道とか、公園とか、こういうものについては無料なんですけれども、いわゆる敷地にあった、それからあと、飼い主は、有料でございまして、２,６００円いただいております。","voiceIndex":173,"id":"exchange-078"},{"speaker":"稲川委員","kind":"意見","question":"要するに、私、ちょっと言いたかったのは、轢かれてしまったその動物たち、もし飼い主がいるのであれば、その飼い主にやはり報告をするとか、そういう部分に対して、その対策とか、さっき言ったＩＣチップを埋めるのを義務、それは所管が違うのかもしれないんですが、今非常にはやっている部分、それは災害においても迷子犬とかになったときに、本当に高齢者のひとり暮らしの方も、動物。","respondent":"島袋品川区清掃事務所長","answer":"もし問い合わせがあった場合には、この犬ではないですかと、そういうことは清掃事務所がやっているところです。","voiceIndex":175,"id":"exchange-079"},{"speaker":"稲川委員","kind":"質問・要望","question":"今までの質問で私は何が言いたかったかというと、ほんとうにこの動物の愛護の観点から考えたときに、飼い主責任をしっかり追及して、人との共生が必要だと考えていますので、このＩＣチップとか、マイクロチップというのはどこが所管だかちょっと私もわからないので、ぜひ義務づけまではできないかもしれませんが、例えば登録するときとか。","respondent":"田村環境課長","answer":"カラスは特に産卵時、あるいは孵化、ヒナの生育時期に大変人間に危害を加えるということですので、今回、決算書に載っているのは、民有地の巣の撤去、あるいは落下ヒナの撤去という費用ですが、総合的に公園は公園、全体の窓口を区全体で統括しておりますので。","voiceIndex":177,"id":"exchange-080"},{"speaker":"武内委員","kind":"質問・要望","question":"私は、１３１ページのかかりつけ薬局機能推進事業と、１３４ページのメール配信サービス事業の２点、お伺いをしたいと思います。","respondent":"太田健康課長","answer":"かかりつけ薬局機能推進事業についてのお尋ねです。平成１８年度から荏原のほうがスタートしていました。その前に平成１８年３月から品川のほうが先にスタートをしていたところですけれども、平成１８年度は２カ所でやっております。","voiceIndex":180,"id":"exchange-081"},{"speaker":"武内委員","kind":"質問","question":"お聞きしたいなと思って、この前振りをさせていただいたんですが、実は区民の方から、私もそんなに数は多くないんですけれども、ジェネリック医薬品についてご相談を受けまして、私はあまり知らなかったので、いろいろインターネット等で調べて、また薬屋にも聞いてみたんですけれども、なかなか有効性というか、効用・効果というか、これが先発の特許の薬と比べて後発なので。","respondent":"山岡品川区保健所衛生課長","answer":"ジェネリック医薬品、後発医薬品のことだと思いますけれども、基本的には、成分、規格、これが先発医薬品と同一ですので、基本的には同一の効果・効能があるというふうに言われております。","voiceIndex":182,"id":"exchange-082"},{"speaker":"武内委員","kind":"質問","question":"同一の効果であれば安いわけですね。特許の分が切れるというか。その辺のところでそういったことが本区としてもお考えがあるのか、全く同じ効果で安ければやったほうが医療費も区の負担も安く済むわけですからいいんじゃないかなと思うんですけれども、その辺のご見解を教えてください。","respondent":"山岡品川区保健所衛生課長","answer":"それは自前の病院、例えば県立病院等、あるいは市立の病院等を持っているところで、その病院ではそういう方針でできるだけジェネリック医薬品を出していこうと、基本的に問題ない場合はジェネリック医薬品を出していこうと、こういうふうに考えてやっているところはあります。","voiceIndex":184,"id":"exchange-083"},{"speaker":"武内委員","kind":"質問・要望","question":"ぜひ研究していただきたいと思います。その辺の実績が少ないのに増額したということは、何らかの理由があるんじゃないかと思いますので、そのことについて教えていただきたいのと、あと以前にも出ていたかもしれませんけれども、ごみの収集と環境講座みたいなものもお知らせしているということなんですが、どの辺まで今後これを活用していこうと考えていらっしゃるのか、教えてください。","respondent":"秋山資源循環推進課長","answer":"お尋ねの予算的なところですけれども、明治大学との実証研究ということでございまして、平成１８年度に明治大学のほうに共同研究費ということで３００万円をお支払いして、このシステムをつくったところです。","voiceIndex":186,"id":"exchange-084"},{"speaker":"武内委員","kind":"質問・要望","question":"例えばチーム・マイナス６％ですか。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-085"},{"speaker":"渡部委員","kind":"質問","question":"１２９ページ、食品衛生許可監視指導および食中毒原因調査、および時間がありましたら、１３１ページ、公害保健費の中の公害健康被害補償事業についてお伺いします。この１２９ページに記載のあります項目の中で幾つかお伺いしたいと思います。そこの乖離があります。このような委託で事業者が行った場合、これはまた営業許可に当たっているのかどうなのかを１点お聞かせください。","respondent":"平澤品川区保健センター衛生課長、山岡品川区保健所衛生課長","answer":"こちらの委託経費です。事業規模に比較して金額が少ないですが、自前の検査につきましては、次のページ以降に記載されてあります衛生課の検査室のほうで実施しておりますので、この金額になっております。最後の食中毒、１件について、これは保健所管内で昨年起こったものですので、私のほうからお答えします。これはある定食を中心に出している飲食店、定食屋というんでしょうか。","voiceIndex":190,"id":"exchange-086"},{"speaker":"渡部委員","kind":"質問","question":"そうすれば、公立学校であれば、委託業者になっても営業許可の必要はない。事業所が調理業務をやっていても、それに食品衛生法上の営業許可が発生しなくていいということでしょうか。","respondent":"平澤品川区保健センター衛生課長","answer":"さようです。","voiceIndex":195,"id":"exchange-087"},{"speaker":"渡部委員","kind":"質問・要望","question":"さきの一般質問において、実は今日、学校給食のことを確認させていただきたかったのが、ほかの委員からのご質問の中で、ある程度この食材の扱いに関してですが、たしかその業者の責任の中でみたいな答弁があったかと、ちょっと聞き間違えていたら申しわけないんですが、そのような答弁があったような形がありまして、その辺の許可の問題等も確認を今させていただきましたら、やはり学校の中ということで。","respondent":"平澤品川区保健センター衛生課長","answer":"この問題につきましては、保健所のかかわりについてご報告申し上げます。食材に関しましては、年に２回、５月と１０月なんですけれども、代表校２つにつきまして、食材の細菌検査を実施しております。","voiceIndex":197,"id":"exchange-088"},{"speaker":"渡部委員","kind":"確認","question":"成分検査はいかがでしょうか。成分検査をやることによって、その商品がちゃんとしたものが入っているかどうかという確認がとれると思いますが、いかがでしょうか。","respondent":"平澤品川区保健センター衛生課長","answer":"今のところ成分検査については実施してございません。","voiceIndex":199,"id":"exchange-089"},{"speaker":"渡部委員","kind":"質問","question":"昨今表示上の問題、白い恋人は表示上の問題だったと思うんですけれども、ミートホープ等のコロッケの偽装って成分ですよね。その辺は絶対必要だと思うんですが、進められますでしょうか、どうでしょうか。","respondent":"古里学務課長","answer":"学校給食においては、加工食品等については一切使用してございません。","voiceIndex":201,"id":"exchange-090"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"不法投棄物の関係でお聞きしたいんですが、決算上１５０万円ほどの決算が出ております。この金額をどう評価するか。３分の２助成の６０万円というのが出ていたんですが、ＩＳＯを取得するのも大変なんですけれども、その後ＩＳＯをずっと継続していく企業にとって、企業の負担という点を、何かこういう後の事後調査というか、区のほうにはそういう確認をとっているようなことはあるんでしょうか。","respondent":"島袋品川区清掃事務所長、藤田道路公園課長、金子産業振興課長","answer":"以前はかなりあったんですけれども、前年は７１０、今年が１,３００ぐらいに増えております。主なものですけれども、例の家電リサイクル品がありますね。目黒川、立会川の関係ですけれども、最近はあまり不法投棄の話は聞かないんですけれども、以前は自転車があったとか。ただＩＳＯ９０００シリーズと１４０００シリーズと両方支援しているわけですが、１４０００シリーズに関しましては。","voiceIndex":204,"id":"exchange-091"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そうすると、その投棄された人は自分が処理しなきゃいけなくなっている状況ですよね。これがどこまで認知されているかということはあるんですけど、国土交通省の推奨している中で、そういう方たちとすると、経費面で多少でも安い形をとりたい、こういう認証は取っていきたいんだというお話は聞いているんですが、この辺、担当の部署として何か情報をお持ちであれば、教えていただきたいなと思うんですが。","respondent":"松嶋交通安全担当課長、田村環境課長","answer":"しかしながら、そこでこれを撤去していただきたいという話になったときには、これは即時強制の部分ですので、私道の管理者の明確な意思があれば、区のほうとしても協力をしていきたいと考えております。私のほうから、今、委員お尋ねのグリーン経営認証取得ということでお答えしますが、これは特に交通関係、運輸業界を対象に、中小規模の事業者でも、容易かつ継続的に環境保全に取り組みのできるグリーン経営。","voiceIndex":208,"id":"exchange-092"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後のグリーン経営認証のほうは、これはそういう状況の中では、区としてはあまりまだ考えていないという、例えばその助成とか支援的なものはまだ考えていないと判断していいでしょうか。自転車のほうは大変厳しいと思うんですけれども、その辺、何かいい方法がとれないかなということ、それは要望しておきますけれども、グリーン経営のほうだけもう１回。","respondent":"田村環境課長","answer":"実態を踏まえて、内容をもうちょっと詳細に調べて、状況を把握して、話し合いを進めてみたいと思います。","voiceIndex":211,"id":"exchange-093"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"まだ不燃ごみが多いお宅も見かけるんですね。実際うまく仕分けしていけば、ほとんど不燃が出てこないというのが、周りの方からも大分お聞きしました。ですから、周りの方にお聞きしていても、せっかくマイバッグを持っていって今まで買い物をしていたけれども、これが増えちゃうとレジ袋が必要だねという声が出ています。その辺をどう考えていったらいいかなと、ちょっと考え方を２点お願いします。","respondent":"秋山資源循環推進課長","answer":"マイバッグとレジ袋等の考え方ですけれども、マイバッグの運動というのは、レジ袋をなるべく減らす生活をですので、片や今度の分別の変更で、ごみの出し方は、袋に入れてそれぞれ別に出してくださいということでお願いをしていますけれども。","voiceIndex":213,"id":"exchange-094"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ちょっと最後に気になる部分もあるんですけど、前半のほうとして、ふれあい指導班の方ですか。パッケージの商品を買ってきたものをそのまま出してしまっている。この補てんというのは、基本的にどこがそれを補てんしていくのかという点を、ちょっとご確認させてください。区としてその補てんを考えていくのか、それとも２３区全体なのか、事務組合が考えていくのか、その点はどうなんでしょうか。","respondent":"秋山資源循環推進課長","answer":"東品川の雇上業者の件ですけれども、不燃ごみの減少につきましての雇上業者の対応につきましては、２３区全体で考えていくです。","voiceIndex":215,"id":"exchange-095"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"あそこの施設、品川区の所有になっていますよね。目的として用途制限がついていると思うんですけど、これから区としてうまくそこを活用していただいて、例えば資源化センターみたいなものにならないような形で、あそこは天王洲のいい場所ですから、観光の拠点にするとか、そういう形を早急に検討していただきたいなと思いますので、これを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":217,"id":"exchange-096"},{"speaker":"市川委員","kind":"質問・要望","question":"私のほうからは、成果報告書１３２ページのマイバッグ運動の推進、１３４ページの廃棄物減量等推進員、それから、このページでメール配信事業の回答についての質問を少しさせていただきたいと思います。それから、マイバッグ運動推進事業の２００６年度の実績を教えてほしいんです。事務事業概要のところでは２００５年度までが出ていたんですけれども、２００６年度について教えてください。","respondent":"田村環境課長","answer":"その中でも、エコスポットだとか、商店街の中にそれぞれ１１カ所ありますけれども、缶だとかペットボトルをリサイクルするエコスポットというのを管理をお願いしたり、あるいはフェスティバルなんかも商店街連合会中心でバックアップして実施したり。","voiceIndex":219,"id":"exchange-097"},{"speaker":"市川委員","kind":"質問・要望","question":"実績について数字でお知らせいただきたいんですけれども。","respondent":"田村環境課長","answer":"それと、先ほど申し上げましたエコスポットの設置１１カ所ですけれども、そこでの回収量が、ペットボトルが２１４万４,９６７本、アルミ缶が３１６万７９０本、スチール缶が１１０万４,０９６本、合わせて６４０万９,８５３本です。","voiceIndex":221,"id":"exchange-098"},{"speaker":"市川委員","kind":"質問","question":"他の自治体の情報として、杉並区では、今年の１月にレジ袋有料化実証実験をして、マイバック持参率が４３％から８５％に増えた。これを機会に、市民と事業者と行政がそれぞれの立場で話し合えるテーブルが有効に機能しているという情報もいただいたんですけれども、このレジ袋有料化ということに対しては、品川区はどういう見解を持っているのかお聞きします。","respondent":"田村環境課長","answer":"委員お尋ねの、当初、杉並区は平成１４年３月、杉並環境目的税とレジ袋条例を検討していたんですが、いろいろ反対等がありまして、それを新条例として、レジ袋有料化推進条例ということで、来年４月施行に動き出しているという情報です。","voiceIndex":223,"id":"exchange-099"},{"speaker":"市川委員","kind":"質問","question":"わかりました。そういう見解だということで認識をしておきます。品川区も数値目標を持って、その動向を区民に知らせて啓発を進めていくという、そういうレジ袋の利用を減らすという積極的な方策も考えていいんじゃないかと思っているんですけれども、その辺はいかがでしょうか。","respondent":"田村環境課長","answer":"環境については、午前中にもお話ししたように、まだまだいろいろな取り組みはしているんですが、区民の方の意識も２６％前後ということで、あらゆる機会を利用して、まずレジ袋有料化ありきじゃなく、いろいろな機会をつかまえてマイバッグと。","voiceIndex":225,"id":"exchange-100"},{"speaker":"市川委員","kind":"質問","question":"１３４ページのメールサービスの配信事業について、回答の中での質問なんですけれども、回答の中に延べ８４７人という回答があったと思うんですけれども、この延べというのはどういう意味なのかということと、それから、この数字は平成１９年２月からこの事業が始まったということなんですけれども、年度末までの数字なのか、それとも２月から現在に至るまでの数字なのかということと、それから。","respondent":"秋山資源循環推進課長","answer":"３点ご質問をいただきました。","voiceIndex":227,"id":"exchange-101"},{"speaker":"市川委員","kind":"質問・要望","question":"先ほどの質問の中にもありましたように、高額な予算をつけてやっているものなので、ぜひ検証というところはしっかりやっていっていただきたいなと思います。次の質問なんですが、１３４ページの廃棄物減量等推進員について伺います。この推進員はどのような構成で人数がどうなっているのかと、それから、どういうことを役割にしているのかということをお聞きします。","respondent":"島袋品川区清掃事務所長","answer":"この廃棄物減量等推進員ですけれども、２０歳以上の区内在住・在勤の方で、ごみ減量やリサイクル活動に協力できる方を公募もしくは推薦してもらいまして、区長が委嘱しているものです。人数ですけれども、上限としては６００名ですけれども、現行の人数は５０３人です。","voiceIndex":229,"id":"exchange-102"},{"speaker":"市川委員","kind":"質問","question":"公募だということなんですけれども、公募の方がそのうちのどれぐらいの割合でいらっしゃるのかということと、それから役割について伺ったので、そこのところの回答もお願いします。","respondent":"島袋品川区清掃事務所長","answer":"町会推薦と公募推薦ということでございまして、大体公募の方が１００名ぐらいだです。それから役割ですけれども、ごみ減量およびリサイクル活動に関する会議や研修などへ参加してもらう。","voiceIndex":231,"id":"exchange-103"},{"speaker":"市川委員","kind":"提案","question":"町会推薦とかでは、いろいろな役割を町会では担わなくてはならなくて、区民のためにありがたいなと思っているんですけれども、ステーション収集が戸別収集に変わってから、なかなかこういう推進員の役割を果たしていくというのは難しいかなと。役割とか当番で構成されている今の体制を見直して、関心がある個人が参加できる仕組みに転換するということを提案しますけれども、ご見解はどうでしょうか。","respondent":"島袋品川区清掃事務所長","answer":"それから今回、いわゆるプラスチックごみの分別変更ですけれども、このようなときにも、推進員の方、各地区１３地区ありますけれども、そちらのほうに去年集まってもらって、こういう分別変更をやってもらうということで広めてもらう、そういう役割もありましたので。","voiceIndex":233,"id":"exchange-104"},{"speaker":"市川委員","kind":"質問","question":"次の質問に移らせていただきます。１３９ページのベンチャー創業支援について伺います。入居期間の回転実績はどのように変化しているのかということと、また、西大井の創業支援ブースという小さなブースのほうの出入りの状況はどうなっているのかということについて伺います。","respondent":"金子産業振興課長","answer":"品川ベンチャー創業支援センターのブースのほうですけれども、１０ブースがありまして、こちらは最高３年ですので、当初からの方についてはすべて出ているということで、かなりカウントするのが難しいんですが、今まで出た方は全部で１６件です。","voiceIndex":235,"id":"exchange-105"},{"speaker":"市川委員","kind":"質問","question":"創業支援として１０年というのはあまりにも長いかなと思うんですけれども、創業支援といえば独立までの力をつけるという期間になるんじゃないかと思うんですけれども、適当な期間としては二、三年なのかなという感じがしますけれども、まず最長１０年と決めた理由は何なんでしょうか。","respondent":"金子産業振興課長","answer":"製造業というのは難しい業種でありまして、品物をつくって評価されるというまでには一定の時間がかかると考えておりますので、この１０年がいたずらに長いというふうには考えておりません。","voiceIndex":237,"id":"exchange-106"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"よろしくお願いします。私のほうからは、成果報告書の１２８ページ、予防費の中のエイズ相談、そして検査についての質問を幾つかします。初めに、この１２８ページに載っております相談件数６５３件、そして検査が３１４件とありますが、この相談と検査の年代別での数がありましたらお教えいただきたいのと、なぜ相談が６５３件に対して検査が３１４件になっているのか、ご説明をよろしくお願いします。","respondent":"倉橋品川区保健所保健サービス課長","answer":"そのときにも検査前の相談という形で相談を承ります。その後、検査が判明した結果通知のときに、それでまた結果がわかった段階でのまた相談、これは内容が若干変わります。その相談をダブルカウントという形でしておりますので、実質的には３００何がしというものが実数です。","voiceIndex":240,"id":"exchange-107"},{"speaker":"石田（慎）委員","kind":"意見","question":"そのことによって、性交渉によって若者の感染拡大が予想されるんですが、今の段階で、その予防の１つとして、しっかりとした教育というのが必要となると思うのですが、性教育についての現状、そして今後の展望についてお聞かせください。","respondent":"倉橋品川区保健所保健サービス課長","answer":"これに合わせて実施して、教育・普及に努めているところです。","voiceIndex":242,"id":"exchange-108"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ぜひとも性教育についてしっかりと、予防に一番つながるのはやっぱり教育だと思うので、ぜひ今後とも進めていただきたいと思います。日本では非常に受診率が低い。これは非常に体制として私はすばらしいものだと思うのですが、品川区として今後このような委託医療機関等と連携をして、検査の期間の幅を広げるというお考えはおありでしょうか、お知らせください。","respondent":"倉橋品川区保健所保健サービス課長","answer":"そのほかの回数ですが、これは東京都全体の検査の体制というものが、東京都の主導で２３区、多摩地域保健所、３３カ所で、各曜日、時間帯などをまんべんなくといいますか、分散させて、必ず検査が受けられるような形で配分して、調整して実施していますので。","voiceIndex":246,"id":"exchange-109"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"もちろん質という意味で、非常に質がいいものを今後も行っていただきたいんですが、毎月４回、しかも午前中の短い時間帯というのは、非常に範囲が狭まってしまう。その中で土日に検査ができないのは、予防という意味でも、いつ感染するのかもわからないという現状ですので、一刻も早く検査をしていただくために、ぜひとも土日等も検査を行っていただきたいと思います。強い要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":248,"id":"exchange-110"},{"speaker":"若林委員","kind":"質問・要望","question":"乳がん検診について、当然それまで早期発見また早期治療のために、本区としても着実に取り組みをされて、私どもも拡充を求めてまいりました。それから健康づくり推進のほうです。この２つの後段のほうの地域健康づくり支援事業と健康づくり推進事業というのが同じなのかなと思ったんですが、内容が比べられませんでしたので、教えていただきたいということが１つ。","respondent":"太田健康課長","answer":"３点目の区民健康づくりの関係ですけれども、お尋ねの地域健康づくり支援事業ですけれども、この平成１８年度の決算に載っています内容については、各地域における健康づくり活動の指導者の養成、あるいはそのレベルアップの区民健康づくりを指導するということで。","voiceIndex":250,"id":"exchange-111"},{"speaker":"若林委員","kind":"質問・要望","question":"健康づくりのほうは、１つご答弁漏れはあったんですが、それはまた個別にお聞きするとして、区が事務局として入っているということでございましたので、協議会また委員からの、地域からの要望というのもしっかりと受けとめていただく機会、そういう場面を、毎回の協議会の中で承っていると思うんですが、それを事務局としてしっかり受けて、そして大事なことは。","respondent":"太田健康課長、原国保年金課長","answer":"罹患率等については、ご指摘のとおり、今後の部分で制度管理を高めるなりということを見ながら、将来的には検討していきたいと考えています。健診項目につきましては、国のほうで医療関係者が集まって検討して決められたものです。しかしながら、区民健診で項目等を増やしてやってきた経過もありますので、その辺を含めて今、関係各課あるいは医師会等と検討しています。","voiceIndex":252,"id":"exchange-112"},{"speaker":"高橋委員","kind":"質問","question":"成果報告書の１３１ページの保健所のことでお聞きしたいと思います。保健所の業務について、衛生が中心だと思うんですが、簡単に教えていただけたらと思います。","respondent":"山岡品川区保健所衛生課長","answer":"衛生課の業務についてお答えいたします。衛生課につきましては、主に環境監視が中心です。食品衛生監視、環境衛生監視、それから医薬の関係の監視指導、これが衛生課の中心になります。は畜犬の登録等の事務も行っております。","voiceIndex":256,"id":"exchange-113"},{"speaker":"高橋委員","kind":"質問","question":"北品川に品川区保健センターというのがあると思うんですが、そちらも今の保健所と、医事衛生の面などを含めると、同じ業務をされていると考えてよろしいでしょうか。","respondent":"平澤品川区保健センター衛生課長","answer":"ご指摘のとおりです。","voiceIndex":258,"id":"exchange-114"},{"speaker":"高橋委員","kind":"質問","question":"ということは保健所が２つですよね。どうして保健センターのほうは保健所と言わないんでしょうか。","respondent":"山岡品川区保健所衛生課長","answer":"ただし今までに保健所でやっておりました業務を、地域割りしてほとんど同じ業務を保健センター、旧品川保健所の業務を保健センターの業務として引き続いてやって、サービス低下が起こらないようにということで、２所体制でやっているところです。","voiceIndex":260,"id":"exchange-115"},{"speaker":"高橋委員","kind":"質問","question":"ということは２つなんですけれども、その辺は法に抵触しないんでしょうか。それがこの形で続いているということは大丈夫なのか、ちょっとわからないんですが、お願いします。","respondent":"山岡品川区保健所衛生課長","answer":"特に法律に抵触するということはございません。あくまでも保健所があって、その中に保健センターがあるという位置づけです。ただし仕事の分担を地域で割っているですので、問題はないかと思います。","voiceIndex":262,"id":"exchange-116"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、もう１つ、保健センターのほうは年間７億円でしょうか。保健所のほうは５億円、これにプラスアルファがあると思うんですが、民間の活力や技術力あるいは行政改革の面から、どちらか医療法人や財団法人、医師会なども、もし可能でしたら、そういう外部に委託することというのは可能なんでしょうか。","respondent":"山岡品川区保健所衛生課長","answer":"今のご質問は、保健所業務の委託ということでございましょうか。保健所業務は保健所でやらなくてはいけないということで地域保健法で決まっておりますので、ちょっとそれはできかねるかなと思います。","voiceIndex":264,"id":"exchange-117"},{"speaker":"高橋委員","kind":"質問","question":"保健所と保健センターとありますので、保健センターのほうを外部委託という聞き方をしたほうがいいんでしょうか。","respondent":"山岡品川区保健所衛生課長","answer":"保健センターでやっている業務も保健所の業務です。ただ地域割りをしてやっているということだけですので、保健所の業務を２つに割ってやっているです。ですから、保健センターの業務につきましても保健所の業務と同じです。","voiceIndex":266,"id":"exchange-118"},{"speaker":"高橋委員","kind":"質問","question":"もう少し勉強します。今のお話の続きになるんですが、別の話で、大井保健相談所とか衛生関係ですか、検査室でしょうか。こういうものを行革の面やそういうところから、こちらを外部に委託するということは可能でしょうか。","respondent":"古川児童保健事業部長","answer":"ただ個別の業務につきましては、これは区の業務も同じですけれども、さまざまな民間活力の活用ということでは、保健所業務の中におきましても、さまざま正規職員以外で取り組んでいる、執行方法については。","voiceIndex":270,"id":"exchange-119"},{"speaker":"高橋委員","kind":"質問","question":"１３２ページのほうに環境相談費というのがあるんですが、たばこの話は以前に別の款で出てきたんですが、歩きたばこなどの苦情などもここに来たりしているんでしょうか。なぜかといいますと、青物横丁から品川シーサイドのところに、シーサイドから京浜急行に乗りかえるところで随分歩きたばこの方が多くて、多くの住民の方が迷惑しているということです。","respondent":"田村環境課長","answer":"こちらの環境相談については、たばこのポイ捨て等の関係の相談ではございません。","voiceIndex":272,"id":"exchange-120"},{"speaker":"高橋委員","kind":"質問","question":"たばこのほうはこちらではなくて、直接どちらのほうでしょうか。","respondent":"田村環境課長","answer":"地域活動課が所管していて、ポイ捨ての関係は生活安全担当課長が所管しています。","voiceIndex":274,"id":"exchange-121"},{"speaker":"松澤委員","kind":"質問","question":"短く２点お伺いしたいと思います。４款衛生費、１項保健衛生費、４目保健指導費、成果報告書の１３１ページです。かかりつけ医機能推進事業、かかりつけ歯科医機能推進事業、かかりつけ薬局機能推進事業とありますけれども、この決算が３００万円、７４４万円、２７８万円とありますけれども、１つは目的と事業の内容についてお伺いしたいと思います。","respondent":"太田健康課長、田村環境課長","answer":"そこの医師会の窓口にかかりつけ医を持たない区民が医師の紹介、あるいは訪問診療を必要とする区民の対応可能な医師の紹介をするという事業です。かかりつけ歯科医も同様なお話です。土壌汚染については、ここ数年ほかの相談業務に比べて増えているという状況で、ここのところ、平成１６年度からですが、６１６件、８２２件、１,３１３件ということで増えているということで、法律ができて。","voiceIndex":280,"id":"exchange-122"},{"speaker":"松澤委員","kind":"質問・要望","question":"かかりつけ医のほう、目的と事業内容をお聞きしました。何でこんなに費用が違うのかなというので、その辺をお伺いしたいと思います。それと２点目ですけれども、アスベストの件についてなんですけれども、アスベストの相談というのはどんな内容があるのか、ちょっとこの内容をお知らせいただきたいと思います。","respondent":"太田健康課長、田村環境課長","answer":"かかりつけ歯科医の事業の内容につきましては、もうちょっと医師会のほうに委託している内容よりも広がってございまして、区民等の地域歯科医療の相談に応じることと、それから従来。アスベスト苦情相談の内訳で、内容ですが、例えば平成１８年度で言いますと、建築中のアスベストについての相談が２９件、分析処理業者の紹介等が３件、解体時の手続についてが１１件、行政への要望等が２件、その他融資。","voiceIndex":283,"id":"exchange-123"},{"speaker":"松澤委員","kind":"確認","question":"かかりつけ医機能のほうは、今度改めて現場を確認しながら、お話を伺いながら、改めてしたいと思います。ただ決算なので、かかりつけ医機能推進事業、これは３００万円ぴったりの決算になっているので、予算でも３００万円何がしという半端が出ているんですけれども、決算がぴったりなので、おもしろい決算だなと思ったものですから質問させていただきました。答弁は結構です。それを聞きたいと思います。","respondent":"齋藤住宅課長","answer":"助成制度についてのご質問ですが、あっせんをする制度はあります。天井に吹きつけのものがあったときにリフォームをする工事費を、区内の信用金庫に融資のあっせんをいたしまして、０.９％の利率でお貸しをするようにしておりまして、平成１８年度に２件ほど実績があります。","voiceIndex":286,"id":"exchange-124"},{"speaker":"松澤委員","kind":"質問","question":"アスベスト除去工事については住宅修繕資金融資あっせんというのがあるんですよね。今のはその件だろうと思いますけれども、大田区なんかですと、これはアスベストかどうかを検査してもらう、これにも助成があるんですよね。品川は環境に優しい品川といいますけれども、何で品川区にはこれに対する助成制度がないのかな、検査に対してね。その辺をしっかりとお聞きしたいと思います。","respondent":"齋藤住宅課長","answer":"あっせんの件数が伸びないので、土建組合の皆さんとか住環境協議会の方にご相談をいたしましたら、基本的に吹きつけの部分については、区内でほとんど終わっているのではないでしょうかというお話をいただいておりまして。","voiceIndex":288,"id":"exchange-125"},{"speaker":"松澤委員","kind":"意見","question":"おおむね終わっているのかもしれませんが、私が見ているところは、歩いていてあるんだからまだあるんですね。そんなのから見ると品川区は、件数がないならそれに越したことはないですけれども、助成制度、１件でも２件でもあったらつくるべきだと思いますので、さらにお願いいたします。","respondent":"齋藤住宅課長","answer":"こういったものも含めて今後ご相談があると思いますので、助成制度をどのような形で相談させてもらうのがいいか、これは検討してまいりたいと考えています。","voiceIndex":290,"id":"exchange-126"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１２９ページの精神保健福祉と１２８ページの保健事業費についてお伺いさせていただきたいと思います。病院に行けない人のために往診という制度というのはないのか、また保健所としてこういう方に相談できますよ、相談体制はこうなっていますよ、困っている方はどうぞ相談においでくださいというお知らせというか、ＰＲをもっとしていただきたいなと思うんですけれども、いかがでしょうか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"往診につきましては、精神保健相談の専門医がございまして、必要に応じましてケースの検討をした結果、必要な場合には、その先生に往診といいますか、出張して現場を見ていただき、診察をしていただくということもままあるケースです。","voiceIndex":293,"id":"exchange-127"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、増税等負担増が大変なときですから、そのメリットというのは大きいと思うんです。それと医療は年に１回の更新が必要だと思うんですが、そのときに手帳ですとか年金とかを取っているという方は把握されていると思うので、まだ手続をされていないという方には、ぜひ勧めていただきたいと思うんですが、いかがでしょうか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"自立支援医療になって年に１回ということになりましたので、お届けいただく書類を受け取る機会、接触する機会もあるようになりましたので、ご指摘のように、その機会を生かしまして、享受できるメリットにつきましては。","voiceIndex":295,"id":"exchange-128"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民健診の中で、またこれも品川の保健衛生の中で、生活習慣改善指導事業というのがあると思うんですが、今年で区民健診も終わりますし、事業は終了になりますけれども、健診の結果、糖尿病、高血圧の要指導に該当する方に指導していくということなんですけれども、この該当者の人数、指導を受けた人数、指導の結果の改善状況について１つお聞かせいただきたいと思います。","respondent":"太田健康課長","answer":"２点目のがん検診についてのお尋ねですけれども、老人保健法に基づいて今、実施していますがん検診については、来年の４月以降は健康増進法に基づく市町村の新たな保健事業ということで、基本的にそのまま引き継いでいくということになっております。","voiceIndex":297,"id":"exchange-129"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"内容面と費用面、それからあとは今度の特定健診になりますと、特定保健指導というのも入ってくると思うんですが、今の生活習慣改善指導事業と今度の特定保健指導というのは、すごく似ている部分があると思うんですが、実際、区民健診の中でこんな実績しかないのに、特定保健指導が機能していくんだろうかという思いがあるんですけれども、いかがでしょうか。","respondent":"太田健康課長、原国保年金課長","answer":"健診結果説明時に第１回の指導をして、２カ月後に第２回、約６カ月後に第３回と半年かかって指導するということで、希望者が極めて少なかったということが現実だろうと考えています。基本的にはそれを重視しながら実施してまいるわけですけれども、今までの区民健診でやったという経過もありますので、そういったところを医療保険者として、この生活習慣病を含めてどういうふうに実施していくかという中で。","voiceIndex":299,"id":"exchange-130"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この財源を見ても、５億７,０００万円ぐらい区民健診にかかっているわけですね。それが今度はなくなるわけですよね、区民健診がなくなってしまうわけですから。それともう１つは、来年から始まるこの特定健診というのは、国民の健康をどう守っていくかというよりは、いかに医療費を抑えるかということから出発している制度だと思うんですね。","respondent":"原国保年金課長","answer":"無料の件です。こちらにつきましては、先ほど申し上げましたように、国の負担金等々のものがこれから出てきますので、そういったことが出たところで含めて考えていくです。","voiceIndex":302,"id":"exchange-131"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"厚生労働省の出身の方も、これは不健康な者を穀潰し扱いにする構造だと言っているんですが、健康で生活する権利は憲法で保証されていますので、これをぜひ区として考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-132"},{"speaker":"西本委員","kind":"質問","question":"質問に入る前に、製品と資料の提示をお願いしたいんですけれども、よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":306,"id":"exchange-133"},{"speaker":"西本委員","kind":"質問","question":"私から１３２ページ、エコクリーン店・事業所認定事業と、１３０ページの「区民健康づくりプラン品川」についてお聞きいたします。エコクリーン店ですが、これは目的は何で行われているのかというところ、それから「区民健康づくりプラン品川」においてですが、今、３大死亡要因というのが、第１位ががん、２位が心疾患、３位が脳血管疾患とあるわけですけれども、品川区の実態をお聞きしたいと思います。","respondent":"太田健康課長、田村環境課長","answer":"品川区の実態です。平成１８年度ですけれども、２,６６３人が亡くなられているです。死因の１番が悪性新生物、がんです。がんが８８３人。２番目の心疾患が４２１人、同列ぐらいで肺炎と脳血管疾患ということとになってあります。私のほうからエコクリーン店の認定事業ですが、環境と共生するまち品川を目指して、環境保全に配慮した取り組みを自主的かつ積極的に実施している小売店をエコクリーン店と認定しまして、これを広く区民に公表しまして。","voiceIndex":308,"id":"exchange-134"},{"speaker":"西本委員","kind":"質問","question":"エコクリーン店ですが、ホームページを見ました。これを今後どうされるのかというところをまずお聞きしたいです。それから、先ほど３大死因、死亡の原因としてはがんが第１位ということでありますが、がんは確かに１位ではあるんですが、これはいろいろながんがあるんですね。４人に１人は死亡しているというのが現状です。この心疾患に対して、品川区としてのお考えについてお聞きしたいと思います。","respondent":"田村環境課長、太田品川区保健センター大井保健相談所長","answer":"そういう意味からしますと、「地球にやさしいお店発見」の新しい事業ですから、それが順調に進めば、ＰＲ活動が進んで、効果があるようでしたら、エコクリーン店認定事業を、今のところ予定ですと平成２０年度まで実施して。それでメタボリック症候群の講演会や、いろいろな生活習慣病改善指導事業等を行っております。突然死につながるような事故に対しては、ＡＥＤを人が集まる施設に設置しております。","voiceIndex":311,"id":"exchange-135"},{"speaker":"西本委員","kind":"質問・要望","question":"定期健診もあります。ですから、やはり自己管理というのがいかにしやすくなっているか、そういう環境にあるのかということが必要ではないかなというところで、最近私が知った中でおもしろいシステムをお聞きしましたので、ちょっとここでご紹介したいと思います。これの測り方ですが、手のひらで３０秒間心電を測定します。ですから、これは非常にいろいろなところで応用できるのではないかと考えております。","respondent":"倉橋品川区保健所保健サービス課長","answer":"ご指摘の新製品、新技術ということで、心臓に不安があった場合に、ホルター心電図と申しまして、１日中心電図をとるというものがありますけれども、携帯型の心電計の活用はまだ限界もありますので、有効な方策を探って、取り入れる形を検討していきたいと考えています。","voiceIndex":314,"id":"exchange-136"},{"speaker":"三上委員","kind":"提案","question":"１年以内に感染した乳児の３人に１人はウィルスが下気道まで侵入し、うち５％が入院すると、赤ちゃんにとってみると基本的に気をつけなければならないというウィルスであるようでありますけれども、こういったことについて、日ごろの手洗いが絶対に欠かせないという予防の第一条件があるんですけれども、こういったことに対しての保健所としての母子相談的な部分について。","respondent":"倉橋品川区保健所保健サービス課長","answer":"これにつきましては、ご指摘のように、医療機関での発見治療がまず第一ですけれども、保護者の方々の知識というものも大事なものですので、両親学級、そのほか普及・啓発活動におきまして、健診、早期が中心ですが、そのような形で機会を活かしまして。","voiceIndex":317,"id":"exchange-137"},{"speaker":"三上委員","kind":"提案","question":"ちょっと順序が逆になりますけれども、１３３ページの緑化推進費、続いて１３０ページから１３１ページの保健指導費の中の保健衛生費についてお伺いしたいと思います。壁面緑化をもっと手を入れてきちっと管理していけば、せっかくやったものを取り外さなくても済んだのにと思ってきたんですけれども、さらにまた平成９年の第４回定例会で屋上緑化ということについても、具体的に提案しました。","respondent":"藤田道路公園課長","answer":"現在、品川区のほうでは、平成１４年から屋上緑化あるいは壁面緑化についての助成を開始したところです。現在の民間の屋上緑化あるいは壁面については、１,０００m2以上については品川区みどりの条例の中で義務づけながら進めているところです。","voiceIndex":319,"id":"exchange-138"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、小さな形でやっているということではなくて、それなりにお金もかけながら、そういう緑のカーテンの運動というものを品川全域に広げていく必要があるんじゃないかと思います。この総合庁舎の中で、耐震工事をやるからということでやりませんという本会議での答弁がありましたけれども、それはそれとしてできるところもあるわけですから、それなりに考えていっていただきたいと要望しておきます。","respondent":"川口品川区保健センター保健サービス課長","answer":"最後のご質問ですけれども、いわゆるキレるという子どものそういうご相談があるかですけれども、我々保健所・保健センターでは、小児健康相談という事業を決算書にも載せてありますけれども、その中でいろいろなご相談を受けて対応しています。","voiceIndex":321,"id":"exchange-139"},{"speaker":"三上委員","kind":"質問・要望","question":"そういう管理をしているということの、ゲームの怖さというものをよく知っているということで、今日は時間がありませんからこれ以上やれませんけれども、そういった点でのゲームの習慣性といったことについての、品川区としても研究をぜひしていっていただいて、こういうことについて注意をすべきであるという啓発的な部分で発信をしていっていただきたいなと思いますが、いかがでしょうか。","respondent":"川口品川区保健センター保健サービス課長","answer":"ただいま委員のお話にもございました脳神経学的ないろいろなことをご教授いただきました。区としましてもまだ研究の段階ですけれども、研究したいと思います。","voiceIndex":323,"id":"exchange-140"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"有料ごみの処理券の経費は、事業系の一般廃棄物のところでいきますと、事業系、ただシールを張ってくださいという部分と、基本的に事業系の一般廃棄物は自分たちでどういうふうにするかという事業者のものがあるとするならば、一度品川区はそういう事業者を、中小企業対策というのはわかるけれども、登録してもらうなり何なりのリストづくりみたいなことは、シールを売ればいいということだけではなくて。","respondent":"島袋品川区清掃事務所長、秋山資源循環推進課長","answer":"集団回収につきましては、石田委員がおっしゃったとおり年々増えておりまして、今は４７１団体です。前回が４３８団体だったので、大変増えております。委員がご指摘になりました事業者の登録制度ですけれども、そういう制度も必要なことではないかと考えています。","voiceIndex":326,"id":"exchange-141"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"集団回収なんだけれども、ごみの減量と有効活用に非常に効果があったということなんだけれども、今、数が例えば年間３０ぐらいずつ増えている。これはマンションなんだよね。そういうことをどうとらえていらっしゃるかというのを教えていただきたい。これも１つのやり方ですよ。そういう事前の準備というのは必ずするべきだと思うんだけれども、そこら辺の見解をもう一度お願いします。","respondent":"島袋品川区清掃事務所長、秋山資源循環推進課長","answer":"そういう前提で、多少専門的な管理人になってくるんですけれども、やっぱりマンション全体の住民の協力が必要だということで、いわゆる集団回収の１つの団体として考えるのが適当ではないかと思っているところです。その中で登録制度というのは、非常にそういうものを進めていく上で有効な手段であるというふうには考えておりますので。","voiceIndex":329,"id":"exchange-142"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"集団回収のところなんだけれども、そうなってくると、１つの単位、マンションでも、それは管理組合の中で話ができる。それはどんどんやってほしい。だけどそこにお金が出るということが１つ問題だろう。だから、それが杉並区でも２人でもいいよとやっているわけね。私は民間にそういうことを渡していく前段階の、それが１つの準備行為だと思いますので、それはぜひやっていただきたいなと思います。","respondent":"島袋品川区清掃事務所長","answer":"それはわかります。ただ小さいところはそうでもないところも結構あるんです。そういうことを考えまして、こういう報奨金のあり方についてどういうのが適当なのか、審議会等がありますので、そういうところにお諮りしながら考えていきたいと考えているところです。","voiceIndex":332,"id":"exchange-143"},{"speaker":"石田（秀）委員","kind":"質問","question":"私も審議会委員だから、審議会でも意見を言わせてもらいます。４ｋｍ四方を全部緑にしたって、この品川というところで、この狭いところで、どうせこういう緑化をしていくんなら、もっと意識啓発、区民の意識を高めていこうよ。それであるならば、必然的に品川区は人口が３４万人ぐらいいるわけじゃないですか。この人口の人で、ごみ１つ減らしましょう、これのほうがよっぽど減るわけですよ。","respondent":"藤田道路公園課長","answer":"そのときにも温室効果ガスを吸収し、地表を冷却するなどの環境保全機能を持つ緑の保全育成に努めるということで、品川区単独の話だけでなく、２３区も合同しながら、こういった取り組みをやっていきたいんだという気持ちのあらわれだと考えております。","voiceIndex":334,"id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"私は成果報告書１２９ページ、環境衛生費と、１３８ページ、中小企業対策費についてお聞きしたいと思います。環境のほうですが、現在、日本の気候は温暖化に向けて本当に暑い、また今年は大変暑かったときを迎えました。区道等の雨水枡や小・中学校の校庭の雨水枡、そして稲を栽培している小学校のバケツ等に銅金属などを入れて、害虫予防対策をとれないかどうか、ご見解をお聞かせください。","respondent":"山岡品川区保健所衛生課長","answer":"私のほうから、今、ご質問のあった銅の利用というんでしょうか、それが蚊の発生抑制に効果があるのかどうかということについてお答えいたします。財団法人日本環境衛生センターというところがございまして、ここで銅イオンを使った実験を行っております。","voiceIndex":337,"id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"ぜひ検証していただきまして、品川区ももし取り入れられたら取り入れてほしいと思います。続きまして中小企業対策費として、今、産業振興課として産業振興に取り組んでいるわけですが、毎年商店街振興事業ならびに活性化推進事業など、さまざまな商店街振興策を実施しておりますが、その費用対効果は実際どうなんでしょうか。産業振興課としてその実態を把握しているのかどうか、お聞きしたいと思います。","respondent":"金子産業振興課長","answer":"そういう意味では、私どもとしましては、意欲のある商店街にさまざまな支援をすることによりまして、一定の商店街の例えば再生であるとか、例えばにぎわいの創出であるとか、そういった形で支援することによって。","voiceIndex":339,"id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"やはりこれだけの予算を、東京都のほうもそうですが、毎年投入されております。品川区は本当にさまざまな事業を商店街振興また推進のためにやっております。実際その結果はどうなったんだろう。その中で特にお聞きしたいんですが、産業振興課で見ていて、産業振興策をどういうふうにすれば、産業振興策としては何が一番根本なのか、その辺の見解をお聞かせください。","respondent":"金子産業振興課長","answer":"ただ次に来るところ、さらにその次に来るところの規模のものというのは、私どもが支援をすることによってさまざまなイベント、あるいは歩きやすい環境づくりをするとか、そういったことによって集客力が上がってくるだろうと考えておりますので。","voiceIndex":341,"id":"exchange-147"},{"speaker":"須貝委員","kind":"意見","question":"今、課長から答弁がありましたが、まさに人がいないとだめなんですね。だから、本当に商店街の近くに多くの人に居住してもらうとか、そういう政策も区として考えていかなければ、購買意欲がなければだめだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":343,"id":"exchange-148"},{"speaker":"阿部委員","kind":"質問","question":"私からは１２７ページ、小児夜間診療と、同じく１２７ページの不妊治療相談・助成事業、そして１３９ページ、ものづくり産学連携についてお伺いします。もしも時間がありましたら、１３０ページの妊婦健診についてもお伺いしたいと考えています。その背景に小児科の医師不足があるとも聞いたんですけれども、ちょっとその背景を教えていただけますでしょうか。","respondent":"太田健康課長","answer":"もともとこの事業については、荏原医師会のほうで単独事業ということで、昭和大学病院との連携のもとで、昭和大学病院の研修医に固定診療所へ来ていただいて、荏原医師会が実施をするということが１つございました。","voiceIndex":345,"id":"exchange-149"},{"speaker":"阿部委員","kind":"質問","question":"先日、小児科の先生に伺ったところでは、そういったことを以前病院などで指導したところ、夜間に訪れる受診者の数が２割ぐらい減ったというお話を伺いました。そういった機会などを活用して、夜間の病院あるいは子どもの全身状態の見方、そういったことを指導する機会というのを積極的に持たれる、あるいは指導を強化されてはいかがと思うのですが、いかがでしょうか。","respondent":"川口品川区保健センター保健サービス課長","answer":"今年度から委員お話しのように、すくすく赤ちゃん訪問事業ということで、児童保健事業部全体として立ち上げてあります。今、委員のおっしゃったそういうことを踏まえて、これからさらに訪問指導を高めていき、それにさらに加えて夜間診療も検討してまいりたいと考えております。","voiceIndex":347,"id":"exchange-150"},{"speaker":"阿部委員","kind":"質問","question":"ぜひご検討をよろしくお願いいたします。次に不妊治療相談なんですけれども、こちらは平成１８年度から始めた事業ということで、相談件数１９件となっております。今、不妊に悩む方が非常に多い中で、私もその１人で大変にナーバスな日々を過ごした経験があるんですけれども、その中で１９件というのはあまり多い数字ではないなと考えています。この数字をどう評価されているか、お伺いいたします。","respondent":"倉橋品川区保健所保健サービス課長","answer":"確かに１９件というのはそう多い数字ではございません。しかしこの実施体制というものが１人３０分から４５分くらいの枠をとりまして、かなり専門性の高い先生をお呼びしまして、じっくりと相談に乗っていただくという相談を企画実施しています。","voiceIndex":349,"id":"exchange-151"},{"speaker":"阿部委員","kind":"意見","question":"量より質を重視したということだと思います。相談は確かに質を重視する、じっくりするということは大切なので、質が低い相談はかえってマイナスであると思いますので、質を重視するという姿勢はいいかと思います。同様にこの不妊相談などについても、医療機関との連携などで場を増やす、あるいは回数を増やしていけるようなことができないかご検討いただければと思います。ご答弁をお願いいたします。","respondent":"倉橋品川区保健所保健サービス課長","answer":"この回数増につきましては、現在ほぼ１日３から５枠の対応でやっておりまして、ほぼちょうどニーズに見合う形となっております。実施しますと、今後のニーズが増えてくる場合もあると考えております。","voiceIndex":351,"id":"exchange-152"},{"speaker":"阿部委員","kind":"意見","question":"最後に１３９ページ、ものづくり産学連携推進事業、この内容についてはちょっとはしょらせていただきます。本日もさまざまな事業の中で、区と大学が連携する、あるいは大学の研究室と連携するといった事業がたくさん出てまいりました。さまざまな視点で連携については考えていかなければいけないと考えています。現段階での大学と連携することのメリットと課題について、手身近にお願いいたします。","respondent":"金子産業振興課長","answer":"そういう意味では、まずは地元、近隣のところとの連携というのが、各学校におきましても、所在する地域との連携というのをまず掲げておりますので、そこで生かせるものがあれば生かしていこう、また区外にあるところのさまざまな技術を使える場合には。","voiceIndex":353,"id":"exchange-153"},{"speaker":"阿部委員","kind":"質問","question":"課題のところまでは伺えなかったと思いますので、また次の機会にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":355,"id":"exchange-154"},{"speaker":"南委員","kind":"確認","question":"２つ質問したいと思います。とりわけ非常に問題意識を持ってきたのが８月の終わりだったでしょうか、奈良県で女性の方が長時間受け入れ先がなくて、とうとう子どもを死産させてしまったという悲しい事件があり、そしてそれだけではなく、改めてこの問題を調べてみると、ちょうど去年の１１月ごろ東京２３区の荒川区でもあったという状況でした。","respondent":"太田健康課長","answer":"ご質問ですけれども、出産ができる医療施設は区内で３つです。昭和大学病院とＮＴＴ東日本関東病院、それから東芝病院です。それぞれの職員体制というのは、申しわけございませんが、私どもでは把握してございません。","voiceIndex":357,"id":"exchange-155"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、極めて東京都や国の医師の教育だとか、医師の勤務体制の充実だとか、そういう問題があるので、品川区でやれる範囲というのは限られてくるというのは承知の上なんですけれども、しかし大病院とまちの中で開業しておられる医者との連携をしっかりとっていくということと、そういうことが非常に求められると思うんですけれども、現状のいわゆる出産難民と言われるこういう状況の中で。","respondent":"倉橋品川区保健所保健サービス課長","answer":"これにつきましては、おっしゃるとおり、品川区レベルではなかなか十分なことができません。ある程度二次医療圏などのような形で対応していくということが必要になるかと思います。","voiceIndex":359,"id":"exchange-156"},{"speaker":"南委員","kind":"質問・要望","question":"２つ目の質問ですけれども、廃棄物対策費ということで、品川区の焼却施設として品川清掃工場がありますけれども、新しくリニューアルされて１年半ぐらいたつんでしょうか。焼却炉が２基と灰溶融炉が２基あるわけですが、この焼却炉２基のほうは日常的に稼働しているということなんでしょうか。","respondent":"秋山資源循環推進課長","answer":"委員おっしゃいますとおり、品川清掃工場なんですけれども、現状は３００ｔの焼却炉が１基ずつ２炉体制ということでございまして、そこの運転状況につきましては、定期的な保守とか、そういうのでとまっているというところは。","voiceIndex":361,"id":"exchange-157"},{"speaker":"南委員","kind":"質問・要望","question":"たまたま今日の朝、この焼却炉の事故が発生したことについて説明を私たちは受けましたけれども、どんな事故だったのかという説明がなかったと思いますので、そのあたりを改めて伺いたいと思いますし、原因はどうなのか、その究明体制はどうなっているのか、そこも含めて教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":363,"id":"exchange-158"},{"speaker":"南委員","kind":"質問","question":"朝の説明ではわからないところがあったので質問したいんですけれども、だめなんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":365,"id":"exchange-159"},{"speaker":"南委員","kind":"質問・要望","question":"私はぜひ全議員のいる場面で、こういう問題はすべての情報をきちんと知らせるということが大事だと思いますので、そういう点で不十分だったところを教えてくださいと。わからなければわからないでいいと思うんです。今わかった段階で教えてくださいということですから、ぜひ取り上げていただきたいと考えています。ぜひそういうことでもう一度委員長のほうの判断をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":367,"id":"exchange-160"},{"speaker":"南委員","kind":"質問・要望","question":"隠しているんじゃないかという思惑で聞いたわけじゃありませんから、それは誤解しないでいただきたいと思います。そういうことはできるだけ避けなければいけないという点で質問したわけです。それに対して質問させていただけないのは非常に不満です。そこのことだけはちょっと申し上げたいと思います。ぜひ理事会を開いていただいて、大事なことですから、この問題を検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":371,"id":"exchange-161"},{"speaker":"南委員","kind":"質問・要望","question":"私も質問をさせていただきたいと思いますし、少なからずほかの方々も聞きたいと思うことはあると思います。したがって、そういう場面をつくっていただきたい。委員長のご判断でぜひそういうふうにしていただきたいと考えていますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":374,"id":"exchange-162"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１回しっかりこういうことは、ルールがあるわけですから、もしあれだったら理事会を開いていただいて、あそこまで何度も言われるのであればどうぞ理事会で、副委員長も出ているわけですから、ぜひやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":376,"id":"exchange-163"}]},{"id":"topic-02","title":"ただいま石田秀男委員より議事進行につきまして動議が出されました。 ただいまの動議","agenda":"ただいま石田秀男委員より議事進行につきまして動議が出されました。 ただいまの動議","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"排ガスについて、きょうの朝の説明では、立方メートル当たり１１０μｇ水銀が出ているというお話でした。したがって、１１０μｇということは２.２倍なんです。今、清掃一部事務組合で追加調査ということがありましたので、それはそれとして伺っておきますけれども、わかった時点で緊急に区民委員会なり所管の委員会を開いて、対応をしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":382,"id":"exchange-164"},{"speaker":"堺委員","kind":"質問・要望","question":"最初の保健衛生に関連してですが、アタマジラミについてお伺いをしておきたいと思うんですが、これは子どもに発生しやすいと言われているようですが、このアタマジラミの発症状況というんでしょうかね、相談件数というんでしょうか、この辺について、把握されている範囲でお知らせいただければと思うんですが。","respondent":"山岡品川区保健所衛生課長","answer":"シラミの相談件数ですけれども、年によって若干上下するところとなりますけれども、平成１８年度につきましては５件の相談をいただいているところです。","voiceIndex":384,"id":"exchange-165"},{"speaker":"堺委員","kind":"質問","question":"品川区では５件ということで、平成１８年度は５件ですが、平成１７年度あるいは今年はどうですか。把握されていれば。","respondent":"山岡品川区保健所衛生課長","answer":"平成１８年度は５件、その前年の平成１７年度はちょっと多くて２６件のご相談、その前の平成１６年度が１２件です。今年はまだカウントしておりませんけれども、昨年並みといいますか、数えるほどということで現在のところは推移しております。","voiceIndex":386,"id":"exchange-166"},{"speaker":"堺委員","kind":"質問","question":"先ほど私はご連絡いただいたときに、教育委員会のほうにもご連絡をとらせていただきましたというお話をさせていただきましたが、これもある小学校のお子さんが頭にシラミがでて、駆除等についてはシャンプーですか、このシャンプーも高いそうですが、買ってこられたようですが、その学校では印刷物をつくって、学校で今、こういうのがはやったから。","respondent":"山岡品川区保健所衛生課長、古里学務課長","answer":"学校とか保育園とか、お子さんが集団生活をしているところで１人の方に発生すると、その子から感染するということはあろうかと思いますけれども、今のところ、私のほうには特別の情報は入っておりません。今年度につきましては、委員おっしゃったところ、もう１つということで、それ以外には今のところ私どもが掌握している件数はございません。","voiceIndex":388,"id":"exchange-167"},{"speaker":"堺委員","kind":"質問・要望","question":"中小企業センターの運営費に関連してですが、これは平成１７年度に耐震診断を行って、それに基づいて平成１８年度は大規模改修の設計委託、そして平成１９年度におきましては、この大規模改修費として３億６,０００万円計上して、今の中小企業センターは工事中という状況ですが、この中で使い勝手のいい形に整備していただきたいというお話をさせていただいた中で。","respondent":"金子産業振興課長","answer":"ですけれども、何らかの工夫をして、利用者の方に快適に過ごしていただけるような方向で検討しておりました。最終的な形はまだ今のところ決まっておりませんけれども、今よりも改善した形で使っていただけるようにということで、鋭意検討しています。","voiceIndex":391,"id":"exchange-168"},{"speaker":"堺委員","kind":"質問・要望","question":"もう一回、その件について後でお答えいただきたいと思いますが、あわせて商店街の関係ですが、これも１０月３日付の新聞で、シャッター通り活性化へということで、１０月２６日に全国商店街サミットということで、品川区が「商人の商人による商人のためのサミット」ということで、大崎のほうで、全国から５００人ぐらいの参加を見込んでやるですが。","respondent":"金子産業振興課長","answer":"私どもは東京商工会議所品川支部その他とともに、後援という立場で積極的に協力をしていくというふうに考えております。先ほどの中小企業センターのエアコンですけれども、これについてはきちっと対応していきたいと考えています。","voiceIndex":393,"id":"exchange-169"},{"speaker":"林委員","kind":"質問・要望","question":"１３８ページの産業振興というか、商店街振興で、確認だけしておきたいんですけれども、１６３号線の道路の拡幅で、非常に大きな打撃を受けた一本橋の商店街は現在どういうふうになっていて、それから、入り口のところの再開発が組合が設立されて進んでくるわけですけれども、現在の状況と、これから年次的にどのくらいのスパンで商店街が復活してくるのか、その辺のことを説明してください。","respondent":"倉橋品川区保健所保健サービス課長、田村環境課長、青木都市開発課長、秋山資源循環推進課長","answer":"不妊相談についですが、男性も対象としております。実際、平成１８年度は１名男性の実績があります。今年ちょうど２回目の更新にあたって、認証機関からも指摘はなく、褒められることがあったので、着実に安定稼働していると考えております。この建物が完成しますのは平成２２年７月を予定しておりまして、１・２階部分は商業施設を入れる予定で、現在、入居者の調整を図っているところです。区施設資源回収事業ですけれども、こちらの庁舎も含めまして、出先も含めて１２５カ所、１６１施設を回収しているものです。","voiceIndex":396,"id":"exchange-170"},{"speaker":"林委員","kind":"質問・要望","question":"聞いたことは、なぜ今年は５割増しの予算がついているのかというのを後で答えてください。その辺について区側としては現在どうなっていて、今言われた平成２２年に開発ビルが完成するということならば、それに合わせて商店街だってイベントを打つとか、活性化の何かを仕掛けていきたいという考えを持っていらっしゃると思うので、その辺について聞かせていただきたい。資源回収のほうだけ答えてください。","respondent":"浜脇街路事業担当課長、金子産業振興課長、秋山資源循環推進課長","answer":"その中に組合の事務所もありますので、その辺も含めて今後の商店街のあり方といいますか、事務所の引っ越し先なんかもあるようですので。そういう意味では、道路の進捗状況に合わせまして、商店街の方々と相談して、私どもとしましては、できる範囲の支援をしていきたいと考えています。資源回収の５割増しですけれども、生ごみ回収の費用が今年度予算で増加しているです。","voiceIndex":401,"id":"exchange-171"},{"speaker":"林委員","kind":"質問・要望","question":"商店街のほうは、一たんほかの場所に行って、道路ができ上がったら戻ってくるという方もいらっしゃるだろうし、形としてさまざま地元の方はご苦労されているわけで、商店街を１本何とかしますというんじゃなくて、きめ細かに、個の商店街の人たちを支援してあげていただきたいなと。今、壊滅的なのは道路を広げたからで、道路を広げるのはやむを得ないということですから、その辺を斟酌してあげてください。","respondent":"日下部企画財政課長","answer":"これが増加します理由は学校の関係なんです。今まではコンポストで処理をしておりましたけれども、コンポストの関係はいろいろ事情がありまして、これを委託に切りかえる。その経費でこの分跳ね上がったという経過です。","voiceIndex":405,"id":"exchange-172"},{"speaker":"林委員","kind":"質問","question":"区の施策に逆行じゃないですか。ごみを減らして循環型社会をつくるというのが品川区の掲げている目標じゃないんですか。１,２００万円もかかるごみが増える。それはコンポストを失敗したからやっていくんだという理由でしょうけれども、区として、ごみを減らして循環型というのはやめたんですか。","respondent":"日下部企画財政課長、岩崎環境清掃事業部長","answer":"ただ学校につきましては、機械上の処理の問題とか、いろいろ課題があったということで、今回は切りかえざるを得なかったということでありますので、その辺、これからどういう形で今後とも進めていくのか。ちょっと言葉足らずでございまして、生ごみ処理機という学校ごとに置いていたものはそのままリサイクルということになるわけですけれども、そのリサイクルのやり方を、生ごみを集めてメタンを発酵させて発電するとか。","voiceIndex":407,"id":"exchange-173"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1282#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":112792,"voices":411}},{"id":"h19-20071009-4","meetingId":"h19-c-settlement","date":"2007年10月9日","dateIso":"2007-10-09","committee":"決算特別委員会","time":"午前１０時０２分～午後５時３６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を158件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時０２分開会 おはようございます。 ただいまより、決算特別委員会を開会いたします。 それでは、平成１８年度品川区一般会計歳入歳出決算","agenda":"○午前１０時０２分開会 おはようございます。 ただいまより、決算特別委員会を開会いたします。 それでは、平成１８年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"私は、１４７ページの防災生活圏促進事業について、国文学研究資料館について、改めていろいろとご意見をいただければなと考えています。平成１８年度の取得へ向けた動き、そして、平成１９年度に入りましたけれども、平成１９年度までの国への働きかけというものを再度教えていただきたいなと思います。","respondent":"堀越行財政改革担当課長、伊勢住環境整備担当課長","answer":"国文学研究資料館の取得の交渉の状況ですが、こちらが、今、国から、大学共同利用研究機関法人、人間文化研究機構というところに資産が、帰属が移っておりまして、そちらのほうと、今、交渉を進めている段階です。今、防災生活圏促進事業ということと、それから国文学資料館の関係ですが、取得した後に、戸越・豊町地区の防災生活圏につきましては、国文学資料館の入り口等の整備を予定しています。","voiceIndex":4,"id":"exchange-001"},{"speaker":"山内委員","kind":"質問・要望","question":"整備に向けた予算の計上をされるということは、これは、設計の二重投資は避けるという説明もございましたけれども、こちらの免震工事の終了時期にもよるかと思うんですけれども、これが平成２４年とか平成２５年とかと言われていますけれども、将来的な跡地の設計の青写真がもうそろそろ、第２回定例会とか、その辺で提出されるのかなという推測をしておりますけれども、これと絡んでくると思うんですが。","respondent":"日下部企画財政課長","answer":"残りの分については、財調算定の対象になる。財源的にはそのようなことで一定の見込みを立てているです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"山内委員","kind":"質問","question":"先ほど課長の答弁の中で、入り口の整備をされるというのは、これはどういうことなのか、もっと具体的に教えていただけますか。","respondent":"伊勢住環境整備担当課長","answer":"戸越・豊町区の防災生活圏ですが、戸越公園あるいは国文学資料館を含む５０haの事業でございまして、そのうちで、戸越公園の入り口整備だとか、あるいは今年やりました橋の整備、こういうものも含めて、国文学資料館につきましては。","voiceIndex":9,"id":"exchange-003"},{"speaker":"山内委員","kind":"質問","question":"といいますと、今現状の入り口がありますよね。それは使わないということになるんでしょうか。それとも、新たに、速やかな避難ができるような形での入り口をつけ加えるということなんでしょうか。","respondent":"松代管理工事課長","answer":"国文学資料館の将来の公園に向けての整備計画ですけれども、当面は、整備方針というものを定めまして、将来的には、先ほどの庁舎の免震工事に伴っての暫定利用が終わった後、本格的な整備になろうかと思います。","voiceIndex":11,"id":"exchange-004"},{"speaker":"山内委員","kind":"質問","question":"今、地域の方といろいろなリサーチをしながらということだったんですが、ちょっと中の部分に入るんですけど、建物について、この前一般質問の答弁の中でも、中にある三井文庫跡は残すという答弁がございました。それ以外の建物に対しては、結構年月も経っていますよね。まだその辺については、決定というか、見通しはついてないのでしょうか。","respondent":"松代管理工事課長","answer":"建物につきましては、当面暫定的な利用ということで、使えるかどうか、今、検討されていると聞いております。将来の公園整備に当たっては、ここは都市計画公園としての整備をします。当然ながら、防災上の避難の拠点となってまいります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"山内委員","kind":"質問","question":"それからあと、これは契約のことになってしまうかなと思うんですけれども、そのような形で速やかに、何か災害が起きたときに避難できるような公園整備、いわゆる防災を兼ねた公園を整備するということに当たって、いよいよ設計という段階に入ってくるのかなと思うんですけれども、設計の仕方なんですが、これはプロポーザル方式をとられるのでしょうか。","respondent":"松代管理工事課長","answer":"その際には、設計等については、改めて設計をしまして、工事という形になろうと思いますが、設計段階では、プロポーザル等々を含めて、少し検討の余地があるのかな、このように考えているところです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"山内委員","kind":"質問","question":"今の段階では、何らかの形での青写真というものがあるわけですよね。で、平成２３年、多分こちらの庁舎の免震工事によるかと思うんですが、何年かある中での、例えば新たな設計をし直すとか、そのようなことが考えられるということなんでしょうか。","respondent":"松代管理工事課長","answer":"設計には、少し段階がありまして、今現在進めておりますのは、整備方針、基本的なことの整備をどうするかということで考えています。次に、基本計画、実施設計という形に進んでまいります。","voiceIndex":17,"id":"exchange-007"},{"speaker":"山内委員","kind":"質問","question":"たしか、一部開放するという話がございましたよね。それとの兼ね合いというのはどうなるんでしょうか。","respondent":"松代管理工事課長","answer":"暫定開放です。基本的には、今の１.４haぐらいの面積の中で、耐震化に向けての駐車場の利用とか、あとは、建物の利用とかというのが、粗々、今、検討されています。残った部分、南側の部分ですけれども、池を中心として、あります。","voiceIndex":19,"id":"exchange-008"},{"speaker":"山内委員","kind":"意見","question":"ちょっと突っ込んで申しわけないんですけど、総務費の中でも、答弁の中で、二重投資はしないという話でしたよね。だけど、今の答えだと、二重投資しますよと言っているようなものだと思うんですよ。その辺について、どう思いますか。","respondent":"松代管理工事課長","answer":"そういった可能性が十分にありますので、そういったことから、最小限の整備をしまして、中に人が入っていける。少し道路のわきを広げる。そういった形で、部分的な暫定開放ができないものかというところで、今、進めているものです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"山内委員","kind":"質問","question":"その暫定の設計に対しての補助金というものは、つかないんですか。","respondent":"松代管理工事課長","answer":"そういったものは、つく予定はございません。","voiceIndex":23,"id":"exchange-010"},{"speaker":"山内委員","kind":"意見","question":"最終的な話になってしまうんですけれども、実施設計の段階で、例えばこれは、いろんな考えなんですけれども、例えば隣にある戸越体育館、さらには戸越小学校、そして戸越公園があります。この辺との連帯というか、一体化をした、いわゆるその地区の本当の意味での防災の公園ならびに避難場所、そういうものというお考えはあるのか、お聞かせください。","respondent":"堀越行財政改革担当課長","answer":"これが基本です。その際、いろいろな地域のご意見を伺いながら、それから、周辺の施設ですとか、そういった防災まちづくりの観点ですとか、そういったところについても、大きな構想として、そういうような部分も、構想としての検討も含めて行っていきたいと、今、考えてあります。","voiceIndex":25,"id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"最初に、道路、公園、河川などの監察事務費ですけれども、その項目として、商品の突出取締ほかとありますけれども、この部署というんでしょうか、この項目はどのような業務を実施されているのかというのが１点。そして、そのような違反に対して改善を強制できるのか。それとも指導だけなのか。そこら辺の件についてお伺いいたします。","respondent":"松嶋交通安全担当課長","answer":"だからといいまして、これを放置することは、公益性を守る上からも問題でありますから、引き続き、商店会あるいは警察との合同パトロールによりまして、指導、警告を持続していきながらも、常識を逸脱するようなもの、そういったものについては。","voiceIndex":28,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"道路が狭くなってしまう。続きまして、公園・児童遊園の維持管理費ですけれども、こちらのほう、品川区民公園維持管理費、これを除いた場合ですけれども、平成１７年度に比べて２億円弱増加しておりますけれども、こちらの主な増加要因は何だったのか、教えてください。","respondent":"藤田道路公園課長","answer":"公園の維持の関係ですけれども、平成１７年度と平成１８年度の違いといったことですけれども、平成１７年度までは、私ども、土木事務所を持っておりまして、そちらの中で、維持管理についても積極的に進めてまいりました。","voiceIndex":30,"id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"委託に変更したということですけれども、とかく委託をすると、費用、見えなくなる部分があるかと思いますけれども、内容のほうもしっかりやっていることだと思いますが、リーズナブルな増額だったのかということを再度お伺いしたいと思います。そして、修繕費も約８,０００万円ほどかかっているんですけれども、主な内容についてお伺いいたします。","respondent":"藤田道路公園課長","answer":"リーズナブルな形での増だったのかですけれども、当然費用の面については、私ども、考えながら、事業実施しているわけですけれども、費用の面だけでなく、サービス面としても、さらに区民の皆様に喜んでいただけるような維持管理を進めるということで、実施をしたところです。","voiceIndex":32,"id":"exchange-014"},{"speaker":"浅野委員","kind":"質問","question":"修繕費、８,０００万円ほどかかっていますけれども、その主な内容についてお伺いします。","respondent":"藤田道路公園課長","answer":"私どもの公園、ご案内のとおり、遊具がある、トイレがある、あるいは公園等々の電気の設備があるということで、それらの維持、改修、補修、あるいはペンキ塗りといったことで、業種にすると、造園や土木、あるいは建築、塗装、上下水道。","voiceIndex":34,"id":"exchange-015"},{"speaker":"浅野委員","kind":"質問","question":"ちょっと話は変わるんですけれども、今年の春ごろですけれども、木製のポールの間を渡した遊具があって、ロープにぶらさがっていた子どもが、ポールが折れたことによって、木製なので、根もとが折れたらしいんですけれども、落下をして、けがをするという事故も起きております。これはどのような項目で、頻度というんでしょうか、どの程度の頻度で実施しているのか、お伺いいたします。","respondent":"藤田道路公園課長","answer":"遊具に限らず、公園施設の点検、これは私ども、日常、管理する中で欠かすことができない項目だと考えています。","voiceIndex":36,"id":"exchange-016"},{"speaker":"浅野委員","kind":"質問・要望","question":"やはり点検に関しまして、こういう専門的なところにつきましては、場所を指定して、このような点検をしてほしいと。そして、それに対して、きっちりと業者のほうから、やったという、これは大丈夫だという、そのような証拠をぜひともしっかりととっておいていただきたいと思います。これは要望です。そのような点検確認をされたのかどうか、お伺いします。","respondent":"藤田道路公園課長","answer":"先ほどの韓国製の関係ですけれども、これは、国のほうでも結構重要に受けとめておりまして、国土交通省のほうから、一斉点検をせよというような指示も出ているものです。区内については、こうした遊具については、なかったということで、確認をしています。","voiceIndex":38,"id":"exchange-017"},{"speaker":"浅野委員","kind":"質問","question":"３点目になりますが、密集住宅市街地の整備関係ですけれども、歳入のところでもちょっと質問させていただいたこともありますけれども、旗の台・中延地区については、平成元年に整備計画が承認されて、事業を進めてきておりますけれども、２回ほど延伸をされて、現在、平成２１年度まで実施をすることになっておりますが、このように、長い期間、延伸を重ねて続けている。","respondent":"伊勢住環境整備担当課長","answer":"密集事業ですけれども、一般的に事業のメニューといたしましては、道路の整備、それから、公園・広場の整備、それと建て替え促進というような、３つの大きな分野があるんですが、ここの地区に関しましては、道路の関係ですと、道路拡幅じゃなくて。","voiceIndex":40,"id":"exchange-018"},{"speaker":"浅野委員","kind":"意見","question":"なかなか住民の方に賛同していただけないということだと思うんですけれども、助成制度につきましては、平成１８年度、１,８７０万円の予算がありますけど、実績がなく、また平成１７年度も実績がないということ。これは進んでないということを意味しているかと思うんですけれども、その点の回答をお願いします。","respondent":"伊勢住環境整備担当課長","answer":"引き続き、建て替えの促進につきましては、働きかけるとともに、あと、荏原町等でも、共同化の動き、最近出てきていると思いますので、その辺で……。","voiceIndex":42,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、成果報告書の１４９ページの区営住宅管理費について伺いたいと思います。初めに、区営住宅について、その目的は何か、ご説明いただきたいと思います。あわせて、地方公共団体が担う公営住宅の役割とは何なのか、あわせてご説明いただきたいと思います。","respondent":"齋藤住宅課長","answer":"公営住宅についてのご質問です。公営住宅は、昭和２２年から、法律に基づきましてできました。最初は、低所得者層の方に対する住宅でございまして、その当時、８２％ぐらいの方が公営住宅に入れる。このような数字でございました。","voiceIndex":45,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区は、今後の見通し、どんなふうに考えているのか、教えていただきたいと思います。それと、私に寄せられる生活相談の多くが、区営住宅に入りたい、都営住宅に入りたい、そういったものです。その理由をよく聞くと、ほとんどが経済的な理由、生活困窮が主な理由です。そういったケースも増えていると思うんですけれども、こうした実態が広がっていることを実感されているのかどうか、伺いたいと思います。","respondent":"齋藤住宅課長","answer":"生活保護を受給されている方は、品川区の場合は、１００世帯に１.６世帯、こういう割合ですので、大きな目で見ますと、十分、住戸としては足りているのではないか、このように考えております。","voiceIndex":47,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"今の実感というのは、区民の実態、実感とあまりにもかけ離れていると思います。景気が上向いていると言いますが、例えば１つの指標で、サラリーマンの平均給与、これは９年連続右肩下がり。国民の貯蓄、貯金、それも今や４世帯に１世帯に迫る勢いで、貯蓄ゼロという世帯が増えている。そういうところをしっかりとまずは目を向けるべきではないかと思います。そう思いますけれども、いかがでしょうか。","respondent":"齋藤住宅課長","answer":"江戸川区や足立区、名前を出すとちょっとあれですけれども、１年間、一生懸命頑張れば、当選します。そこから品川区まで１時間半ほどはかかりますけれども、住宅を確保すること、それは必ずしも難しい時代ではなくなってきたんだです。","voiceIndex":49,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"品川に住み続けたい。先ほどから、区内にはたくさん、４,０５０戸ですか、あるんだと言いますけれども、私は、今、幾つあるのかという議論よりも、区民の実態に照らして、足りているのか、いないのか。この視点をなぜ持たないのか、そこを伺いたい。そう思いますけれども、そういう視点は全くないのかどうか、伺いたい。それと、先ほど、４,０５０とありましたけれども、詳しく内訳も教えてください。","respondent":"齋藤住宅課長","answer":"こういうことです。これをもっと分解してみますと、荏原のほうには公営住宅が２００戸ぐらいしかありませんので、つくろうか、こういう話を考えますけれども、荏原のほうで２,０００m2ぐらいの土地が出るかと申しますと、なかなか出ません。","voiceIndex":51,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"都営、区営住宅、合わせて４,０５１戸。今日は再開発のことはやりませんが、５,０００万円、７,０００万円もするようなものをじゃんじゃんつくる。以前、建設委員会で数を聞いたら、今で１,０８０戸、今後を含めると３,０００戸、合わせて４,０００戸。１つ、他の区に比べて遜色ないと言いますけれども、２３区の中で、品川区の公営住宅、一体何番目ぐらいになるのか、具体的に教えていただけますか。","respondent":"齋藤住宅課長","answer":"すいません。何番目と言われますと、ちょっと苦しいんですけれども、例えば足立区、江東区、これらは１０％を超えておりまして、１０世帯に１世帯の方が公営住宅にお住まいです。割合で見ますと、平均が４.２９％になっておりますので、品川区は、真ん中より下ぐらいの数です。","voiceIndex":53,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"城南ブロックを見ても遜色ないと言いますけれども、城南ブロックが２３区の中で下のほうだというのが、私は実態だと思いますけれども、大体他の区に比べてというか、区民の願いに照らして、実態に照らしてどうなのかと。それでも足りないと思う。他の区に比べてもおくれていると思いますけれども、いかがでしょうか。","respondent":"齋藤住宅課長","answer":"１６番目ですが、地価が日本で４番目に高い。こういうことから考えますと、戸数、頑張っているんじゃないかなという実感を持っております。","voiceIndex":55,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"あまりにも都合のいい計算だと思います。家賃の安い住宅が足りない。それは応募倍率からも明らかだと思っています。平成１８年度で、例えば全部を紹介してもらうと時間もあれでしょうけれども、２００倍を超えたもの、３００倍を超えたもの、それがどういう状況にあるのか。こうした事態が生まれている理由、背景、それをどう考えているのか、教えてください。","respondent":"齋藤住宅課長","answer":"募集倍率ということで説明いたします。平成１８年度を見ますと、都営住宅、５月分で、東京都全体で５７.４倍でした。品川区の倍率は、１１４.５倍です。例えば東品川ですと、３６１倍がございまして、北品川第二であれば５８倍。東品川一丁目であれば１３０倍。","voiceIndex":57,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"例えば平成１８年度で見ますと、都営住宅、東五反田二丁目、募集１戸に対して、応募数は２４８人。だから、単純に２４８倍。東品川第二は、これも１戸に対して、３８６人の方が申し込んでいますから、３８６倍。北品川第二は、募集が２戸に対して５６２人ですから、２８１倍。ほかが５００倍の中で２００倍だから、まだいいんだと。区民の実態がどういうふうに置かれているのか、お考えを教えてください。","respondent":"齋藤住宅課長","answer":"２つあります。１つは、先ほど申し上げましたみたいに、大崎保育園の上にある都営住宅になりますと、近隣は２０万円ぐらい家賃をとりますので、そこに２万円前後で入れるというのは、大変魅力があるんだと思います。","voiceIndex":59,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"今話した説明の理由というのは、何か調査をした上で述べているんでしょうか。","respondent":"齋藤住宅課長","answer":"そのときの国の説明に書いてあったのが、私が答弁申し上げた、１００人いて、下から２５％の方が公営住宅に入居できる所得対象になっているのに、現状、世帯の収入が上がったのに、平成８年以降見直しをしていないので、上がってきてしまったと。","voiceIndex":61,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"どういう状態で申し込んだのか。ああ、２万円の家賃は安くていいなと、これで申し込んでいる実態は、私は限りなくないんじゃないかと思うんですけど、申し込みをする際に、きちんと意向調査というんですか、申し込みの理由、その背景、そういう住民の、申し込んだ方々のいわゆる理由ですね。それはしっかりとまずは把握されることを実施すべきではないかと思いますけれども、いかがでしょうか。","respondent":"齋藤住宅課長","answer":"こういう住宅もございまして、意向調査云々という問題ではございませんで、申し込みをする要件があれば、申し込みができる。それだけのことです。","voiceIndex":63,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"先ほど、都営住宅の倍率が２４８倍、３８６倍、こういう高い倍率が続くのは、ただ、周辺家賃よりも安いからではなくて、生活が苦しくなっている実態のあらわれだと思うんですね。そこについて、申し込みの際に、申し込みをする理由や背景、それはまずきちんと調査すべきではないかと思います。理由の調査といいますか、それについてはいかがでしょうか。","respondent":"齋藤住宅課長","answer":"答弁、繰り返しになりますが、公営住宅法は、要件がある方が入居できる、こういうものでございまして、意向調査をする考えはございません。","voiceIndex":65,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"これで最後にしますけれども、都営住宅、区営住宅、本当に申し込み倍率が高いです。さらに今、繰り返されている構造改革の中で、雇用の問題、社会保障の問題、そして増税負担増の問題、どれ一つとっても、今後明るい見通しが持てないというのが区民の実態です。ぜひ区営住宅、都営住宅もあわせて、長期基本計画の中で、よく議論していただき、建設に向けた具体化を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-031"},{"speaker":"稲川委員","kind":"質問","question":"成果報告書、１４０ページにあります駅周辺等放置自転車対策事業、そして、同じページにあります交通安全対策、１４８ページの木造住宅耐震化経費助成について、お伺いいたします。過去のデータを見ますと、平成１４年度、２万４,３６８台、撤去台数なんですか、今、平成１８年度、前年度が２万８,７７３台ということで、年々撤去台数が増えている状況の中、どういう状況なのかを教えてください。","respondent":"松嶋交通安全担当課長","answer":"これにつきましては、大きく出せば、クリーンキャンペーン、あるいは道の日、そういったものの日に、区民の方、あるいは関係機関と連携して、街頭活動による呼びかけ、あるいは、広報紙だとかホームページを利用した啓発、それと、放置自転車に対する警告札の貼付、あとは。","voiceIndex":69,"id":"exchange-032"},{"speaker":"稲川委員","kind":"意見","question":"品川区、私鉄の駅、ＪＲの駅がありますが、駅周辺にもちろん駐輪場はあります。例えば駅前の景観とか、あと、土地の有効利用を考えたときに、皆様もご存じだと思いますが、世田谷区などで取り入れている地下駐輪場があると思うんですが、地下駐輪場を今後、品川区として取り入れていく考えとか、取り入れなくても、検討をするとか、そういう思いがあるか、お聞かせください。","respondent":"松嶋交通安全担当課長","answer":"しかしながら、区内では、用地の問題、それと、それ以上に、設備コストに見合う費用対効果が望めるかというところでありまして、検討するといたしましても、より極めて慎重にすべき問題かと考えているところです。","voiceIndex":71,"id":"exchange-033"},{"speaker":"稲川委員","kind":"質問","question":"ぜひ景観、あと、防災の観点で考えても、駅前周辺、そして、きれいな品川区、安全な品川区をつくっていただければと思います。次に、交通安全対策費なんですが、ここにもまた啓発という言葉が出てきております。実際、啓発とはどういうことか、教えてください。","respondent":"松嶋交通安全担当課長","answer":"交通安全に対する啓発、これにつきましては、いろいろな種類を実施しています。例えばリーフレットの配布、あるいは交通安全教育、それと、参加型の交通安全教室だとか、自転車教室だとか、いろいろ種々雑多にわたって実施しています。","voiceIndex":73,"id":"exchange-034"},{"speaker":"稲川委員","kind":"質問・要望","question":"そういう中で、非常に自転車を取り締まるというのは、道交法上、厳しいという話を何回かお伺いをしたんですが、例えば地域の人から、ここの交差点は危ない、ここの坂道を下ってきたところは危ないという、さまざまな要望とか相談をいただくんですが、実際、品川区として、そういうところをどういう判断で、ここは危険な地域だ、ここはまだまだ大丈夫だというのを判断しているのか、お聞かせください。","respondent":"松嶋交通安全担当課長","answer":"そのたびに、現場のほうを確認させてもらって、必要な安全施設整備はとっているところです。それと、白線とか「止まれ」の表示の部分です。確かに薄くなる、見えづらいといったものは、事故防止上、問題があると思いますので、薄いところは、積極的に補正をしていっております。","voiceIndex":75,"id":"exchange-035"},{"speaker":"稲川委員","kind":"確認","question":"１４８ページにあります木造住宅耐震化経費助成費、これはちょっと確認というか、お伺いをしたいのですが、品川区のホームページ上も、木造住宅耐震診断支援ということで、ここに行き着くにも、結構いろいろクリックしていかなければいけないんですが、ここに診断費用が１２万円、その２分の１の６万円を助成支援をするということに、私も一般質問の中でお伺いをしたんですが、これは実際。","respondent":"片田建築課長","answer":"現在、区が行っているのは、一般診断まででございまして、さらに補強工事とか、そういうことになってくると、一般診断の結果を踏まえて、どこに補強材をどういう形で入れたらいいかということも検討していかなきゃいけない。","voiceIndex":77,"id":"exchange-036"},{"speaker":"稲川委員","kind":"質問","question":"実際、この２つを関連づけると、精密診断がどこにも出てこない中で、区民の方は非常に困っているというか、こんなお金がかかるものだったら、それこそいつ起きるかわからない地震に対してそんなお金をかけられないという話にもなっているんですが、もちろんホームページもわかりやすくするべきだと思うんですが、いかがでしょうか。","respondent":"片田建築課長","answer":"それと、精密診断のお話ですけれども、基本的には、精密診断まで必要かどうかというところは、かなり微妙でございまして、一般診断で、ほぼこれまで一応改修に至っているものについては、それを基本として補強設計に進んできているという話も一応聞いてありますので、基本的には。","voiceIndex":79,"id":"exchange-037"},{"speaker":"稲川委員","kind":"質問・要望","question":"一般診断書、もしくは精密診断書を添付して申請してくださいという形。１２万円を負担していただいて、そのまま７５万円の支援をしていただいて、自分が１００万円なり２００万円を足せば、耐震補強できるという考えでいるんですけど、そうでもないということが現状なので、今後とも積極的に、わかりやすい耐震補強、そして、促進事業を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-038"},{"speaker":"大沢委員","kind":"質問","question":"１４２ページ、東急目黒線に関連して、あと、都市計画道路、そして、１４６ページ、都市開発費で、大崎駅周辺ということで、質問します。最初に、ちょっと順番が逆なんですが、１４６ページの大崎駅周辺から伺わせていただきますけれども、副都心ということで、大崎駅周辺では、さまざまなまちづくりが行われております。","respondent":"青木都市開発課長","answer":"通常ですと、近隣に対策、計画説明をした後に、解体工事ということになるんですけれども、今回、まさに土壌対策も含めた解体工事から優先していく必要があるという事業者側のご判断で、１０月４日だったと思うんですけれども、近隣の方々に説明会を開催したということで。","voiceIndex":83,"id":"exchange-039"},{"speaker":"大沢委員","kind":"質問","question":"それと、ご答弁の中で、ネズミの駆除の中で、必要性の基準という文言がありましたが、必要性の基準というのは何かをお教え願えますでしょうか。ネズミの駆除の必要性の基準ということです。","respondent":"青木都市開発課長","answer":"基準と言ったのは、私の言葉の間違いだと思います。過去において、そういった苦情が寄せられた経験を踏まえて、殺鼠する必要があるということを認識した上で指導しているということでご理解ください。申しわけございません。","voiceIndex":85,"id":"exchange-040"},{"speaker":"大沢委員","kind":"質問・要望","question":"経験則上で認識された部分で、ネズミの駆除をするという。ネズミは移動します。街並み、すべてリニューアルといいますか、かつて３両編成の目蒲線が走っていたころに比べると、本当に街の顔が変わりつつありますが、その中で、これに付随してきた事業ではないと思います。これはあくまでも、両方とも、都が主体の事業ではありますけれども、区はどのようにかかわっていかれるのか、教えてください。","respondent":"阿部都市計画課長、松代管理工事課長","answer":"隅切りの部分につきましては、みずほ銀行のところですけれども、そこにつきましては、来年度用地買収をする予定というふうに聞いております。ここは広域的な避難場所となっていますので、林試の森公園と一体的な整備が一番望ましいということで考えてございまして、東京都と今後はその方向でいろいろと協議をしていきたい、このように考えているところです。","voiceIndex":87,"id":"exchange-041"},{"speaker":"大沢委員","kind":"質問","question":"２６号線のほうから伺います。来年度の買収ということですが、買収の範囲、今既に買収されている場所がありますけれども、おおむね計画には５００ｍということになりますが、来年の予定として、展望としては、地図がなくてこんなことをお話しするのは、漠然として申しわけないんですが、大体どれぐらいまで買収をされるご予定、またご意思というのがあるのか、教えてください。","respondent":"阿部都市計画課長","answer":"計画としては、平塚橋のところは１８０ｍというふうに聞いてあります。ただ、先ほども申し上げましたけど、左折レーンを開設するのが、まずは求められているということで、今のところ、平塚小学校の歩道橋がありますよね。あそこの部分まで、拡幅を急いでいると聞いてあります。","voiceIndex":90,"id":"exchange-042"},{"speaker":"大沢委員","kind":"質問・要望","question":"２６号線、民生住宅跡地、いずれにしましても買収される予定、そしてまた整備をされる予定ですけれども、民生住宅跡地、非常に貴重な場所です。ちなみに、駅周辺とあそこら辺、暑いとき、温度差が２度違いますので、林試の森に隣接している公園の一部、緑地帯としてその特性を生かした場所づくりをしていただきたいと思います。１００％のうち、今何％ぐらい検討されているのか。","respondent":"伊勢住環境整備担当課長","answer":"現在、物理的な道路やその他の公共施設の調査、それから、これから住民の方の意向の調査、こういうことが入ってあります。これは今年度につきましては、検討案の作成ということになっていまして……。","voiceIndex":92,"id":"exchange-043"},{"speaker":"金野委員","kind":"質問・要望","question":"私のほうからは、成果報告書１４５ページの公園管理費、そして、戻りまして、１４１ページの道路維持費からお伺いします。その工事というか、状況をお聞きしたい。それと、大井五丁目にあります滝王子公園、改修というお話も伺っているんですが、その後の進捗状況と、また、区民の皆さんの、地域住民の方の要望の遊具等々、ご要望を聞いてくださるのかどうか。３点の件に関して、お願いしたいと思います。","respondent":"藤田道路公園課長、松代管理工事課長","answer":"これにつきましては、今後、まずは撤去をせざるを得ないという形で考えてございまして、今、その準備を進めているところですので、もうしばらくこういう状態で、よろしくお願いいたします。滝王子公園の改修に当たっての計画と経過、そして考え方です。今、滝王子公園、全面改修をすべく、地元に説明会を開いてあります。説明会は、これまで２回ほど開いておりまして、年内にもう１回開く予定です。","voiceIndex":95,"id":"exchange-044"},{"speaker":"金野委員","kind":"質問・要望","question":"滝王子公園に関しては、アンケートをとってくださって、遊具をまた決めてくださるということですので、これは要望ですけれども、あそこは、ほとんど今あるのは、小学生高学年向きというんでしょうか、遊具は、大変高い遊具になっておりますので、できれば、もう少し低学年、または幼児が使うような遊具にしていただきたい、そのように思います。続きまして、１４１ページの道路維持費のほうにまいります。","respondent":"藤田道路公園課長","answer":"もしご指摘の場所、今、若干ございましたけれども、そういった箇所があれば、私ども、早急に点検をし、改善に努めていきたいと考えています。","voiceIndex":98,"id":"exchange-045"},{"speaker":"金野委員","kind":"質問・要望","question":"そういった意味からも、このまちづくりの１つとして、点字ブロックの総点検、また、新たに設置していただきたい場所等も要望をしたいと思います。新たに設置していただきたい場所でありますけれども、下神明の駅からこの庁舎に向かう間は、点字ブロック等は１つもないかと思います。いかがでしょうか。","respondent":"藤田道路公園課長","answer":"点字ブロック等の点検の関係ですけれども、私ども、当然日々の点検、パトロールを実施しております。","voiceIndex":100,"id":"exchange-046"},{"speaker":"金野委員","kind":"質問・要望","question":"それは、西大井広場公園とニコンの間の道路の交通安全ですけれども、安全対策として、これまでも公明党として、るる要望をしてまいりましたけれども、一部、ニコンが解体の際、その道路を少し提供するような声も伺っておるんですが、たとえそうであったとしても、区道でありますし、西大井広場公園という区の施設がありますので、区のほうも、何らかの対策を練り。","respondent":"松代管理工事課長","answer":"もしその辺のところ、手を入れるとなると、西大井広場公園のほうにかなりの影響部分があります。そういったことから、西大井広場公園の改修等、先々、その辺のことを検討しながら、そこの部分も改善したいと思っているところです。","voiceIndex":102,"id":"exchange-047"},{"speaker":"渡部委員","kind":"質問","question":"私のほうからは、成果報告書のほうの１４６ページ、東京臨海高速鉄道出資金について、それと、１４１ページの交通安全施設整備事業、１４０ページ、放置自転車対策等について質問します。それと、当然株式会社ですので、持ち株比率、また、この会社に対して、区として役員等を出向なりの形で送り込んでいるのかどうか、ひとつ教えてください。","respondent":"阿部都市計画課長","answer":"臨海高速鉄道の出資の金額ですけれども、委員ご指摘のとおり、平成１７年、平成１８年、あわせまして１０億円を出資しています。その１０億円を含めまして、２２億円の出資です。割合ですけれども、発行済み株式に対する割合としては、品川区は１.９１％を保有しています。","voiceIndex":105,"id":"exchange-048"},{"speaker":"渡部委員","kind":"質問","question":"例えば区としても、公共交通、出資されている中で、例えば区内の人たちの利用に向けて、何か割引制度、例えばですが、品川シーサイドから大井町まで出てくる人、大崎のほうから区役所に来るのに大井町まで乗る人ですとか、何らかの、役員も本間副区長が入っているということで、割引制度を区として、臨海高速鉄道に持っていくことというのはできないんでしょうか。その辺を教えてください。","respondent":"阿部都市計画課長","answer":"ただし、利用者の方々にさまざまなサービスをすることは当然のことですので、その点につきましては、私どもとしても臨海高速鉄道には申し入れをしていきたいと考えています。","voiceIndex":107,"id":"exchange-049"},{"speaker":"渡部委員","kind":"質問・要望","question":"続きまして、１４１ページの道路維持費の中、特に交通安全施設整備事業等のところでお伺いしたいんですが、さきの一般質問においてもスクールゾーンの時間帯の変更のことをお伺いして、これから進んでいくよということですが、そうなりますと、溶着の部分ですとか、いろいろ施設整備にもお金がかかってくると思います。ちょっとお伺いできますでしょうか。","respondent":"松代管理工事課長","answer":"道路に立っています標識には２種類あります。今、委員ご指摘のとおり、警視庁国家公安委員会がつくる道交法に基づいた標識、それと、我々、道路管理者として設置する標識の２種類があります。ここにありますのは、私どもが設置している標識です。","voiceIndex":109,"id":"exchange-050"},{"speaker":"渡部委員","kind":"質問","question":"ちょっとその辺、不勉強でわからなかったんですが、例えば区のほうとして、道路管理者としてつける標識と警察の道交法上つける標識との違いというのは何かあるんでしょうか。教えていただけますか。","respondent":"松嶋交通安全担当課長","answer":"端的に言いますと、道路管理者がつけるものは、例えば警戒標識とか案内標識、そういったものでございまして、公安委員会がつくるものにつきましては、規制標識です。","voiceIndex":111,"id":"exchange-051"},{"speaker":"渡部委員","kind":"質問","question":"交通安全施設事業の中で、この辺の道路標識、スクールゾーンカラー表示とか、あります。先日答弁いただいて、これからどんどん時間の変更等進んでいくという話をいただいたんですが、例えば今、進んでいる中で、前回、大井の地区のほうで進んでいるという話を伺いました。荏原地区のほうの状況等、わかれば、スクールゾーンの時間変更等、教えていただけますでしょうか。","respondent":"松嶋交通安全担当課長","answer":"現在、現実に今進んでいるところは、浅間台小学校と品川小学校、それともう一校が伊藤学園、この部分が進んでいるところです。なお、荏原地区のほうにつきましても、今後、来年度以降に順次実施をしていきたいと考えております。","voiceIndex":113,"id":"exchange-052"},{"speaker":"渡部委員","kind":"質問・要望","question":"区内、１万１,０００台置けるところがありまして、撤去台数というのが、今、平成１８年自体、２万８,０００台で、これから撤去を厳しくしているから増えていているということなんですが、これは実際、撤去されまして、今、オンラインで管理しているということなんですが、同じ人、いわゆる同じ自転車の放置割合はどれぐらいになっているか、わかりますでしょうか。","respondent":"松嶋交通安全担当課長","answer":"申しわけありません。割合につきましては、正確な数字はありませんけれども、何度もやっている方は、こちらは把握しております。今現在一番多い方で、８回ということであります。","voiceIndex":115,"id":"exchange-053"},{"speaker":"渡部委員","kind":"質問","question":"８回となりますと、常習で、そのたびに３,０００円払っていたら、買ったほうが安いんじゃないかと、変な話、なってしまうんですが、そのような方々、例えばこれが２回なのか、３回なのか、わからないんですが、そのように、この人は何回目だぞとわかるものに関しては、区から何らかの指導なり、はがきなり、何か方策を練っているんでしょうか。","respondent":"松嶋交通安全担当課長","answer":"ただ、先ほどもありましたとおり、１回３,０００円ですから、それが積もり積もっているわけですので、そういった部分はどのように考えているか、ちょっとわからないところもあるんですけれども、いずれにしても、そういった状況でやっているところです。","voiceIndex":117,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"初日に引き続きまして、再開発の問題なんですが、１４６ページの都市計画費の都市開発費についてお伺いいたします。あわせて、今回都市開発費、１１４億円、平成１８年度入っていますけれども、再開発分のうちの、原資が国からの補助金と都の補助金が出ていると思うんですが、１１４億円のうち、どれぐらいが国と都から出ているんでしょうか。","respondent":"青木都市開発課長、日下部企画財政課長","answer":"そのうち、想定の部分も含んでしまいますけれども、補助金が投入されます予定が５６９億円ほど、総事業費の約１１％強になるかと思います。財源の問題ですけれども、平成１８年度から、今、都市開発課長が申し上げましたように、２分の１は国庫、残りにつきましては、約４分の１になりますけれども、これにつきまして、再開発組合に対する補助金につきましては。","voiceIndex":120,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問・要望","question":"このような大規模で、なおかつさまざまな高度な専門的知識も必要な事業ですので、当然、住民発意とよく区側もおっしゃいますけれども、区や都などの行政が強烈に推進というか、協力をしないと進まないものだと思っておりまして、北品川五丁目の準備組合の、今年の２月ですかね、２月に行われました説明会で配られた資料の中にも、「私ども北品川五丁目第１地区市街地再開発準備組合は。","respondent":"青木都市開発課長","answer":"再開発事業というのは、いろんな意味合いがありますけれども、委員ご指摘のように、大崎駅周辺の６０haの区域につきましては、都市再生緊急整備地域という指定をされておるところですので、これは国策にも従う形で。","voiceIndex":123,"id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"積極的に推進していくということでしたけれども、具体的な点で、同じ平成１８年度の予算で、小関橋の新設設備整備工事委託、３億３,０００万円がありますけれども、この橋なんですけれども、北品川五丁目開発の関係で言いますと、当時はまだ都市計画決定がされていない開発ですけれども、ちょうどその開発事業の予定のメインストリートの１６ｍ道路に直結する橋になっておりますけれども。","respondent":"青木都市開発課長","answer":"３点目として、御殿山小学校への日影規制の問題ですけれども、こちらにつきましても、事業としては、御殿山小学校については、再開発事業から外れておりますけれども、再開発を進めるに当たって、地区計画を定める段階では、同じ地区計画の中に定めて。","voiceIndex":125,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"施工主の方が説明に来たのは、都市計画決定前に１回だけ来て、そのときに、どういう計画なのかという、図面などを全く持ってこなかったと。それ以来、一度も全く来ない。それが１つ。こういった、これまで地域で長年生活されていた方の生活実態を奪いかねない事態になるんじゃないかなと思うんですが、そのことに関しては、どういった手当て、あるいは認識、お伺いしたいと思うんですけれども。","respondent":"青木都市開発課長","answer":"それは、それぞれのご事情、ご自身の生活再建を自分で設計して、ご自身でまた新たにチャレンジをしていくというものですので、それは、再開発準備組合、あるいは再開発組合の段階でも、そういった権利者の方々のお世話といいますか、いろんな生活再建に対する相談業務等も。","voiceIndex":127,"id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"出ていく自由はあるけれども、そこに残る自由はないという話だと思うんですけれども、あと、もう一つ重要なのが、税金の使い方だと思うんですね。私はよくわかりません。優先順位として、先ほど同僚議員からもありましたけれども、こうしたお金を使うのであれば、しっかり今求められている策、例えば公営住宅の建設、あるいは高齢者医療費の無料化などに税金を使うべきだと思うんですが、いかがでしょうか。","respondent":"日下部企画財政課長","answer":"品川区におきましては、すべての施策についてバランスをとりながら、しっかりと進めている。そういう現状ですので、ご理解をいただきたいと思います。","voiceIndex":129,"id":"exchange-059"},{"speaker":"渡辺委員","kind":"質問・要望","question":"私のほうは、１４１ページ、交通安全施設整備、また、街路樹整備費、１４５ページの公園・児童遊園維持管理について、お伺いしたいと思います。それともう１点、歩道に木が飛び出して、歩きづらい、危ないというご指摘の中では、公共施設だけじゃなくて、民間、あるいは民家の木に対しての区民要望も多いかと思いますが、その辺はどのような対応をなされているのか、お伺いしたいと思います。","respondent":"藤田道路公園課長","answer":"街路樹等の維持管理ということでの剪定ということでのお尋ねですが、樹木、木は、切るのにちょうどいいような時期というのがあります。そういった観点から言うと、全部まとめて同じ時期に切ればいいということではありません。簡単に言いますと、例えばサツキが植わっている。","voiceIndex":133,"id":"exchange-060"},{"speaker":"渡辺委員","kind":"質問","question":"ご指摘の民地、民家の木に対する、今、お願いという表現がありましたが、こちらは何か条例や法律の関係で、指導を強く言えるケースというのはあるんでしょうか。","respondent":"藤田道路公園課長","answer":"民地側の隣のお宅に行けば、当然隣との関係の中では剪定するというのが前提になりますので、私ども、緑を守るという観点と、それからそういった法律上といいますか、一般的な常識の話と重ね合わすと、まずはお願いをしながら。","voiceIndex":135,"id":"exchange-061"},{"speaker":"渡辺委員","kind":"質問・要望","question":"関連してお伺いしたいんですが、季節にもよるんですが、特にこれからの季節、落ち葉の区民要望というのも、落ち葉清掃、結構あるかと思いますが、場所により事情は異なると思いますが、重点地区や、あるいはそういったケースの場合、区民の方は、申告して、初めて落ち葉清掃、お願いができるのか。この辺を伺いたいと思います。","respondent":"藤田道路公園課長","answer":"ただ、道路の清掃については、昔からですけれども、地域の方々、自分のおうちの前はお掃除をするという形でご協力いただいている人たちも大変多くあります。そういう中で、地域の力と私どもと合わせてきれいな道路にしていきたいと考えています。","voiceIndex":137,"id":"exchange-062"},{"speaker":"渡辺委員","kind":"質問・要望","question":"交通安全施設整備のことでお伺いしたいと思います。おそらく作成に携わった方は、本当に近所、近隣の住民の方で、ものすごい熱意を持って作成をされたというものが感じられるんですが、このまちづくりの会、戸越・豊町地区なんですが、まちづくりの会の主な活動とメンバー構成を伺えればと思います。","respondent":"伊勢住環境整備担当課長","answer":"その後、林試の森公園等の視察も行ってあります。今後は、地区計画だとか、あるいは防災活動に資する道路ネットワークの検討等を行っていこうというふうに予定されてあります。","voiceIndex":139,"id":"exchange-063"},{"speaker":"渡辺委員","kind":"質問・要望","question":"やはりこの地域においては、広く的確に住民要望が集約されていると考えられますので、国文学資料館跡地、平成２０年度からの暫定整備の際で、ぜひ施設周辺の道路、特に歩道の点に注目をして、歩道確保、しっかりとした整備で、先行してでも実行される必要性があるかと思われますが、お考えをお伺いしたいと思います。","respondent":"松代管理工事課長","answer":"私ども、それを十分に踏まえまして、暫定利用に当たって、そのようなことを考えられないかと、今、検討しております。ただ、冒頭申しましたように、暫定ですので、本格整備と二重投資にならないような、そういったことも十分考えながら、計画を練ってまいりたいと考えております。","voiceIndex":141,"id":"exchange-064"},{"speaker":"渡辺委員","kind":"質問・要望","question":"最後に、公園・児童遊園の維持管理について、簡潔にお伺いしたいと思います。各公園、非常にきめ細かな整備で、特に今回お伺いしたいのは、植えられている樹木について伺いたいと思います。現状でどのような樹木が多いのか。本当に幅広くなってしまうので、ランキングではないんですが、上位ベスト３ぐらいのものを、比率とともに伺えればと思います。","respondent":"松代管理工事課長","answer":"公園の樹木です。区立公園、二百十数カ所ありますけれども、高木等も含めて、約４万本ほどあります。その中で、高木にちょっと絞って考えますと、上位から椎の木が１,８００本ぐらい、桜が９００本ぐらい、次にイチョウ５００本ぐらいの割合で植えているものです。","voiceIndex":143,"id":"exchange-065"},{"speaker":"渡辺委員","kind":"質問・要望","question":"やはりこれからの整備、かなり行き届いている中で、あの公園は何々が特徴というような、実際今の現実もあわせて、話題づくりと。そういった演出も逆にあってもいいのかなと思われます。これは、バランスというのは非常に難しいかと思いますが、ぜひそのような方向で、話題になる公園を提供いただければと思いまして、要望として終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-066"},{"speaker":"藤原委員","kind":"質問・要望","question":"１４９ページの区民住宅費についてお伺いしますが、現状の入居の状況で、空き室の数について、建設型と借上型に分けて伺わせていただきたいのと、それとあと、中長期的に見て、区民住宅の空き室は、これから増えていくのでしょうか。それとも減っていくのでしょうか。予想といいますか、区のご見解をお伺いしたいと思います。","respondent":"齋藤住宅課長","answer":"区民住宅の入居率ですが、今日現在、２８の空きがございまして、全体で見ますと、９７.３％ぐらいの入居率です。建設型を見ますと、３つの空きで、９９％。借り上げ型は、２５の空きがございまして、９２％。","voiceIndex":147,"id":"exchange-067"},{"speaker":"藤原委員","kind":"質問","question":"今、住宅課長からご答弁いただいた３住宅、４０戸ということですが、多分これからも入らないと思いますとこの場で断言をされて、そうですかとは言えないわけですよね。それと、具体的に区としては、空き室がこういうふうに出たときに、どのような対処をしているのかをお答えください。","respondent":"齋藤住宅課長","answer":"こういう言い方をしまして、あと、オーナーの方も、手放したい、こういうことがございましても、２０年間、これは事業認可の期間なんですけれども、この間は手放すことも、例えば個人の名義を会社の名義にすることもできない。","voiceIndex":149,"id":"exchange-068"},{"speaker":"藤原委員","kind":"質問","question":"結局持ち出しているわけですよね。ちょっと調べたら、４年以上の空き室があるんですけれども、大体この空き室に対して補償額というのは、今までどのぐらいしてきたんでしょうか。","respondent":"齋藤住宅課長","answer":"去年、空き、最大で３５までいきまして、今年は２７です。年間大体３,５００万円から４,０００万円ぐらい、この４年ですので、掛けることの１億５,０００万円以上は、空き室に家賃補償したです。","voiceIndex":151,"id":"exchange-069"},{"speaker":"藤原委員","kind":"質問","question":"結局、オーナーが土地を提供して、低利で建てて、家賃を下げなくても、入らなかったら区が全部その家賃補償をしてくれるという制度ですよね。この制度は、一体だれのためにあったんでしょうか。区民のためですよね、安定供給ということで。だけど、結局こういう数字で、今まで何億も補償してきた。オーナーはいいかもしれませんけれども、区民は納得いかないと思うんですね。その辺についていかがでしょうか。","respondent":"齋藤住宅課長","answer":"だれのためにということになりますと、その当時、２０万円なければ、家を借りられなかった。８万円台で借りられる。そういうことに国としての政策的な必要性があったんだと思います。ただ、残念ながら、私どもの区で言うと、３住宅がなかなか設定家賃が高い。","voiceIndex":153,"id":"exchange-070"},{"speaker":"藤原委員","kind":"質問","question":"国のほうも、これはまずいということで、特優賃の制度をどうにか変えていかなくちゃということが出始めて、検討するということが出てきたと思うんですけれども、先ほどもちょっと金額的なお話も少し出たと思うんですけれども、この検討を、結果、どのような形で、どういうふうに具体的になっていくんでしょうか。","respondent":"齋藤住宅課長","answer":"こういうことでありまして、今、２３区を挙げて、使い勝手が悪い制度なので、改善要望をしているです。","voiceIndex":155,"id":"exchange-071"},{"speaker":"藤原委員","kind":"質問","question":"ぜひ２３区挙げて、改善してください。どうでしょうか。","respondent":"齋藤住宅課長","answer":"２３区を代表して、国に改善要望しております。それで、１,３００万円の地域交付金がもしかしたらもらえたのではないかなと考えていますので、引き続き頑張っていきたいと思います。","voiceIndex":157,"id":"exchange-072"},{"speaker":"阿部委員","kind":"質問","question":"私からは、１４１ページの道路維持費の中の点字ブロック、そして、１４６ページ、大崎駅周辺の再開発、それから、最後、これは多分１４０ページ土木管理費、土木総務費の中に入るんでしょうか。自転車の通行についてお伺いしたいと考えています。あるいは、今後どのぐらい整備をしていくといった、全体の計画というのはあるのでしょうか。教えてください。","respondent":"松代管理工事課長","answer":"ここに来まして、平成１３年に、実施計画というもので、数値目標を挙げまして、これまで取り組んでおります。そのときの実施計画の目標は、１,０００ｍを目標にしまして、順次、毎年計画的に進めてまいりました。ここ６年間で、８７６ｍほど整備しております。","voiceIndex":160,"id":"exchange-073"},{"speaker":"阿部委員","kind":"質問","question":"１,０００ｍの目標ということなんですが、実際にまちを歩いていますと、点字ブロックって、先ほどもほかの委員のご質問でありましたが、材質がいろいろばらばらであったりとか、１つの交差点の中で、こっちの角はあるけど、こっちはないとか、あるいは、福祉施設の近くでというようなお話もさっきありましたけれども、どの場所にどのように設置されているかという基準のようなものはあるのでしょうか。","respondent":"松代管理工事課長","answer":"バス停等につける場合があります。そのほかは、私ども、品川身体障害者の団体の皆様と定期的にいろいろと会合を持っておりまして、そういう中で、ぜひここに設置してほしいというところを優先的に設置する。そういった考えで設置しています。","voiceIndex":162,"id":"exchange-074"},{"speaker":"阿部委員","kind":"質問","question":"知らない道の点字ブロックというのは、やっぱりわからないのであるというようなお話を伺ったことがあります。これはもしかすると、まちづくりとは離れてしまうのかもしれないですけれども、ソフト面での拡充といいますか、運動を起こしていくというか、呼びかけていく、そういったようなお考え、ハード整備とあわせてやっていくような、そういった考え方というのはありますでしょうか。","respondent":"松代管理工事課長","answer":"障害者の方にとって、ちょっと手を差し伸べていただく。そういったことを広げていけないか。そういったことでバリアをなくすようなことができないか。そういったことも含めて、今、検討しています。","voiceIndex":164,"id":"exchange-075"},{"speaker":"阿部委員","kind":"質問","question":"そのご検討のスケジュールみたいなものがあれば、教えてください。","respondent":"上山介護保険担当課長","answer":"これは、案の段階でございまして、それを来年の２月には、パブリックコメントを実施いたしまして、３月末に改定作業を終えたいと考えております。","voiceIndex":166,"id":"exchange-076"},{"speaker":"阿部委員","kind":"質問","question":"了解しました。先日、産業経済費のところで、区と大学との連携ということを少し触れたんですけれども、例えばものづくりの歴史を持った大崎のまちの再開発の中で、ものづくりを核とした高等教育機関、大学、あるいは研究機関といったところとの連携、ないし、そういった研究機関と地元の産業との交流の場になるような機能、あるいは場所といったものをつくられるような、そんなお考えはありますでしょうか。","respondent":"青木都市開発課長","answer":"産業経済費のときに担当課長からもご説明申し上げたと思うんですけれども、ご案内のとおり、大崎でまちづくりを進めておりまして、委員ご指摘のとおり、大崎の歴史を考えますと、ものづくりをキーワードにまちづくりを進めていきたいと考えておる中で、既に。","voiceIndex":168,"id":"exchange-077"},{"speaker":"阿部委員","kind":"質問・要望","question":"最後の質問なんですけれども、自転車の通行についてお伺いしたいと思います。先ほどより、放置自転車についてさまざまな質問が出てきて、確かに決算の面でも、放置自転車という言葉があるんですけれども、そもそも自転車が安全に通行するためのインフラというのが整っているのかどうかということ。この品川区におきまして、自転車の安全通行のためのインフラ整備について、何かお考えをお持ちでしょうか。","respondent":"松嶋交通安全担当課長","answer":"したがいまして、区といたしましては、これらのことを改善するために、現在、新たな施策として、新たなと言っても、国交省はちょっと言っているかもわかりませんけれども、路側帯の有効活用によりまして自転車の走行空間を確保するということに着手していきたいと考えております。","voiceIndex":170,"id":"exchange-078"},{"speaker":"阿部委員","kind":"質問","question":"路側帯の中に自転車の通行帯を確保するということですが、具体的に対象や手法などは決まっているのでしょうか。車が進入してきにくくするといった手法もとられているみたいですが、品川区の場合には、安全策を持って路側帯を使うということを進められようとしているのかどうか、教えてください。","respondent":"松嶋交通安全担当課長","answer":"路側帯に現在青のカラー舗装というものを今後全国的にやろうという話ですので、レーンを青にカラー舗装いたしまして、もちろん構造上、構造物はちょっと置けないんですけれども、カラー舗装して、要は視覚的な分離対策を実施していきたいと考えております。","voiceIndex":172,"id":"exchange-079"},{"speaker":"阿部委員","kind":"質問・要望","question":"実験という意味で、ぜひやってみていただきたいと思います。ただ、一方で、路側帯、道の端っこのところは段差が多かったりして、段差と言ったらいいんでしょうか、アスファルトのちょっとずれたようなところがあったりして、ちょっとがたがたっとタイヤがとられやすいような、そんな部分がある。そういった危険というのが逆に出てくるかと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":174,"id":"exchange-080"},{"speaker":"武内委員","kind":"質問","question":"私からは、１４３ページの橋梁費、それから、１４８ページの木造住宅耐震化経費助成費の２点、お伺いしたいと思います。橋梁費については、皆様もご存じのとおり、８月にアメリカのほうで、ミネアポリスですか、橋が落ちましたけれども、それで、いろんな報道等でも、日本の橋が大丈夫なのかというようなことで、報道によるとかなり、なかなか厳しい状態があると聞いております。","respondent":"松代管理工事課長","answer":"それを受けまして、対象となる橋梁の４８橋に耐震化の工事を計画的に進めてきております。現在は、これまでに４５橋、すべて完了しておりまして、残り３橋です。３橋につきましても、順次、今、計画を進めているところです。","voiceIndex":176,"id":"exchange-081"},{"speaker":"武内委員","kind":"質問・要望","question":"残り３橋ということなんですけど、本当に計画的に、阪神・淡路大地震の前から調査を行って、計画的に進めてこられたということで、非常に安心しているんですけれども、区の中には、都の橋と、また国が管理の部分もあると思うんですけれども、この辺についてはどうなっているのか。大体の数とあわせてどれぐらいの割合で大丈夫なのかというのを、わかれば教えていただきたいと思います。","respondent":"松代管理工事課長","answer":"申しわけございません。国と都の管理しております橋につきましては、細かく数字等、把握してございません。","voiceIndex":178,"id":"exchange-082"},{"speaker":"武内委員","kind":"質問","question":"平成１９年の予算書には橋梁台帳管理システム作成委託等、１２３万６,０００円ほど計上されていますけれども、これは、そうすると、橋梁台帳管理システム作成なので、区のだけなんでしょうか。それとも、国とか都の、区内にある、こういうのも含んでいるんでしょうか。","respondent":"松代管理工事課長","answer":"大変失礼しました。実数、数量だけで申し上げますと、国の橋梁が１１、東京都の橋梁が１８、品川区が４８ということで、歩道橋で申し上げますと、国が１６、東京都が１０、品川区が２２ということを把握しています。","voiceIndex":180,"id":"exchange-083"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、今質問した橋梁台帳管理システムが平成１９年予算で入っているんですけれども、これは全部管理するような台帳なんでしょうか。","respondent":"松代管理工事課長","answer":"私ども、管理システム、基本的に品川区の財産をきちんと管理するための把握するシステムですので、そこの中には、品川区の管理する橋等をシステムに入れているものです。","voiceIndex":182,"id":"exchange-084"},{"speaker":"武内委員","kind":"質問","question":"定期点検も３割しか行ってないような状態だというようなアンケート結果も出ていますので、区については、先ほどお示しいただいたとおり、非常に安心しているんですけれども、国とか都の管理の区内にあるものも、やはり区が状況をつかんでいただいて、それで、もしそういう計画がなされてないようであれば、しっかりそれも申し入れていただいて、早急にやっていただくようにお願いしたいと思うんですけれども。","respondent":"松代管理工事課長","answer":"東京都、もしくは国のほうに、そういったことを問い合わせまして、十分調査と協議を進めてまいりたいと考えています。","voiceIndex":184,"id":"exchange-085"},{"speaker":"武内委員","kind":"質問","question":"１４８ページで、平成１８年度の実績については、粗々、この数を見て、わかるんですけれども、歳入のところでもご質問しましたけれども、いよいよ住宅の耐震促進計画の中間まとめ案が出たという発表が建設委員会でありまして、その中身について少しお伺いしたいと思いますが、読ませていただくと、木造住宅については、５４.４％ですか。","respondent":"片田建築課長","answer":"結論から言いますと、国や都よりもかなり精度を上げた調査をさせていただいた経過があります。ちなみに、国と東京都は、平成１５年度の土地、建築物の統計調査、これを基本に置いた推定値を出してきているということで聞いてあります。","voiceIndex":186,"id":"exchange-086"},{"speaker":"武内委員","kind":"質問","question":"それ以外の啓発の部分とか、また、今回新たに耐震シェルターみたいなものについても、支援ということで、どういう支援をするかはちょっとわかりませんけれども、入っていますので、そうした実際に直接補助する割合とそれ以外のものとの比率というのは、大体どれくらいを考えていらっしゃるんでしょうか。","respondent":"片田建築課長","answer":"補助の割合ですけれども、一応今後、平成２７年までの事業費については、いろいろそういう補助の想定を含めて検討していますけれども、現在、国および東京都の支援制度、それらを活用させていただいて、区としての補助を決定させていただいているんですけれども、現時点で。","voiceIndex":188,"id":"exchange-087"},{"speaker":"武内委員","kind":"質問・要望","question":"それで、それ以外の意識の啓発だとか、直接促進計画のパーセンテージには含まれませんけれども、命を守る取り組みとしてのシェルターの支援ですとか、ここにはまだ載っていませんけれども、簡易改修についてもどうしていくのかとか、その辺の大まかな考え方がもし出ているのでしたら、教えていただきたいということなんです。","respondent":"片田建築課長","answer":"それ以外についても、直接補助のほかに、いろいろな個別訪問した場合の支援費等々についても、国のほうは検討をし始めている、あるいは耐震シェルター等々についても検討をし始めているですので、その辺の情報を察知して、適正に、これをできるところについては、取り込んだ中で。","voiceIndex":190,"id":"exchange-088"},{"speaker":"武内委員","kind":"質問・要望","question":"そういう方については、例えばシェルターですとか、安い簡易改修ですとか、そういったものについても支援できますよということで、間口を広げていただくと同時に、この計画、９０％というのは、もちろん大事なものなんですけれども、それにあまりとらわれずに、しっかり地に足がついたというか、そういう取り組みをしていただきたいなと思うんですが、それについての見解をお伺いしたいと思います。","respondent":"片田建築課長","answer":"ただ、いろいろメニューとして、まちを守る、あるいは人の命を守るといったような切り口の中で、建物の安全性、あと、個人の命を守る上でのシェルター等々についても、いろんな角度から考えていきたい、このように考えてあります。","voiceIndex":192,"id":"exchange-089"},{"speaker":"原委員","kind":"質問","question":"私のほうからは、成果報告書の１４３ページ、目黒川のほうの排水設備関係、それから、１４４ページの水質調査等の委託関係、それから、あと１４６ページで、目黒川の緑道、それから、親水護岸、その辺まで、全体的に目黒川についてお聞きしていきたいと思うんですが、まず、細部のほうからお聞きしてまいりますけれども、川底の問題ですとか、排水設備関係その１、２とか、実際に続いて。","respondent":"家壽田下水道河川課長","answer":"以後、今後は、その２に引き続きまして、その３、その４工事というふうに続いてまいります。それから、続きまして、河川水質の調査ですけれども、これは目黒川で、全体７カ所の水質を調査するものでございまして、昨年度実施しております。","voiceIndex":195,"id":"exchange-090"},{"speaker":"原委員","kind":"意見","question":"そうしますと、「等」というのは便宜上ついているという解釈でよろしいわけですよね。ちょうど、まあ、これは次ですけど、決算特別委員会なので、２００万円しかついてないんですけれども、平成１９年度４,８００、約５,０００万円ついておりますので、これは水質調査という解釈でよろしいわけですね。","respondent":"家壽田下水道河川課長","answer":"すいません。目黒川水質調査等委託について補足しますと、平成１８年度におきましては、「等」の中では、立会川の土壌調査の委託を行っています。","voiceIndex":197,"id":"exchange-091"},{"speaker":"原委員","kind":"質問","question":"ご丁寧にありがとうあります。よくわかりました。天候の関係が、大分温度が下がってきたので、においも大分減ってきたみたいな感覚はあるんですけれども、私自身も、目黒川も今回、高濃度酸素溶解水を入れていろいろやっていかれるというのは聞いておるんですけれども、片方でかきまぜて、片方で水質調査をやられているという状況について、ご説明いただけますでしょうか。","respondent":"家壽田下水道河川課長","answer":"立会川のほうにつきましては、同じように、かき回してしまいますと、泥がまき上がって、それが川を汚してしまうことになりますので、今回、委員ご指摘の高濃度酸素溶解水というものは、そっと川の底に酸素の入った水を戻すということで、浄化の実験を行っております。","voiceIndex":199,"id":"exchange-092"},{"speaker":"原委員","kind":"質問・要望","question":"今度は、緑道とか、水質、これについてちょっとお伺いしていきますけれども、今の段階としては、開発地の一部という解釈で、将来的には当然に防災上の問題ですとか、かなりもう少し先になろうかと思うんですけれども、都とかの打ち合わせをしていただいて、これが例えば水上バスですとか、観光資源の１つにならないかとか、そういった問題等に関しましてご意見をちょうだいできればと思うんですけど。","respondent":"青木都市開発課長","answer":"そこにつきましては、目黒川により近い位置で人々が親しんでいただけるようにということで、護岸を低くするものですけれども、あわせて、防災用の船着場の設置を現在検討しております。","voiceIndex":201,"id":"exchange-093"},{"speaker":"原委員","kind":"質問・要望","question":"地元の人の意見をくまなく、細部にわたるまで聞いていただきたいと思います。それで、ただ、これ、管理者が、区も当然、実際具体的な主たる管理者は東京都だと思うんですけれども、この辺との関連関係はどういうふうになっているか、もう少しご説明いただければと思います。","respondent":"青木都市開発課長、家壽田下水道河川課長","answer":"この広場につきましては、地元の方々、再開発事業者であるとか、現段階ではまだ事業者中心ですけれども、新たにお住まいになる方々、地元の方々と区の一定の協力関係のもとで管理をしていきたいと考えております。若干補足します。河川法の第１０条によりますと、目黒川は２級河川ですけれども、この管理は当該都道府県が行うことになっております。","voiceIndex":203,"id":"exchange-094"},{"speaker":"原委員","kind":"質問・要望","question":"この間もちょっと、先々週でしたか、いろいろな現場のほうで調査をやっておられるのを確認いたしましたので、それで、これは、国だけではなくて、政官学、こういう表現をしていいのかどうかわかりませんけれども、先ほどもどなたかほかの委員がお話ししていたように、大学等、例えば地域のほうで、立正大学なんかは非常に世界的に環境問題等に関しましては、精通している先生がいらっしゃいますし。","respondent":"青木都市開発課長","answer":"目黒川全体ですので、１つ、まちづくりという視点だけではないんですけれども、地元の方々、あるいは大学関係、研究関係の方々とのいろんな主体の協力関係というのは今後行政の課題になってまいりますので。","voiceIndex":206,"id":"exchange-095"},{"speaker":"井上委員","kind":"質問","question":"私からは、１４５ページの都市計画費の区民の自主的なまちづくりへの支援と水とみどりのネットワーク構想、そして、１４２ページ、東急目黒線立体交差事業について伺います。しかし、現在では、執行率から見ると、この制度が区民にとって有効に活用されていないように思えるんですけれども、この結果を担当課としてどのように評価しているのか、お伺いしたい。その辺についてもお伺いいたします。","respondent":"伊勢住環境整備担当課長","answer":"この予算編成時期に、どれぐらいの量があるかということを考えるんですが、ちょうど平成１８年度の予算編成時期、平成１７年の秋ごろなんですが、大変問い合わせが結構多かったということで、これらの問い合わせに対応するために予算措置をしたものです。","voiceIndex":209,"id":"exchange-096"},{"speaker":"井上委員","kind":"質問","question":"お知らせをしているけれども、なかなか地域のほうで使われていないという状況があるのかと思うんですけれども、このまちづくりの推進要綱を見ますと、そういった会を組織をし、申請書を出すということになっていて、その中で、区へ登録されたコンサルタントの中から、区のほうで住民の申請の目的に合った人たちを派遣するという仕組みになっているわけですけれども、ここを一歩先に進んで。","respondent":"伊勢住環境整備担当課長","answer":"それで今、委員がおっしゃったのは、ある団体がある専門家を推薦して、それをドッキングして専門家派遣できないか、こういうようなご趣旨ですけれども、基本的には、先ほどおっしゃったようなこういう仕組みで。","voiceIndex":211,"id":"exchange-097"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほどの予算の件なんですけれども、２００７年度の予算額が１２９万８,０００円ということで、今年度の予算になりますけれども、前年度の半額になっていて、それはきっと２００６年度の実績見合いということで、予算額が算定されたのかと思いますけれども、今回の場合でいうと、来年度の予算の見通しなどはどんなふうにお考えでしょうか。","respondent":"伊勢住環境整備担当課長","answer":"お問い合わせだけで終わっちゃうということもありますけれども、基本的にはこういうお話が来たら、予算的には措置しているというような状況をお出ししたい。こういうスタンスで編成していきたいと考えています。","voiceIndex":213,"id":"exchange-098"},{"speaker":"井上委員","kind":"質問・要望","question":"そこで、品川区として、まちづくり事業部、今日はそうなんですけれども、それだけではなく、全体の品川区の考えとして、市民側の利用ニーズと執行機関側の意識のミスマッチというのをどういうふうに改善していただけるのかということを、全体のこととしてぜひ副区長にお伺いできればと思うんですが、いかがでしょうか。","respondent":"伊勢住環境整備担当課長、福田企画部長","answer":"ですから、必ずしもこの制度、もっともっと、この制度、固定的にこういうふうには考えてございませんけれども、そういう面では、またそういう状況の変化に応じて、変えていく場合があれば、やりますけれども、今のところは。そういう問題意識に基づきまして、区長がよく申しますが、区民の声をきちんと聞く。このことを原点に据えて考えてまいりたいと考えています。","voiceIndex":215,"id":"exchange-099"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひこういう仕組みがあって、こういうふうにやっているんだということで納得していただかないで、そこのところでは、どういう要望があって、なぜそういう声が上がっていくのだということをぜひ一緒に考えていただきたいと思います。それで、次に、新・水とみどりのネットワーク構想検討経費についてお伺いいたします。今回の２,１００万円の経費の内訳がどのようなものか。","respondent":"松代管理工事課長、家壽田下水道河川課長","answer":"経過ですけれども、当初、新・水とみどりのネットワーク構想の、今言いました、調査・検討を主にやる予定でございましたけれども、その後、目黒川の水質等の改善ということで、調査をするということで、金額を計上したものです。そうした経費も今回の決算の中には含まれております。","voiceIndex":218,"id":"exchange-100"},{"speaker":"井上委員","kind":"質問","question":"ということは、２,１００万円の中で、この内訳ということで、その後、水とみどりのネットワーク構想をつくるに当たってコンサルタントが入っているかと思うんですけれども、その辺の経費の内訳を一緒に教えてください。","respondent":"松代管理工事課長、家壽田下水道河川課長","answer":"今、委員からもお話がありましたように、私どもの水とみどりのネットワーク構想のための調査費が、先ほどの金額、７５０万円でございまして、目黒川の水質等の関係の金額が先ほどの金額です。目黒川の浄化検討として、１,３５０万円です。","voiceIndex":221,"id":"exchange-101"},{"speaker":"井上委員","kind":"質問・要望","question":"そこで、構想検討経費なので、コンサルタントなどが入って基礎データなどをまとめたんじゃないかなとお聞きしたものですので、この２,１００万円の決算がどういうふうな、コンサルタント委託費が幾らで、下水道、ここに水とみどりのネットワーク構想検討費というふうに、構想検討費でここに水質の予算がぽーんと入っていくというのもよくわからないんですけれども、その辺のことをお伺いしたのと、あと。","respondent":"松代管理工事課長","answer":"そういった意味のための調査をしなければいけないということで、平成１８年度、新・水とみどりのネットワーク構想検討経費、２,１００万ということを計上しまして、その中の内訳が、構想自体の基礎データ、さらに、目黒川の水質等の調査をするものが１,３５０万円ということで。","voiceIndex":224,"id":"exchange-102"},{"speaker":"井上委員","kind":"質問・要望","question":"これを構想をつくるという中で、まだパブリックコメントの結果も出ず、これは中間案ですから、本構想が出ないままに、具体的な施策について予算が分かれているということは、おかしいと思います。それから、そこについて答弁をいただきたいんですけれども、本当はもっともっと構想の中に入りたかったんですけれども、入り口でちょっとよくわからないので、その辺についてだけきちんと説明してください。","respondent":"松代管理工事課長","answer":"平成１９年度の計上ですけれども、緑と花のあるまちづくりということで、緑化推進のところに緑の行動計画検討委託ということで、平成１９年度の予算書の中には計上しているものです。","voiceIndex":228,"id":"exchange-103"},{"speaker":"高橋委員","kind":"質問","question":"１４３ページの道路橋梁費の中の受託事業費という、先ほど目黒川の話が少し出たんですけれども、受託事業費というのは、どのような性格のものなんでしょうか、お教えください。","respondent":"家壽田下水道河川課長","answer":"下水道河川課のほうで所管しております受託事業の内容でご説明申し上げますと、当課で行っております下水の雨水排水施設の整備工事につきましては、基本的に東京都の事業を区がなりかわって行っておりますので、全額都のほうからお金をいただいてやっております。","voiceIndex":231,"id":"exchange-104"},{"speaker":"高橋委員","kind":"質問","question":"とすると、今、都のほうでお金がもらえるのは、この４つのうちのどれになるんでしょうか。目黒川の排水施設建設事業はそうだとは思うんですが、すいません。","respondent":"岩田まちづくり事業部長","answer":"成果報告書の１４３ページに４項目受託事業費で挙げしています。","voiceIndex":233,"id":"exchange-105"},{"speaker":"高橋委員","kind":"質問","question":"ということは、この区が受託をそれぞれしているんですが、メリットというのはどの点にあるんでしょうか。","respondent":"松代管理工事課長、家壽田下水道河川課長","answer":"そういったものを一たん私どもで受けて、一括で道路を整備します。そうしますと、騒音・振動、工事による被害がといいますか、ご迷惑をかけるのが１回で済みます。先ほどもご説明いたしましたシールドという、比較的大規模な公共工事を行うということで、区の固有の技術職員の技術向上にも資するということで、さまざまメリットがあると感じております。","voiceIndex":235,"id":"exchange-106"},{"speaker":"高橋委員","kind":"質問","question":"この中で、金額が多いものとして、今、排水施設建設事業があるんですが、支出のほうの金額が１１億４,８００万円。収入がたしか１２億２００万円ぐらいなんですが、収入のほうが多いわけでありますけれども、この差はどうなるんでしょうか。","respondent":"家壽田下水道河川課長","answer":"先ほどまちづくり事業部長のほうからもご説明したと思いますけれども、受託事業費に我々の人件費やさまざまな経費を受託に乗っけまして、それで受託事業収入のほうが上回っているです。","voiceIndex":238,"id":"exchange-107"},{"speaker":"高橋委員","kind":"質問","question":"建設型のところだけ、先ほどのお話ではないんですが、「等」がついてないんですけれども、上の２つは「等」がついているんですが、これはどのようなことが含まれるんでしょうか。管理運営委託でどのようなことをやられているか。一般のマンションなどの管理というような感じで受け取ってもよろしいのでしょうか。","respondent":"齋藤住宅課長","answer":"「等」につきましては、すいません、おわび申し上げます。１４９ページを見ますと、「管理運営委託等」、下は「管理運営等委託」と書いてございまして、「等」の位置がずれておりますが、ちょっとニュアンスが、気持ちが違いますので、お許しをいただきまして。すいません。","voiceIndex":242,"id":"exchange-108"},{"speaker":"高橋委員","kind":"意見","question":"区民住宅のほうは、共益費を１万円さらにとっているんですが、このように比べることがどうか、あれですけれども、区民住宅と区営住宅で差が出てくるのかということと、あと、これは民間の管理と比べて、どういう評価をされているのか、お願いしたいと思います。","respondent":"齋藤住宅課長","answer":"民間と比べてどうかですが、基本的に三井不動産、ベニーエステートサービスという不動産の専門の法人に委託しておりますので、民間と比べても極めて遜色のない水準でサービスを提供させていただいていると考えています。","voiceIndex":244,"id":"exchange-109"},{"speaker":"高橋委員","kind":"意見","question":"指定管理者制度を否定するわけではありませんが、モニタリングのシステムも導入されておりますので、今後も適切な管理をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":246,"id":"exchange-110"},{"speaker":"若林委員","kind":"質問・要望","question":"私は、１４１ページの街路樹整備、１４２ページの道路バリアフリー、それから、時間があれば、１４６ページの都市開発、３点伺いたいと思います。それで、そこから、そもそも植栽、植樹、街路樹の全体の計画というんでしょうか、植栽をまず何本植える、樹種を選定する、そこから通常の維持管理、一連の計画というものが、マニュアルみたいなのがあると思うんですが、そこら辺のお話を伺いたいと思います。","respondent":"松代管理工事課長、藤田道路公園課長","answer":"新しく植わるところは、都市計画道路として今後整備する予定のところ。例えば補助１６３号線、補助２０５号線、そういったところでは、公幅員の中に歩道を設けて街路樹を植えていく計画はあります。東京都では、最近職員提案で、東京都のほうで賞をいただいたような形の管理のマニュアルみたいなものも作成していますので、そういったものも参考にしながら、区のほうでは。","voiceIndex":248,"id":"exchange-111"},{"speaker":"若林委員","kind":"質問・要望","question":"そうしますと、区道のほうでは、もうこれ以上増える余地はないというふうに今お聞きいたしましたけれども、確認をします。それから、区内には、当然国道、都道があります。そこら辺、区民ニーズに応じた計画、また国と都、ここら辺の連携、区のほうからご要望するとか、また逆に、区と都ではこういう計画を立てていますというところがあれば、お知らせをいただきたいと思います。","respondent":"松代管理工事課長","answer":"オリンピック誘致だとか、いろいろとそういった将来を見込んでまちづくりを進めたいということで、既存の道路の中に植栽がもう既にあるんですけれども、それを何とかもう一歩工夫して、緑化等を広げたいという考えを聞いてあります。","voiceIndex":251,"id":"exchange-112"},{"speaker":"若林委員","kind":"質問・要望","question":"街路樹の維持管理に関して、剪定のお話が午前中にもたしかございました。改めて伺いたいと思うんですが、剪定の仕方について１つご要望がありまして、これも高木の話ですが、剪定をする際には、木のてっぺんから、下枝、枝の下のほう、これはまとめて剪定されるわけですけれども、下の枝のほうの高さ、これをどういうふうに設定されているかということなんです。その改善点について教えていただきたい。","respondent":"藤田道路公園課長","answer":"ただ、現地の状況等がある中で、東京都のほうでもいろいろ判断をして、管理されていると思いますので、補助２６号線の街路樹の管理については、私どものほうからも東京都のほうにお話をしておきたいと考えています。","voiceIndex":253,"id":"exchange-113"},{"speaker":"若林委員","kind":"質問・要望","question":"わかりました。先ほども、平成９年のやさしいまちづくり計画の改定に向けてというお話もございました。それから、信号の秒数が１５秒ぐらいしかなくて、上って四苦八苦している間に信号が赤になっちゃうということがございました。これについて、総合的にまちづくりの観点、またはその策定等もありますが、区内のこういう障害者の方に対するバリアフリーの考え方を確認させていただきたいと思います。","respondent":"松代管理工事課長、松嶋交通安全担当課長、阿部都市計画課長","answer":"そういった改修にあわせて、少しでも車いすの方、加えて、高齢者の方が歩きやすいような道路整備を今、進めているところです。信号の関係です。高齢者、障害者に対応するために、ボタンを押すと青秒数が延伸するシステムの信号があります。委員の指摘を踏まえまして、当該箇所を調べまして、第二建設事務所に必要な申し入れをしていきたいと考えています。","voiceIndex":255,"id":"exchange-114"},{"speaker":"若林委員","kind":"質問・要望","question":"区と都ということで、当然地域に密着した区の考え方が都の考え方に優先すると理解しておりますので、今後都への要望と、また策定の中でも、国と都と区の３者の連携で、円滑にバリアフリーのまちづくり、ユニバーサルのまちづくりが前進しますように、お願いを申し上げまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":259,"id":"exchange-115"},{"speaker":"鈴木（真）委員","kind":"確認","question":"大井町駅周辺地区開発計画、これは平成１８年の予算特別委員会で質問させていただいて、もう一度確認なんですが、整備計画として、都市再生公社に委託して、たしか２,０００万円だと思いましたけど、この結果というか、現在経過になるのかな、初期的段階ということですが、その当時初期的段階ということでお話があったんですが、どのような経過状況になっているかということを教えてください。","respondent":"松代管理工事課長、家壽田下水道河川課長、青木都市開発課長、松嶋交通安全担当課長","answer":"そういった意味では、再度調べまして、そういったものへの対応を考えていきたいと考えているところです。やはり用地確保が難しいということで、できればなるべく緩やかな護岸の傾斜にしたいところですが、これがどうしても直立的な護岸になってしまうです。過去３年にわたって検討してまいりましたＪＲと共同でやってきたまちづくりの検討ですけれども、結論から申し上げますと、最終結論ではないんですが。パトカーだとか、そういったもので指導していますけれども、今後もまた引き続き強化していきたい。","voiceIndex":261,"id":"exchange-116"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１４８ページの中高層建築物開発指導費についてお聞かせいただきたいと思います。ワンルームのマンションの建設についてなんですが、９月２８日の日本経済新聞で、「ワンルーム乱立待った。都内自治体、広がる規制。具体的に年間何戸建築されているのか。それから、ワンルームが新築マンションの戸数の何％になっているのか。そして、全世帯に占める単身住宅の割合について教えていただきたい。","respondent":"齋藤住宅課長","answer":"ところが、平成１４年からワンルームの戸数が増えてまいりまして、建設の棟数が、平成１４年が３５棟、数が１,３９８戸、平成１５年が２８棟で１,３４１戸、平成１６年が２６棟で１,３９１戸、平成１７年が３９棟で、１,８０４戸です。","voiceIndex":267,"id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"マンションのファミリータイプの中で、ワンルームの戸数が何割ぐらいになっているかというのは、データとしてないでしょうか。そしてまたその中身についても、区として把握しているところがあったら、教えていただきたいと思います。","respondent":"齋藤住宅課長","answer":"それで、各区の規制を先に答弁をさせてください。各区のワンルームの規制は、条例がある区が９区あります。９区ございまして、先ほど委員からご指摘のありました荒川区を契機に、４、５区、規制をする方向で検討していると聞いております。","voiceIndex":269,"id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つは、ワンルームの規定についても、品川区は１８m2から２９m2という規定をしていると思うんですが、多くのところが２５m2以上という形の規定をしていまして、東京都の単身者の、最低、健康で文化的な住生活を営む、人としての不可欠な住宅の面積、そういうふうなところで、多分２５m2というのが出ていると思うんですが、そこら辺のところでも。","respondent":"齋藤住宅課長","answer":"こういうことを考えておりまして、調査ものとかが来ております。その２５m2がいいのか、あるいは２０m2にして、年金で払えるぐらいの広さにしたほうがいいのか。これは今、十分検討しておりまして、近々、きちんとしたものをお示しできると考えております。","voiceIndex":271,"id":"exchange-119"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ地域の方の要望が入れられる改定をぜひお願いしたいということと、それから、荒川区に私もお話をお聞きしたんですけれども、それまでも附置義務とかはあったけれども、その要綱でつくられていたと。それから、あとは、建築主が説明会に出席しなければならない。こういうところで改正をしているんですけれども、ぜひこういう改正も行っていただきたいと思うんですが、そのことについてもお聞かせください。","respondent":"齋藤住宅課長","answer":"実態がなかなか難しい。いろいろ特定の会社をつくったりとかしまして。ただ、私どもの区といたしましては、厳しく呼びつけたり、行ったりとかしておりまして、説明会も、委員ご存じのとおり、夜、休日を含めてやらせていただいていますので、引き続きご指導します。","voiceIndex":273,"id":"exchange-120"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それと、あとは、要綱でも、条例と変わらないような指導をするということですけれども、実際は、要綱でなかなか、本当に業者が、モラルがどうなのかというふうなところが増えてきて、というのが荒川区のお話だったんですけど、それで条例をつくっている区が既に９区あって、その後も条例をつくっていく、検討しているという区があるということであれば、私はやはり要綱よりは条例のほうが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":277,"id":"exchange-121"},{"speaker":"石田（慎）委員","kind":"質問","question":"私のほうからは、成果報告書１４２ページ、一番下の商店街電線類地中化事業についてお伺いをします。平成１７年度の決算で、１億１,７００万円で、平成１８年度、２億５,６００万円。平成１９年度の予算、６９万８,４２２円。決算と予算額がそれぞれ出ているんですが、この内容と、現在までの品川区においての電線類地中化事業はどのように行われていたのか、教えてください。","respondent":"松代管理工事課長","answer":"私どもで、今、商店街のほうの電線類地中化を進めておりますのは、こういった街路事業の電線類地中化とは、またちょっと目的を変えまして、商店街の活性化を支援するということとあわせて、景観上、交通安全上の部分、また、防災機能の強化といった目的で進めているものです。","voiceIndex":280,"id":"exchange-122"},{"speaker":"石田（慎）委員","kind":"意見","question":"アメリカでも、大都市では、電柱の地中化というのがかなり進められていて、ヨーロッパでも、ロンドンやパリでは、無電柱化率が１００％。それと、地震が起きたときに、これは阪神・淡路大震災のときに、既にわかっていることですが、地中化された電線は、上にある電線より破損しにくい。もし展望というか、今後のお考えがありましたら、お聞かせください。","respondent":"松代管理工事課長","answer":"これにつきましては、電線類の地中化をぜひやりたいということで、ただ、電線類の地中化だけでは避難道路の機能は得られませんので、今、地域に入りまして、４回ほど説明会を開いておりますが、地区計画等とも、地域の方とお話をしながら、道路幅員を少し広げ。","voiceIndex":282,"id":"exchange-123"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ほかの家等が倒れて、その影響で電柱が倒れたと伺っていますが、電柱があることによって、そういった意味でも、危険性がまた高まってしまうので、ぜひとも、重点地域を決めていただいて、その中で地中化を進めていただければなと。これはあくまで要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":284,"id":"exchange-124"},{"speaker":"松澤委員","kind":"質問・要望","question":"３点、お聞きします。１点目が、成果報告書の１４１ページ、道路新設改良費に入るのでしょうか、第６次の品川区総合実施計画の中で、踏切ですけれども、平成１９、２０、２１年度と、すべて踏切改良の検討と書かれていたんですが、補正予算の中で、国の緊急対策踏切というんでしょうか、補助金、支出金が出ると伺いました。それと、もう一つ、１６３号線の一本橋までの、本当に期限内に間に合うのかどうか。","respondent":"松代管理工事課長、浜脇街路事業担当課長、阿部都市計画課長、家壽田下水道河川課長","answer":"私ども、具体的な中身としてできることは、例えば対策の方法として、賢い踏切として、踏切のカラー化、または構造改良、少しでも拡幅するようなもの。残っている土地区画に若干の土地が取得できないものですから、大々的な工事ができないということがありますので、うまく街区を分けながら。委員お尋ねの２６号線の件ですけれども、事業認可は、確かに委員がおっしゃるとおり、平成２１年度までとってあります。８月２７日に説明会を開催いたしまして、出席者は８名と、大変少のうございましたが、２時間。","voiceIndex":286,"id":"exchange-125"},{"speaker":"松澤委員","kind":"質問・要望","question":"踏切の件です。いつごろできるのかというのをお聞きしたいと思います。それと、１６３号線の件は、わかりました。２６号線が厳しいという、厳しいの意味がちょっとあれですけど、厳しいということで、まちの人にもお伝えしたいと思います。本当に待ちに待った、４,８００ｔの工事ができましたので、通常の夕立なら大丈夫かなと思いますけど、さらに頑張っていただきたいと思います。お答えをお願いします。","respondent":"松代管理工事課長","answer":"これにつきましては、例えば苗木原踏切ですけれども、いろいろと地域からも、議会からも陳情等、拡幅も含めて、要望等が挙がっているものと十分認識しております。下神明１号に当たりましては、今、密集のほうでのまちづくりを行っている。そういった中にある踏切です。","voiceIndex":291,"id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"１４１ページの街路樹整備費と、それから区民住宅費についてお伺いいたします。ただ、要望として聞いておりますのは、場所によってということになるでしょうけれども、道路に面しているところのお宅のところの樋のところに落ち葉がいっぱいたまってしまうということなんですね。区との関係ですね。そうすると、今後どういう形で修繕等々をしなければならないのかということについて、お伺いいたします。","respondent":"藤田道路公園課長、齋藤住宅課長","answer":"剪定の工事というか、委託をする際には、当然地域の方々には、工事に入りますよというお知らせをいたしますので、その中でいろんな声を聞きながら、私どものほうとしては進めていきたいと考えています。指定管理者も、維持修繕はいたしませんので、具体的に申し上げますと、入居者の決定、滞納督促、いろいろ日常的なトラブルが発生したときに、指定管理者が対応し、一時修繕の業者は、オーナーが自分で業者を見つけて、直す。","voiceIndex":294,"id":"exchange-127"},{"speaker":"西本委員","kind":"質問・要望","question":"街路樹のほうは、やはり剪定のときの機会がよろしいかと思いますので、希望があったらということで、問いかけていかないと、住民から要求がなかなか出づらいというところがありますので、そこは区として何かご要望があればとか、そういう樋の清掃等々のところでご要望があればという形で、投げかけをぜひしていただきたいと考えています。","respondent":"齋藤住宅課長","answer":"そのような住宅は、８年後、１０年後になりますので、そのときの住宅事情、品川区、同じように区民住宅として持っていたほうがいいかどうか。これはそのとき、しかるべき時期、しかるべきときに、議会にご相談をしながら決めたほうがいいのだろうと考えております。","voiceIndex":297,"id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"国の規制が非常に厳しいというところでは、区の立場としても難しいのかなと思います。その中で、２０年経ってしまったから、契約が切れてしまったから、では、自由におたくのほうでやってくださいよというふうに手を離してしまうというのも、どうなんだろうと思います。区として必要なところは転用するとかというところのことも考えて、進めていただきたいと考えますが、いかがでしょうか。","respondent":"齋藤住宅課長","answer":"オーナーとしては、同じように引き続きという方もいらっしゃいますし、改めて自分で資産として純粋に活用したい、こういう考えの方もいらっしゃいますので、今後、８年後、１０年後、住宅施策との絡みを考えながら、十分にお話をさせていただこうと思います。","voiceIndex":299,"id":"exchange-129"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ、国の制度がどうなっているかということも含めて、十分に話をして、今後も一緒に考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":301,"id":"exchange-130"},{"speaker":"三上委員","kind":"質問","question":"成果報告書の１４０ページ、駅周辺等放置自転車対策事業、１４２ページ、都市計画道路整備事業。時間がありましたら、１４９ページの区営住宅管理費のアスベスト除去費ということでお伺いしたいと思います。こういう署名の用紙であったわけでありますけれども、この間、東急電鉄との交渉、そして、現状について、品川区としてはどういうふうに受けとめられているか、お伺いをしたいと思います。","respondent":"浜脇街路事業担当課長","answer":"東急からの今日現在の答えなんですけれども、残りが約２００台分ぐらいの駐輪場をつくるスペースを持っていると。その中で検討していきたいです。私どものほうとすれば、予定といいますか、やる時期、それについては、早く回答するようにということで、求めているものです。","voiceIndex":303,"id":"exchange-131"},{"speaker":"三上委員","kind":"質問","question":"現状、今、どうなっているか。何回もこういう状況にありますよということをお伝えしてきているんですけれども、公衆トイレ側のところにバイクが１０台ぐらいは置いてある。多いときは２０台ぐらい置いてありますよ。道路にバイクを置いていいんですよという、そういうことの、逆に、１つのいい例になってしまう。こういうことについても、本当にどう思うのか。もう一度お伺いいたします。","respondent":"松嶋交通安全担当課長、浜脇街路事業担当課長","answer":"不動前駅につきましても、大崎署とこれまで３回ほど、バイクの取り締まりについては警察のほうで、自転車の撤去については区のほうでということで、やってきている中ですけれども、今後も、引き続きそういった撤去活動、啓発活動は。私どもとすれば、今、委員がおっしゃったような状況というのは、私自身も見てきておりますので、強く働きかけたんですが、今日現在の回答がこういう状況だですので、今後とも強く働きかけるということをお約束したいと思います。","voiceIndex":305,"id":"exchange-132"},{"speaker":"三上委員","kind":"確認","question":"ということは、私ども、区民の皆さんの力を借りて、また別の運動をしなければ解決しない。今日は、こういうふうに受けとめておきますよ。改めて取り組みたいと思います。都市計画道路の件でありますけれども、午前中も出ました。補助２６号線の平塚橋交差点のところで、今、改良工事を行うという説明がありましたけれども、もう一度、スケジュールの点を確認させてください。２６号線拡幅のことについて。","respondent":"阿部都市計画課長","answer":"午前中にもご答弁申し上げましたけれども、左折レーンにつきまして、２０年の３月までに暫定整備をして、左折レーンをつくるです。隅切りの部分につきましては、平成２０年度に用地買収をして、本格整備に入るというふうに聞いてあります。","voiceIndex":308,"id":"exchange-133"},{"speaker":"三上委員","kind":"質問","question":"平成２０年の３月までに左折レーンという、その距離というのは、どこまで考えているんですか。みずほ銀行までの買収した土地で考えるのかどうか。","respondent":"阿部都市計画課長","answer":"区域につきましては、みずほ銀行の前のところと、あと、２６号線については、駐車場がありますよね、みずほ銀行の裏のところ。そこの区間というふうに聞いております。","voiceIndex":310,"id":"exchange-134"},{"speaker":"三上委員","kind":"質問・要望","question":"そういう状況を伺っています。とにかく８月の段階で、みずほ銀行とマンションとの敷地の境界確認立ち会いの打ち合わせのときに、そのとき初めて、同席した東京都の職員が、当マンション側から説明を要請して、今後の話をちょっと聞いたと。そういうような状況の中から、２６号線についても、平成１７年の１０月ですか、初めて住民説明会をやった。どうぞこの点だけもう一度ご答弁いただきたい。","respondent":"阿部都市計画課長","answer":"確かに委員がおっしゃるとおり、地域の方々の協力がなければ進まない事業ですので、私どものほうからも、第二建設事務所に対して、住民の方に丁寧な説明をするように求めてまいります。","voiceIndex":312,"id":"exchange-135"},{"speaker":"須貝委員","kind":"確認","question":"私は、１４７ページ、建設費の建築確認申請と１４５ページの公園新設改良費についてお聞きしたいと思います。どこの担当に何人配属されたのか、お聞かせ願いたい。建物の構造計算偽装事件の問題を二度と起こさないということで、建築確認、そして検査の厳格化を大きな柱とする建築基準法等の一部改正が行われましたが、これはどういうものなのか。その２点についてお聞かせください。","respondent":"片田建築課長","answer":"一応数値的に申し上げますと、区だけで受けた場合、７月から９月の末までという状況の中では、前年比、平成１８年度の同月３カ月間でいきますと、大体５４％ぐらいと。民間に出されたものも含めますと、全体では、前年比の４３％ほど、一応減少してきているという状況です。","voiceIndex":315,"id":"exchange-136"},{"speaker":"須貝委員","kind":"確認","question":"法改正によって、書類上の建築確認検査の手続が、今年の６月２０日から変わりました。これは事実でしょうか。そして、建築確認審査期間も、従来は区の条例でも２１日間以内で建築確認をおろすという話でしたが、２１日間から３５日間に長くなって、そして、最大で７０日間となって、大幅に延びております。いわゆる再申請ですね。１回目の審査で、３５日、最大で７０日かかった。","respondent":"片田建築課長","answer":"今、委員のご指摘がございましたように、今回の法改正の中で、大きく分けて３点ほど改正して行われております。１つは、構造審査を厳密にやろうと。","voiceIndex":317,"id":"exchange-137"},{"speaker":"須貝委員","kind":"確認","question":"建築主も大変困っておりまして、耐震強度に関係ない、階段の位置や窓の位置を変更するだけでも、建築確認の、先ほどの再申請やり直しということで、工事がストップされるわけですから、自然と工事日数が延びる。区民生活にこれだけ影響が起きている。これから新たに家を建てようとする人が大変苦労されている。それに対して、品川区として、どのような対応、対策を考えておられるでしょうか。","respondent":"片田建築課長","answer":"事前の窓口相談、正式に受理した後、適正に円滑に処理が進むように、十分に区民の方の、あるいは相談者のご相談に乗った中で、区のほうとしても円滑に進めていきたいということで、窓口相談の部分で、円滑に進むよう、指導を含めて、対応してきているという状況です。","voiceIndex":319,"id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"国は、６月２０日に法律を施行しましたが、この法改正の解説書が８月１０日に関係者に出回ったというわけです。してください。でも、その中身はどうやって法改正になっているのか、中身は、ほとんどの方が知らされない状態。そして、８月１０日に、この手続審査をこの解説書のとおりに進めてください。そうすると、この５０日間というのは、区としてはどのように対応していたのでしょうか。","respondent":"片田建築課長","answer":"確かに当初の国の説明のニュアンスと、私ども、８月の半ばに国土交通省に呼ばれて、説明を聞きに行ったという部分では、若干当初の法改正の時期とかなりトーンが変わってきてあります。","voiceIndex":321,"id":"exchange-139"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回、二重審査となった構造計算適合性判定機関において、国交省は大臣認定のプログラムを用いれば審査を効率化できるということで、このソフトが公表されていますが、これはいまだにできていなくて、法律施行をしたのに、全く対策がとれていない。そして、ちょっとお聞かせいただきたいんですが、今回の法改正で、あくまで見解としてですが、耐震偽装は防げるとお思いでしょうか。","respondent":"片田建築課長","answer":"それと今回、法改正でそれが防げるかといったご質問ですけれども、なかなか私の口から申し上げるのは難しいところもありますけれども、やはり制度、手続の中で、今回、法が改正された中では、防げることを想定して改正されてありますので、私ども、それを十分確認をしながら。","voiceIndex":323,"id":"exchange-140"},{"speaker":"須貝委員","kind":"確認","question":"確かにまだきちんとした法改正が行き渡っていないので、区としても、判定としては、今後どうなるんだろうというのは、まだまだ疑問点があると思います。私、思うに、前回と同じで、確認申請書面をきちっとつくって、構造計算書もきちっとつくれば、工事現場で、結局手抜きをすれば、今までと何ら変わりはないのかなと。この辺、わかる範囲でいいですから、簡単に教えてください。","respondent":"片田建築課長","answer":"今後引き続いて、いろいろな問題について、私どものほうとしても、前向きに受けとめて、必要な対応を行っていきたいと考えています。","voiceIndex":325,"id":"exchange-141"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に、せっかく平成１８年度も、建築課に構造計算に関する技術者か１人増えたということですが、しばらく手探り状態だと思うんですね。仕事は３件抱えているけれども、できないんだという話も聞いております。しかし、大変水はけが悪くて、使いにくい状況にあり、土壌改良の要請があると聞いておりますが、これについて、どういう状況になっているか、お聞かせください。","respondent":"藤田道路公園課長","answer":"鮫洲のグラウンドの件ですけれども、あちらのグラウンド、大変広いグラウンドになっております。その中で、ある程度の野球だとか、そういったものに対応できるような形での公園整備ということで、本来であれば、ある程度の広さの中で、ますをいっぱいつくりたいんですね。","voiceIndex":327,"id":"exchange-142"},{"speaker":"須貝委員","kind":"意見","question":"ここは、文字どおり、運動公園ということで、品川区もしておりますので、できれば、公園広場、若干ありますが、ここも運動広場にして、全面改良して、多目的運動公園とか、防災広場などにして、地域の人がいろいろ使いやすいような公園にしていただけたらいいのではないかと思うんですが、一言だけ、ご見解をお聞かせください。","respondent":"藤田道路公園課長","answer":"皆さんと一緒によりよい管理をしていって、今後も、無償で開放しているという意味でも、大変意義がある公園だと考えていますので、ご理解のほど、よろしくお願いいたします。","voiceIndex":329,"id":"exchange-143"},{"speaker":"林委員","kind":"質問・要望","question":"関連ということで、１つ聞きます。一番最初の大井プレイス構想のときは、ぼたんのかけ違いというか、人のうちの土地に勝手に手を突っ込みやがってと、非常に激怒をされたんだけど、今回は順序を追って、ＪＲとお話をしてきたと聞いていますけれども、なぜそういう結論というか、中間結論というのか、そういうことになったのか、理由があったら聞かせていただきたい。","respondent":"青木都市開発課長、日下部企画財政課長、松嶋交通安全担当課長","answer":"この検討につきましては、引き続き、大井町全体の区としての考え方をまた新たに持っていく中で、ＪＲの位置づけを明らかにして。実は、監査のほうにあります公園・児童遊園整備で、決算額２億３,２６２万円となっておりますが、実はこれは、成果報告書の１４５ページでまいりますと。見ながら、考えていただくということでやっております。それと、警察のほうでは、各保育園に行きまして、安全教育を実施しています。","voiceIndex":332,"id":"exchange-144"},{"speaker":"林委員","kind":"質問","question":"広町のほうは、道路がいかないというのは、大分前から区側も薄々はわかっていた話で、それ１本しか計画を持たないで交渉をしたというのは、僕はミステイクだと思う。ＪＲのここを何とか大井町、品川の中心にするという信念でいったとすれば。それだけ言っておきます。それから、監査と成果報告書のずれというのは、何ですか、これ。非常に大きいずれですよ。やります。その道路のことだけ聞かせてください。","respondent":"松代管理工事課長","answer":"旗の台のコミュニティーゾーンでも、それは実践して、一定の効果を上げています。ですから、必要な箇所があれば、十分地域の方とお話をしながら、進めていけるものと考えているものです。","voiceIndex":336,"id":"exchange-145"},{"speaker":"川西委員","kind":"質問","question":"道路台帳の整備と、それから公共溝渠の整備事業、そして、１４５ページの公園新設改良、もし時間があれば、さっきも出ていました街路樹のことについて若干触れたいと思います。最初に、道路台帳の整備と公共溝渠の整備事業、金額が低いんですけど、執行状況について教えてください。","respondent":"松代管理工事課長","answer":"公共溝渠のほうですけれども、こちらにつきましては、公共溝渠、基本的には水路です。水路の管理等をする上で、この経費を持ってございまして、今回はその水路を通路化しようとするものの１路線を計上したものです。","voiceIndex":339,"id":"exchange-146"},{"speaker":"川西委員","kind":"質問","question":"違うんですか。私は官民境界の道路整備のことかと思って、どこまで、何％ぐらいがきちっと進んできたのかということを伺いたかったので。見間違えましたか。そうですか。公共溝渠の整備事業については、全面的に区に事業が移管になりまして、整備すべき公共溝渠というのがあると思うんですけど、やや消極的になってきているというので、平成１８年度、何にもしてないということですか。それを伺います。","respondent":"松代管理工事課長","answer":"そういった意味で、整理をし、かつ、通路化できるものは通路化する。水路として機能がないものについては、払い下げをする。そういった作業として進めているものです。","voiceIndex":341,"id":"exchange-147"},{"speaker":"川西委員","kind":"質問","question":"道路台帳のほうは、私の聞き方が悪かったんでしょうか。ちゃんとした中身の説明をお願いいたします。","respondent":"岩田まちづくり事業部長","answer":"道路台帳といいますのは、現況の区が管理している道路の現況図です。これは、境界がどうであれ、現在の道路のＬ型から反対のＬ型までがどれだけあるかというのが５００分の１の縮尺図で、きちっと地図をつくって管理をしております。","voiceIndex":343,"id":"exchange-148"},{"speaker":"川西委員","kind":"質問・要望","question":"わかりました。そういうところは、区の方針で、先ほどから出ていますように、緑化対策として一定の空間の中にそういうふうな、いわゆるオープンスペース、緑化ということを考えながら、もう少し積極的にしてほしいと要望をいたします。完成をいたしました。そういう中で１つ伺いたいのは、鈴ケ森公園の拡張用地取得費の中身を説明していただきたい。それもあわせてご回答願います。","respondent":"松代管理工事課長","answer":"それと、新設に当たりましては、東品川海上公園、今、委員からもお話がありましたように、平成１８年度は新設ということで、設けてあります。平成１８年度の新設公園としては、この１カ所です。","voiceIndex":345,"id":"exchange-149"},{"speaker":"川西委員","kind":"質問","question":"もう少し公園の新設というのは積極的にお願いしたいと思いますが、東品川海上公園、あれは何年も前から長期計画で進めてきたところですので、例えば売地があったから、この辺は少し公園が少ないから、あるいは児童遊園にしたらいいんじゃないかという、その温かい思いやりというのが最近少ないようにも感じられるんですが、いかがでしょうか。それがちょっとここのところ、ないように思います。","respondent":"松代管理工事課長、藤田道路公園課長","answer":"公園設置の考え方ということで、新設公園をです。私ども、公園の設置の基本的な考え方としましては、今現在防災まちづくりを推進しております。そういった中で、密集住宅地市街地整備促進事業ということを面的に、今、推進しています。そういった中で、適切な時期に刈り込みをする、あるいは、除草等を行うということで、心配りをしながら、管理を徹底していきたいと考えています。","voiceIndex":347,"id":"exchange-150"},{"speaker":"宮崎委員","kind":"質問","question":"成果報告書の１４６ページ、都市開発費、広町地区の再開発計画検討委託と１４８ページ、木造住宅の耐震化、１４２ページの都市計画道路整備事業についても、時間があればやりたいと思います。どういう建物がつくれるか。ところが、今の説明では、東西の道路をもう１本つくるとなると、構造的に無理だという話なんですよね。そういう話でしたけれども、また、案をつくっていくということなんでしょうか。","respondent":"青木都市開発課長、岩田まちづくり事業部長","answer":"その結果として、先ほども別の委員の方にもご指摘いただきました、道路計画が１本だけでやったのかというご指摘もありましたが、道路計画についても、ある程度譲歩できるところで。この広町の検討は、この３年間、ほとんどの土地の地主はＪＲ東日本ですけれども、それに対して、ここの開発が大井プレイス構想のように、工場を含めた全体の開発は無理にしろ。","voiceIndex":351,"id":"exchange-151"},{"speaker":"宮崎委員","kind":"質問・要望","question":"この前の本会議との質問の関係で確認したいんですけれども、住宅の耐震化の支援なんですけれども、現在、費用の２分の１を助成するという考え方なんですけれども、それが７５万円なんですが、実態はもうちょっとかかっているというのが実態だと思うんですけれども、東京都、あるいは国のほうも、わりあいもっと多い、そういう話なんですけれども、現在の助成の７５万円。","respondent":"片田建築課長","answer":"ただ、私どものほうとして、建物の耐震化促進ですので、まず建物を基本と置きながらも、そこをあわせて検討できる要素、人の命を守るということで、シェルターを含めた中で、あわせて検討できる要素について検討してまいりたい、このように考えてあります。","voiceIndex":354,"id":"exchange-152"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そうであるならば、家具の転倒防止なんかも、支援をするということを求めているんです。今の高齢者、特に所得の少ない方々の高齢者がどういうつもりでいるのかというところも含めて、私は、実態をよく調査したほうがいいんじゃないかと思うんですよ。私はそこのところぜひ、実態調査なんかをやったらどうかと思うんですけれども、考えをお聞かせいただきたいと思います。","respondent":"岩田まちづくり事業部長","answer":"これも耐震計画上はカウントはできませんけれども、区長の強いご意見で、命を守るというのも１つの大きな柱にしたいということで、今回は計画に載せていただいております。これと家具の転倒防止とは、かなり時限が違いますので……。","voiceIndex":356,"id":"exchange-153"},{"speaker":"堺委員","kind":"質問・要望","question":"私のほうからは、１４２ページの補助１６３号線に関連して、それから、１４７ページの防災生活圏促進事業に関連して、時間がございましたら、同じ１４７ページですが、密集住宅市街地整備促進事業に関連して質問させていただきたいと思います。","respondent":"松嶋交通安全担当課長","answer":"現在、区内では４４カ所ほど音響式の信号機を設置しています。なお、これは、視覚障害者の方の施設があるとか、よく通るとか、そういった場所につきましては積極的に実施をしています。","voiceIndex":361,"id":"exchange-154"},{"speaker":"堺委員","kind":"質問・要望","question":"どうしてもあそこは避けて通れない大事なところですから、ぜひひとつ、希望としては早急に調査をしていただいて、毎回申し上げておるように、未整備区間を何とか早く完成させていただきたい、こういう願いからお尋ねをしているわけですので、その辺につきましても、ぜひひとつお取り組みをお願いしておきたいと思います。それから、２点目の防災生活圏の件です。もしありましたら、お聞かせいただけますか。","respondent":"松代管理工事課長","answer":"この中で、整備した後の反響というご質問ですけれども、まだ直接的には来てございませんが、地域の町会等々のお話を聞きますと、非常に雰囲気もよくなったし、きれいになったという声はお聞きしています。","voiceIndex":365,"id":"exchange-155"},{"speaker":"堺委員","kind":"質問","question":"あそこが、大崎高校側でしょうか、木がしげっているというんでしょうか、そんなので、幾らか暗いかなという印象を受けたんですね。こんな気もしたのと、もう一つあわせて、あの橋、きれいな橋ができたから、あの橋にも何かお名前をつけていただくといいななんて、そんな気もしたんですが、その辺はどうでしょうかね。ちょっと無理な話でしょうか。ちょっとご見解を。","respondent":"松代管理工事課長","answer":"一応照度的には、３ｌxぐらいあるんですが、どうしても周りがうっそうとしている点で、不安に思われるということもありますので、もう少しその辺、安心してご利用いただけるようなものを検討したいと思います。","voiceIndex":367,"id":"exchange-156"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、１４８ページ、木造住宅耐震化助成費をやりますが、その前にちょっと確認をしたいことがありますので、２つだけ教えてください。それから、民地の樹木も、道路上に出ていたりすると、すぐ行きますなんてさっき言ったような気がしたんだけど、そういう体制は、今まで私の感覚では、あまりなかったと思うんだけど、これもそういう体制整備ができたのかどうかだけ確認を。拡大してくれ、どうだこうだと。","respondent":"松代管理工事課長、藤田道路公園課長、片田建築課長","answer":"国文学研究資料館の今後の進め方に関することだと思いますけれども、まず、今年度、整備方針という、これは前回も答弁しましたが。そういうような状況の中で、現地現地を判断する中で、これまで対応してきたものです。したがいまして、時限的かもございませんけれども、平成２７年を目途に、区として施策の方向を決めて進めていきたい、このように考えてあります。","voiceIndex":372,"id":"exchange-157"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もうこれで質問はやめますが、質問の仕方も悪かったかもしれないですが、的確に答えていただきたい。もうこれでやめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":376,"id":"exchange-158"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1284#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":121479,"voices":377}}]);
